  ("check.go", "package teslrt\n\nimport \"fmt\"\n\n// Check is the erased runtime result of a Tesl check. Proof identities remain a\n// compiler concern; runtime retains only success/failure and the checked value.\ntype Check[T any] struct {\n\tvalue   T\n\tstatus  int\n\tmessage string\n\tok      bool\n\t// shape marks \"the JSON is not this shape\" as opposed to \"this value is invalid\"; see\n\t// RejectShape. It is a FLAG rather than a reserved status, because the status is also what\n\t// a leaked rejection writes on the wire, and a sentinel status of 0 there is not a\n\t// response \226\128\148 `WriteHeader(0)` panics.\n\tshape bool\n}\n\nfunc Accept[T any](value T) Check[T] {\n\treturn Check[T]{value: value, ok: true}\n}\n\nfunc Reject[T any](status int, message string) Check[T] {\n\treturn Check[T]{status: status, message: message}\n}\n\nfunc (result Check[T]) OK() bool {\n\treturn result.ok\n}\n\nfunc (result Check[T]) Value() (T, bool) {\n\treturn result.value, result.ok\n}\n\nfunc (result Check[T]) Status() int {\n\treturn result.status\n}\n\nfunc (result Check[T]) Message() string {\n\treturn result.message\n}\n\n// MustCheck unwraps a statically expected successful check and fails closed if\n// a caller ignored rejection propagation.\nfunc MustCheck[T any](result Check[T]) T {\n\tif !result.ok {\n\t\tpanic(fmt.Sprintf(\"Tesl check rejected with status %d: %s\", result.status, result.message))\n\t}\n\treturn result.value\n}\n\n// RequestRejection is a check rejection consumed inside a HANDLER body. It travels as a\n// panic because a handler's Go signature returns its value type, with nowhere to put a\n// failure \226\128\148 and the router turns it back into a response carrying the check's own status.\n//\n// That is the Racket behaviour, not an invention: `dsl/web.rkt` installs the\n// raise-on-escaping-failure wrapper for every function kind EXCEPT `handler`, so a\n// rejection reached in a handler body flows out as the response's status (422, 404, \226\128\166)\n// rather than as a server error. Reporting 500 there would turn \"you sent an invalid age\"\n// into \"this server is broken\".\ntype RequestRejection struct {\n\tStatus  int\n\tMessage string\n}\n\n// MustCheckRequest is `MustCheck` at the request boundary: same unwrapping, but a rejection\n// answers the client instead of crashing the request.\nfunc MustCheckRequest[T any](result Check[T]) T {\n\tif !result.ok {\n\t\tpanic(RequestRejection{Status: result.status, Message: result.message})\n\t}\n\treturn result.value\n}\n\n// RejectShape reports that the JSON simply is not this shape \226\128\148 a missing or mistyped field \226\128\148\n// as opposed to a VALIDATION failure from a `via` or cross-check, which carries the status the\n// check itself chose.\n//\n// The distinction is load-bearing when a codec has several alternatives. Racket's\n// registry loop treats a raised decode exception as \"try the next decoder\" while a\n// check failure is remembered (the FIRST one wins) and still lets a later alternative\n// succeed. Collapsing the two would report \"required field \\\"userName\\\" not found\" \226\128\148\n// the last alternative's shape complaint \226\128\148 in place of the real 400 the first\n// alternative's check produced.\n// A shape rejection still carries 400, so a decoder with no alternatives behind it (a DERIVED\n// record decoder) can answer the client with it directly.\nfunc RejectShape[T any](message string) Check[T] {\n\treturn Check[T]{status: 400, message: message, shape: true}\n}\n\n// IsShapeMismatch reports whether a failure means \"not this shape\" rather than \"this\n// value is invalid\".\nfunc (result Check[T]) IsShapeMismatch() bool {\n\treturn !result.ok && result.shape\n}\n");
  ("control.go", "package teslrt\n\n// If evaluates and returns only the branch selected by condition.\nfunc If[T any](condition bool, whenTrue, whenFalse func() T) T {\n\tif condition {\n\t\treturn whenTrue()\n\t}\n\treturn whenFalse()\n}\n\n// Boxed holds a value behind a pointer, and Unboxed reads it back.\n//\n// A RECURSIVE ADT is why these exist: `type Expr = Lit Int | Add Expr Expr` cannot hold an\n// Expr by value in Go (a struct containing itself has no finite size), so a self-referential\n// payload field is a pointer and the emitter goes through these two functions at every\n// construction and every read. Keeping the indirection in one pair of named functions is\n// what makes it invisible in the emitted code's SHAPE: a pattern binding still reads as one\n// call, not as a nil test the reader has to trust.\n//\n// Unboxed traps on a nil pointer rather than answering a zero value. Nothing the emitter\n// produces can construct one \226\128\148 every boxed field is filled by Boxed at construction \226\128\148 so a\n// nil here is a broken invariant, and a fabricated zero Expr would turn it into a silently\n// wrong answer somewhere further along.\nfunc Boxed[T any](value T) *T {\n\treturn &value\n}\n\nfunc Unboxed[T any](boxed *T) T {\n\tif boxed == nil {\n\t\tpanic(\"recursive value: a payload field was never filled\")\n\t}\n\treturn *boxed\n}\n");
  ("crypto.go", "package teslrt\n\nimport (\n\t\"crypto/hmac\"\n\t\"crypto/rand\"\n\t\"crypto/sha256\"\n\t\"crypto/sha512\"\n\t\"encoding/base64\"\n\t\"encoding/hex\"\n\t\"fmt\"\n\t\"os\"\n\t\"strings\"\n)\n\n// `Tesl.Crypto`: message authentication, digests and tokens.\n//\n// Every primitive here is Go's standard library, and each one is the same primitive the Racket\n// runtime calls into libsodium for \226\128\148 HMAC-SHA256, SHA-256, SHA-512, the OS CSPRNG \226\128\148 so a value\n// produced by one backend verifies on the other. What is NOT here is password storage\n// (`hashPassword`/`checkPassword`/`needsRehash`): Racket uses libsodium's Argon2id, Go's\n// standard library has no Argon2, and matching it means taking on\n// `golang.org/x/crypto/argon2` \226\128\148 a dependency decision, not an implementation detail, since a\n// PBKDF2 substitute would produce hashes the Racket side cannot verify. The emitter refuses\n// those three by name until that is decided.\n//\n// The SHAPE of the surface is the security argument, and it is preserved exactly:\n//\n//\ta Signature cannot be compared          \226\128\148 only `CheckSignature` consumes one, and it\n//\t                                          compares in constant time, so the classic\n//\t                                          timing-unsafe `==` on a MAC tag is unwritable;\n//\ta Secret cannot be printed              \226\128\148 it holds a SecretString, which redacts;\n//\tthe transport forms are one-way pairs   \226\128\148 hex/base64 in and out, because a tag is public\n//\t                                          data that travels in a header.\n\n// Secret is the stdlib's own secret: what `requireSecret` answers. It is a secret NEWTYPE\n// like any a program declares, so it prints as \"[redacted]\", compares in constant time, and\n// reaches an outbound header only through `HttpClient.bearer`/`secretHeader`.\ntype Secret struct {\n\tValue SecretString\n}\n\n// Signature is an opaque MAC tag, held as lowercase hex \226\128\148 the same representation the Racket\n// runtime keeps, so a tag crossing between them is the same string.\ntype Signature struct {\n\tValue string\n}\n\n// RequireSecret is `requireSecret`: the environment value, or a trap. An unset variable is a\n// configuration error, so it fails at the read rather than flowing on as an empty secret.\nfunc RequireSecret(name string) Secret {\n\tvalue, present := os.LookupEnv(name)\n\tif !present || value == \"\" {\n\t\tpanic(fmt.Sprintf(\"requireSecret: environment variable %s is not set (or is empty)\", name))\n\t}\n\treturn Secret{Value: MakeSecret(value)}\n}\n\nfunc hmacSha256Bytes(key, data string) []byte {\n\tmac := hmac.New(sha256.New, []byte(key))\n\t_, _ = mac.Write([]byte(data))\n\treturn mac.Sum(nil)\n}\n\n// SignWith is `Crypto.signWith key payload`: HMAC-SHA256, configuration first and subject\n// last, so `payload |> signWith key` reads correctly.\nfunc SignWith(key Secret, payload string) Signature {\n\treturn Signature{Value: hex.EncodeToString(hmacSha256Bytes(key.Value.Reveal(), payload))}\n}\n\n// CheckSignature is `Crypto.checkSignature key sig payload`. The constant-time compare lives\n// in here, where it cannot be got wrong \226\128\148 which is why there is no `constantTimeEquals` on the\n// surface at all. A malformed tag fails the verification cleanly rather than trapping: it\n// arrived from a header, so it is untrusted input, not a program error.\nfunc CheckSignature(key Secret, sig Signature, payload string) Check[string] {\n\texpected := hmacSha256Bytes(key.Value.Reveal(), payload)\n\tactual, err := hex.DecodeString(sig.Value)\n\tif err != nil || !hmac.Equal(expected, actual) {\n\t\treturn Reject[string](401, \"signature does not match\")\n\t}\n\treturn Accept(payload)\n}\n\n// SignatureHex is the transport form: a tag you produced, for a header or a body. A MAC tag is\n// public data, so this is not an unwrap of a secret \226\128\148 but it DOES make\n// `signatureHex a == signatureHex b` expressible, which is the timing-unsafe comparison, and\n// that is what the SEC002 diagnostic is for.\nfunc SignatureHex(sig Signature) string { return sig.Value }\n\n// SignatureFromHex is the inbound half: a webhook's tag arrives as hex in a header. Parsing\n// untrusted input is safe here \226\128\148 the result can still only be consumed by a verification.\nfunc SignatureFromHex(text string) Signature { return Signature{Value: text} }\n\n// SignatureBase64 is the base64 transport form (Standard Webhooks puts the tag in\n// `webhook-signature: v1,<base64>`).\nfunc SignatureBase64(sig Signature) string {\n\traw, err := hex.DecodeString(sig.Value)\n\tif err != nil {\n\t\t// The tag came from `signatureFromHex` on untrusted input; re-encoding it is not the\n\t\t// place to fail, and an unparseable tag has no base64 form.\n\t\treturn \"\"\n\t}\n\treturn base64.StdEncoding.EncodeToString(raw)\n}\n\n// SignatureFromBase64 is the inbound half for a base64 tag. Malformed input yields a tag that\n// cannot match any MAC, so the verification fails cleanly \226\128\148 the Racket side's decoder is\n// lenient in the same direction (it never turns bad input into an error the program sees).\nfunc SignatureFromBase64(text string) Signature {\n\traw, err := base64.StdEncoding.DecodeString(strings.TrimSpace(text))\n\tif err != nil {\n\t\treturn Signature{}\n\t}\n\treturn Signature{Value: hex.EncodeToString(raw)}\n}\n\n// Fingerprint is `Crypto.fingerprint`: a stable content digest for ETags, cache keys, dedup\n// and idempotency keys. NOT for passwords \226\128\148 a fast digest of a password is exactly the mistake\n// `hashPassword` exists to prevent.\nfunc Fingerprint(content string) string {\n\tsum := sha256.Sum256([]byte(content))\n\treturn hex.EncodeToString(sum[:])\n}\n\n// keyFingerprintLabel is hashed in so a key fingerprint can never coincide with\n// `Fingerprint` of the same string. The trailing NUL is part of the label, as on the Racket\n// side, so the two backends produce the same fingerprint for the same key.\nvar keyFingerprintLabel = []byte(\"tesl-key-fingerprint-v1\\x00\")\n\n// KeyFingerprint answers \"did I load the right key?\" \226\128\148 a short identifier that is safe to log.\n// Truncated to 8 bytes so it reads as an identifier rather than as something to compare\n// cryptographically; it is NOT proof of key possession.\nfunc KeyFingerprint(key Secret) string {\n\tsum := sha256.Sum256(append(append([]byte{}, keyFingerprintLabel...),\n\t\t[]byte(key.Value.Reveal())...))\n\treturn hex.EncodeToString(sum[:8])\n}\n\n// RandomToken is 256 bits from the OS CSPRNG, base64url with no padding (43 characters).\n// There is deliberately no length parameter: a caller who can pass 4 will.\nfunc RandomToken() string {\n\tbuffer := make([]byte, 32)\n\tif _, err := rand.Read(buffer); err != nil {\n\t\tpanic(\"Crypto.randomToken: no source of randomness: \" + err.Error())\n\t}\n\treturn base64.RawURLEncoding.EncodeToString(buffer)\n}\n\n// The expert aliases: the friendly names above are the ones a newcomer can pick correctly, and\n// these exist so someone who already knows what they want can say it.\n\nfunc Sha256Hex(content string) string { return Fingerprint(content) }\n\nfunc Sha512Hex(content string) string {\n\tsum := sha512.Sum512([]byte(content))\n\treturn hex.EncodeToString(sum[:])\n}\n");
  ("dict.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"slices\"\n)\n\n// Dict is Tesl's `Dict k v`, held as entries kept SORTED BY KEY.\n//\n// Two forces pick this representation over a Go map. First, a Go map cannot be keyed\n// by teslrt.Int at all \226\128\148 it is deliberately non-comparable \226\128\148 so a map would need an\n// emitter-supplied key encoding and would still store the original key alongside it.\n// Second, and more important: Go randomises map iteration order per run, while the\n// Racket backend iterates a hash whose order is unspecified but stable within a run\n// (tesl/dict.rkt uses `hash-keys` and `in-hash`, and says so: \"hash has no order\").\n// Emitting raw map order would therefore make a Tesl program's output differ between\n// runs of the SAME binary \226\128\148 strictly worse than the Racket behavior. Sorted order is\n// deterministic, reproducible, and a defensible reading of an operation the language\n// leaves unspecified.\n//\n// Costs, accepted: lookup is O(log n) rather than O(1), and insert is O(n) because a\n// Tesl Dict is immutable and every write copies (the same rule as List \226\128\148 see list.go).\n// Racket's persistent hash is asymptotically better; Tesl dicts are typically small\n// (headers, cookies, config) and this keeps the runtime auditable.\n//\n// Ordering is supplied by the emitter, which knows the concrete key type at every call\n// site \226\128\148 the same device used for list equality and sorting.\ntype Dict[K any, V any] struct {\n\tEntries []DictEntry[K, V]\n}\n\ntype DictEntry[K any, V any] struct {\n\tKey   K\n\tValue V\n}\n\nfunc DictEmpty[K any, V any]() Dict[K, V] {\n\treturn Dict[K, V]{}\n}\n\nfunc DictSize[K any, V any](d Dict[K, V]) Int {\n\treturn FromInt64(int64(len(d.Entries)))\n}\n\nfunc DictIsEmpty[K any, V any](d Dict[K, V]) bool {\n\treturn len(d.Entries) == 0\n}\n\n// dictSearch returns the entry index for key, and whether it was present.\nfunc dictSearch[K any, V any](d Dict[K, V], key K, less func(K, K) bool) (int, bool) {\n\treturn slices.BinarySearchFunc(d.Entries, key, func(entry DictEntry[K, V], key K) int {\n\t\tswitch {\n\t\tcase less(entry.Key, key):\n\t\t\treturn -1\n\t\tcase less(key, entry.Key):\n\t\t\treturn 1\n\t\tdefault:\n\t\t\treturn 0\n\t\t}\n\t})\n}\n\nfunc DictLookup[K any, V any](d Dict[K, V], key K, less func(K, K) bool) Maybe[V] {\n\tif index, found := dictSearch(d, key, less); found {\n\t\treturn Something(d.Entries[index].Value)\n\t}\n\treturn Nothing[V]()\n}\n\nfunc DictMember[K any, V any](d Dict[K, V], key K, less func(K, K) bool) bool {\n\t_, found := dictSearch(d, key, less)\n\treturn found\n}\n\n// DictInsert replaces any existing entry for key. It is a WRITER, so it allocates\n// rather than touching the caller's entries.\nfunc DictInsert[K any, V any](d Dict[K, V], key K, value V, less func(K, K) bool) Dict[K, V] {\n\tindex, found := dictSearch(d, key, less)\n\tif found {\n\t\tentries := make([]DictEntry[K, V], len(d.Entries))\n\t\tcopy(entries, d.Entries)\n\t\tentries[index] = DictEntry[K, V]{Key: key, Value: value}\n\t\treturn Dict[K, V]{Entries: entries}\n\t}\n\tentries := make([]DictEntry[K, V], 0, len(d.Entries)+1)\n\tentries = append(entries, d.Entries[:index]...)\n\tentries = append(entries, DictEntry[K, V]{Key: key, Value: value})\n\tentries = append(entries, d.Entries[index:]...)\n\treturn Dict[K, V]{Entries: entries}\n}\n\nfunc DictRemove[K any, V any](d Dict[K, V], key K, less func(K, K) bool) Dict[K, V] {\n\tindex, found := dictSearch(d, key, less)\n\tif !found {\n\t\treturn d\n\t}\n\tentries := make([]DictEntry[K, V], 0, len(d.Entries)-1)\n\tentries = append(entries, d.Entries[:index]...)\n\tentries = append(entries, d.Entries[index+1:]...)\n\treturn Dict[K, V]{Entries: entries}\n}\n\n// DictUnion is LEFT-BIASED: a key in both dicts keeps the left dict's value, which is what\n// `hash-union #:combine (lambda (_v2 v1) v1)` does in tesl/dict.rkt. Both operands are already\n// in key order, so this is a merge rather than a series of inserts \226\128\148 O(n+m) against O(n log m).\nfunc DictUnion[K any, V any](left, right Dict[K, V], less func(K, K) bool) Dict[K, V] {\n\tentries := make([]DictEntry[K, V], 0, len(left.Entries)+len(right.Entries))\n\tleftAt, rightAt := 0, 0\n\tfor leftAt < len(left.Entries) && rightAt < len(right.Entries) {\n\t\tleftKey := left.Entries[leftAt].Key\n\t\trightKey := right.Entries[rightAt].Key\n\t\tswitch {\n\t\tcase less(leftKey, rightKey):\n\t\t\tentries = append(entries, left.Entries[leftAt])\n\t\t\tleftAt++\n\t\tcase less(rightKey, leftKey):\n\t\t\tentries = append(entries, right.Entries[rightAt])\n\t\t\trightAt++\n\t\tdefault:\n\t\t\t// The same key on both sides: the left value wins, and the right one is dropped.\n\t\t\tentries = append(entries, left.Entries[leftAt])\n\t\t\tleftAt++\n\t\t\trightAt++\n\t\t}\n\t}\n\tentries = append(entries, left.Entries[leftAt:]...)\n\tentries = append(entries, right.Entries[rightAt:]...)\n\treturn Dict[K, V]{Entries: entries}\n}\n\n// sameKey is equality derived from the ordering the emitter supplies: neither key\n// orders before the other.\nfunc sameKey[K any](left, right K, less func(K, K) bool) bool {\n\treturn !less(left, right) && !less(right, left)\n}\n\n// DictKeys, DictValues, and DictToList all iterate in key order, so a Tesl program's\n// output does not depend on which backend ran it or on Go's map seed.\nfunc DictKeys[K any, V any](d Dict[K, V]) []K {\n\tkeys := make([]K, len(d.Entries))\n\tfor index, entry := range d.Entries {\n\t\tkeys[index] = entry.Key\n\t}\n\treturn keys\n}\n\nfunc DictValues[K any, V any](d Dict[K, V]) []V {\n\tvalues := make([]V, len(d.Entries))\n\tfor index, entry := range d.Entries {\n\t\tvalues[index] = entry.Value\n\t}\n\treturn values\n}\n\nfunc DictToList[K any, V any](d Dict[K, V]) []Tuple2[K, V] {\n\tpairs := make([]Tuple2[K, V], len(d.Entries))\n\tfor index, entry := range d.Entries {\n\t\tpairs[index] = Tuple2[K, V]{Tuple2First: entry.Key, Tuple2Second: entry.Value}\n\t}\n\treturn pairs\n}\n\n// DictFromList lets LATER duplicates win, matching tesl/dict.rkt's `for/hash`.\n//\n// Sorted once rather than inserted one at a time: n inserts would be O(n\194\178), where a\n// stable sort plus a dedup pass is O(n log n). Stability is what makes \"later wins\"\n// well defined \226\128\148 equal keys keep their input order, so the last of each run is the\n// one to keep.\nfunc DictFromList[K any, V any](pairs []Tuple2[K, V], less func(K, K) bool) Dict[K, V] {\n\tentries := make([]DictEntry[K, V], len(pairs))\n\tfor index, pair := range pairs {\n\t\tentries[index] = DictEntry[K, V]{Key: pair.Tuple2First, Value: pair.Tuple2Second}\n\t}\n\tslices.SortStableFunc(entries, func(left, right DictEntry[K, V]) int {\n\t\tswitch {\n\t\tcase less(left.Key, right.Key):\n\t\t\treturn -1\n\t\tcase less(right.Key, left.Key):\n\t\t\treturn 1\n\t\tdefault:\n\t\t\treturn 0\n\t\t}\n\t})\n\t// Compacts in place: `entries` was just allocated here, so nothing else can see it,\n\t// and each write lands at an index at or below the one being read.\n\tkept := entries[:0]\n\tfor index := 0; index < len(entries); index++ {\n\t\tlast := index\n\t\tfor last+1 < len(entries) && sameKey(entries[last].Key, entries[last+1].Key, less) {\n\t\t\tlast++\n\t\t}\n\t\tkept = append(kept, entries[last])\n\t\tindex = last\n\t}\n\treturn Dict[K, V]{Entries: kept}\n}\n\n// DictEqualBy compares two dicts entry by entry. Since both are kept in key order, a\n// single pass suffices \226\128\148 no lookup per key. Key and value comparisons are supplied by\n// the emitter, which knows both concrete types at the comparison site.\nfunc DictEqualBy[K any, V any](\n\tleft, right Dict[K, V], keyEqual func(K, K) bool, valueEqual func(V, V) bool,\n) bool {\n\tif len(left.Entries) != len(right.Entries) {\n\t\treturn false\n\t}\n\tfor index := range left.Entries {\n\t\tif !keyEqual(left.Entries[index].Key, right.Entries[index].Key) {\n\t\t\treturn false\n\t\t}\n\t\tif !valueEqual(left.Entries[index].Value, right.Entries[index].Value) {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n\n// stringKeyLess is the ordering a String-keyed Dict is built with \226\128\148 the comparator the emitter\n// passes at every `Dict.lookup` on String keys. It lives here rather than with the HTTP request\n// snapshot that first needed it: `Tesl.JWT`'s claims are a String-keyed Dict too, and a program\n// that signs a token need not serve HTTP.\nfunc stringKeyLess(left, right string) bool { return left < right }\n\n// DictSingleton is `Dict.singleton`: the one-entry dict, which is how a claims dict or a\n// single-key lookup table is usually written.\nfunc DictSingleton[K any, V any](key K, value V) Dict[K, V] {\n\treturn Dict[K, V]{Entries: []DictEntry[K, V]{{Key: key, Value: value}}}\n}\n\n// DictRequireKey is `check Dict.requireKey key d`: it answers the SAME dict, and what a caller\n// gains is the `HasKey` proof that makes `Dict.get` reachable. The proof erases here, so what\n// survives is the rejection \226\128\148 a 400, because a missing key in a request-shaped dict is bad input\n// rather than a broken program.\nfunc DictRequireKey[K any, V any](d Dict[K, V], key K, less func(K, K) bool) Check[Dict[K, V]] {\n\tif _, found := dictSearch(d, key, less); found {\n\t\treturn Accept(d)\n\t}\n\treturn Reject[Dict[K, V]](400, fmt.Sprintf(\"expected key %v to be present in Dict\", key))\n}\n\n// DictGet is `Dict.get`: the value for a key the caller has PROVEN present. The proof is what\n// makes it total, and it erases \226\128\148 so this traps rather than answering a zero value, which is the\n// only honest thing left if a caller ever reached it without the proof.\nfunc DictGet[K any, V any](d Dict[K, V], key K, less func(K, K) bool) V {\n\tif index, found := dictSearch(d, key, less); found {\n\t\treturn d.Entries[index].Value\n\t}\n\tpanic(fmt.Sprintf(\"Dict.get: key %v is not present \226\128\148 a `check Dict.requireKey` must prove it \"+\n\t\t\"first\", key))\n}\n");
  ("env.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"math/big\"\n\t\"os\"\n)\n\n// Reading the environment is an effect Tesl gates behind the `envRead` capability, which\n// the checker enforces; nothing about that survives to run time.\n//\n// An EMPTY variable counts as unset everywhere here, which is what `tesl/private/runtime.rkt`\n// does (`empty-string->false`): `FOO=` and an absent `FOO` are the same answer, so a blank\n// value in a deployment cannot look like a configured one.\nfunc envRaw(name string) (string, bool) {\n\tvalue := os.Getenv(name)\n\tif value == \"\" {\n\t\treturn \"\", false\n\t}\n\treturn value, true\n}\n\n// EnvMaybe is `env`: the value, or Nothing when unset.\nfunc EnvMaybe(name string) Maybe[string] {\n\tif value, ok := envRaw(name); ok {\n\t\treturn Something(value)\n\t}\n\treturn Nothing[string]()\n}\n\n// EnvString is `envString`: the value, or the fallback when unset.\nfunc EnvString(name, fallback string) string {\n\tif value, ok := envRaw(name); ok {\n\t\treturn value\n\t}\n\treturn fallback\n}\n\n// EnvInt is `envInt`: the value parsed as an exact integer, or the fallback when unset. A\n// SET-but-unparseable value is a configuration error and traps \226\128\148 it must not quietly become\n// the fallback, or a typo'd port would look like a deliberate default.\nfunc EnvInt(name string, fallback Int) Int {\n\tvalue, ok := envRaw(name)\n\tif !ok {\n\t\treturn fallback\n\t}\n\tparsed, valid := new(big.Int).SetString(value, 10)\n\tif !valid {\n\t\tpanic(fmt.Sprintf(\"envInt: invalid integer environment value %s=%s\", name, value))\n\t}\n\treturn fromBig(parsed)\n}\n\n// RequireEnv is `requireEnv`: the value, or a trap. An unset variable is a configuration\n// error, so it fails at the read rather than flowing on as an empty string.\nfunc RequireEnv(name string) string {\n\tvalue, ok := envRaw(name)\n\tif !ok {\n\t\tpanic(fmt.Sprintf(\"requireEnv: environment variable %s is not set (or is empty)\", name))\n\t}\n\treturn value\n}\n");
  ("either.go", "package teslrt\n\n// Either is Tesl's `Either a b`: Left carries the error-ish side, Right the value.\n// Like Maybe it lives in the runtime because an Either crosses module boundaries, and\n// it uses the same flat tag+payload shape the emitter generates for a user ADT.\n//\n// The zero value is a Left holding the zero value of A, matching the tag order below.\n// That is deliberate rather than incidental: a zero Either must not read as a Right\n// and hand out a fabricated value.\ntype Either[A any, B any] struct {\n\tTag        EitherTag\n\tLeftValue  A\n\tRightValue B\n}\n\n// EitherTag identifies which side an Either holds. The constants are an enum-like set\n// so the `exhaustive` linter can verify a switch over them.\ntype EitherTag int\n\nconst (\n\tEitherLeft EitherTag = iota\n\tEitherRight\n)\n\n// Left and Right exist for hand-written runtime code and readable tests; emitted code\n// writes the composite literal directly.\nfunc Left[A any, B any](value A) Either[A, B] {\n\treturn Either[A, B]{Tag: EitherLeft, LeftValue: value}\n}\n\nfunc Right[A any, B any](value B) Either[A, B] {\n\treturn Either[A, B]{Tag: EitherRight, RightValue: value}\n}\n\n// IsRight reports which side is held.\nfunc (e Either[A, B]) IsRight() bool {\n\treturn e.Tag == EitherRight\n}\n\n// EitherPartition splits a list of Either into its Left payloads and its Right payloads, in\n// input order, as `Either.partition` does in tesl/either.rkt. It answers the two lists as a\n// Tuple2 rather than two values, because Tesl has no multiple return.\nfunc EitherPartition[A any, B any](values []Either[A, B]) Tuple2[[]A, []B] {\n\tlefts := make([]A, 0, len(values))\n\trights := make([]B, 0, len(values))\n\tfor _, value := range values {\n\t\tif value.Tag == EitherRight {\n\t\t\trights = append(rights, value.RightValue)\n\t\t} else {\n\t\t\tlefts = append(lefts, value.LeftValue)\n\t\t}\n\t}\n\treturn Tuple2[[]A, []B]{Tuple2First: lefts, Tuple2Second: rights}\n}\n\n// The Either combinators, as tesl/either.tesl writes them. The ones taking a FUNCTION\n// (`map`, `mapLeft`, `andThen`) are emitted inline instead \226\128\148 the emitter inlines a callback\n// rather than passing a Go func value, which is the same rule the list leaves follow.\n\nfunc EitherIsLeft[A any, B any](value Either[A, B]) bool {\n\treturn value.Tag == EitherLeft\n}\n\nfunc EitherIsRight[A any, B any](value Either[A, B]) bool {\n\treturn value.Tag == EitherRight\n}\n\nfunc EitherFromLeft[A any, B any](value Either[A, B]) Maybe[A] {\n\tif value.Tag == EitherLeft {\n\t\treturn Something(value.LeftValue)\n\t}\n\treturn Nothing[A]()\n}\n\nfunc EitherFromRight[A any, B any](value Either[A, B]) Maybe[B] {\n\tif value.Tag == EitherRight {\n\t\treturn Something(value.RightValue)\n\t}\n\treturn Nothing[B]()\n}\n\n// EitherWithDefault takes the default FIRST, as the Tesl signature does.\nfunc EitherWithDefault[A any, B any](fallback B, value Either[A, B]) B {\n\tif value.Tag == EitherRight {\n\t\treturn value.RightValue\n\t}\n\treturn fallback\n}\n\n// EitherToMaybe forgets WHICH left it was: a Left becomes Nothing.\nfunc EitherToMaybe[A any, B any](value Either[A, B]) Maybe[B] {\n\tif value.Tag == EitherRight {\n\t\treturn Something(value.RightValue)\n\t}\n\treturn Nothing[B]()\n}\n\n// EitherFromMaybe supplies the left a Nothing has no value for.\nfunc EitherFromMaybe[A any, B any](leftValue A, value Maybe[B]) Either[A, B] {\n\tif value.Tag == MaybeSomething {\n\t\treturn Right[A, B](value.SomethingValue)\n\t}\n\treturn Left[A, B](leftValue)\n}\n");
  ("float.go", "package teslrt\n\nimport (\n\t\"math\"\n\t\"strconv\"\n)\n\n// Tesl's Float is Go's float64. Two things about it are NOT the Go default, and both\n// are decided in roadmap/next/migrate_to_golang.md (\"Float decisions\"):\n//\n//   - Rendering adopts Go's shortest-round-trip digits and layout, plus one deviation:\n//     a `.0` is appended when the result carries neither `.` nor `e`. Tesl has both\n//     arbitrary-precision Int and Float, so a bare `1` would make the two\n//     indistinguishable in logs, interpolation, and test expectations.\n//   - Equality is STRUCTURAL, not IEEE: NaN equals NaN and 0.0 does not equal -0.0,\n//     matching Racket's `equal?`. IEEE `==` is not an equivalence relation, which\n//     would cost a record or Dict key holding NaN its own reflexivity. Postgres\n//     independently agrees that NaN = NaN.\n//\n// Ordering, by contrast, IS plain IEEE in both backends, so it needs no helper here.\nfunc FormatFloat(value float64) string {\n\tswitch {\n\tcase math.IsNaN(value):\n\t\treturn \"NaN\"\n\tcase math.IsInf(value, 1):\n\t\treturn \"+Inf\"\n\tcase math.IsInf(value, -1):\n\t\treturn \"-Inf\"\n\t}\n\trendered := strconv.FormatFloat(value, 'g', -1, 64)\n\tfor index := 0; index < len(rendered); index++ {\n\t\tif rendered[index] == '.' || rendered[index] == 'e' {\n\t\t\treturn rendered\n\t\t}\n\t}\n\treturn rendered + \".0\"\n}\n\n// FloatEqual is Racket `equal?` on flonums: reflexive for NaN, and distinguishing the\n// two zeros. Both differ from Go's `==`.\nfunc FloatEqual(left, right float64) bool {\n\tif math.IsNaN(left) || math.IsNaN(right) {\n\t\treturn math.IsNaN(left) && math.IsNaN(right)\n\t}\n\tif left == 0 && right == 0 {\n\t\treturn math.Signbit(left) == math.Signbit(right)\n\t}\n\treturn left == right\n}\n\n// FloatKeyLess is the ordering Dict and Set use for Float KEYS, and it is deliberately\n// NOT the IEEE ordering that user-visible comparisons and List.sort use.\n//\n// Dict and Set are sorted, so their binary search derives key equivalence from the\n// comparator: \"neither side is less\" means \"same key\". Native `<` breaks that in two\n// ways, and both are real lookup bugs rather than output-order quirks:\n//\n//   - Every comparison involving NaN is false, so a NaN key looks equivalent to whatever\n//     value the search happens to probe. `SetMember(NaN, {1,2,3})` returned TRUE with the\n//     native comparator, and inserting NaN was a no-op.\n//   - Native ordering treats -0.0 and +0.0 as equal, while FloatEqual deliberately\n//     distinguishes them, so the two collapsed into one key.\n//\n// The law this function must satisfy, and which float_test.go checks exhaustively:\n//\n//\tFloatEqual(a, b)  ==  !FloatKeyLess(a, b) && !FloatKeyLess(b, a)\n//\n// All NaNs form ONE key-equivalence class (matching FloatEqual) and sort before every\n// number; -0.0 sorts immediately before +0.0. Where the NaN class sits is internal and is\n// not Tesl language semantics \226\128\148 only the equivalence classes are.\nfunc FloatKeyLess(left, right float64) bool {\n\tleftIsNaN, rightIsNaN := math.IsNaN(left), math.IsNaN(right)\n\tif leftIsNaN || rightIsNaN {\n\t\treturn leftIsNaN && !rightIsNaN\n\t}\n\tif left == right {\n\t\t// Only -0.0 and +0.0 reach here as distinct values.\n\t\treturn math.Signbit(left) && !math.Signbit(right)\n\t}\n\treturn left < right\n}\n\n// ParseFloat accepts what Tesl's `Float.parse` accepts: a decimal float, with no\n// leading or trailing space and no Racket reader syntax.\nfunc ParseFloat(text string) Maybe[float64] {\n\tvalue, err := strconv.ParseFloat(text, 64)\n\tif err != nil {\n\t\treturn Nothing[float64]()\n\t}\n\treturn Something(value)\n}\n\nfunc FloatAbs(value float64) float64 {\n\treturn math.Abs(value)\n}\n\n// FloatMin and FloatMax propagate NaN and distinguish the zeros, matching Racket's\n// `min`/`max` on flonums rather than Go's built-in min/max.\nfunc FloatMin(left, right float64) float64 {\n\treturn math.Min(left, right)\n}\n\nfunc FloatMax(left, right float64) float64 {\n\treturn math.Max(left, right)\n}\n\n// FloatFloor, FloatCeil, and FloatRound return an INT, not a Float: tesl/float.rkt\n// wraps each in `inexact->exact`, and their declared Tesl signatures are\n// `Float -> Int`. FloatRound rounds HALF TO EVEN, because that is what Racket's\n// `round` does on a flonum \226\128\148 `math.Round` would round half away from zero and disagree\n// on every exact .5.\n//\n// NaN and infinity have no integer value. Racket RAISES there (`inexact->exact` has no\n// exact representation for them) and the declared Tesl signature is `Float -> Int`\n// rather than `-> Maybe Int`, so these panic rather than inventing a value or widening\n// the type.\nfunc FloatFloor(value float64) Int {\n\treturn mustExactInt(\"Float.floor\", math.Floor(value))\n}\n\nfunc FloatCeil(value float64) Int {\n\treturn mustExactInt(\"Float.ceil\", math.Ceil(value))\n}\n\nfunc FloatRound(value float64) Int {\n\treturn mustExactInt(\"Float.round\", math.RoundToEven(value))\n}\n\nfunc mustExactInt(who string, value float64) Int {\n\tconverted, err := FromFloat64(value)\n\tif err != nil {\n\t\tpanic(who + \": no exact integer for NaN or infinity\")\n\t}\n\treturn converted\n}\n\nfunc FloatClamp(value, low, high float64) float64 {\n\treturn math.Max(low, math.Min(high, value))\n}\n\n// FloatSqrt is bit-identical to Racket's, since both defer to the IEEE-exact\n// operation. The other transcendentals are NOT: they are rejected in the emitter\n// rather than emitted divergent.\nfunc FloatSqrt(value float64) float64 {\n\treturn math.Sqrt(value)\n}\n\n// FloatFromInt is exact up to 2^53 and rounds beyond it, like Racket's exact->inexact.\nfunc FloatFromInt(value Int) float64 {\n\treturn value.Float64()\n}\n\n// FloatToInt truncates toward zero. NaN and infinity are not integers, so this\n// mirrors Int.fromFloat by refusing them.\nfunc FloatToInt(value float64) Maybe[Int] {\n\tconverted, err := FromFloat64(value)\n\tif err != nil {\n\t\treturn Nothing[Int]()\n\t}\n\treturn Something(converted)\n}\n\n// FloatRequireNonZero is Tesl's `Float.requireNonZero` check: the proof erases, the\n// rejection does not. Negative zero is zero.\nfunc FloatRequireNonZero(value float64) Check[float64] {\n\tif value == 0 {\n\t\treturn Reject[float64](400, \"expected a non-zero float\")\n\t}\n\treturn Accept(value)\n}\n\n// FloatToIntTruncating is Tesl's `Float.toInt`, whose declared signature is\n// `Float -> Int`: it truncates toward zero and panics on NaN or infinity, exactly where\n// Racket's `inexact->exact` raises. FloatToInt above is the Maybe-returning form used\n// by hand-written runtime code.\nfunc FloatToIntTruncating(value float64) Int {\n\treturn mustExactInt(\"Float.toInt\", math.Trunc(value))\n}\n\n// FloatRequireNonNegative is Tesl's `Float.requireNonNegative`, the check that\n// discharges `Float.sqrt`'s FloatNonNegative obligation. Zero is accepted: sqrt(0) is\n// 0, so requiring strict positivity would reject a well-defined call.\nfunc FloatRequireNonNegative(value float64) Check[float64] {\n\tif math.IsNaN(value) || value < 0 {\n\t\treturn Reject[float64](422, \"expected a non-negative float\")\n\t}\n\treturn Accept(value)\n}\n\n// The Float ARITHMETIC surface (`Float.add` and friends), for code that prefers named\n// operations to operators. Plain IEEE arithmetic \226\128\148 the same thing `a + b` emits.\nfunc FloatAdd(left, right float64) float64 { return left + right }\n\nfunc FloatSub(left, right float64) float64 { return left - right }\n\nfunc FloatMul(left, right float64) float64 { return left * right }\n\n// FloatDiv's divisor carries a `FloatNonZero` proof, which erases; division by zero would\n// otherwise be \194\177Inf, which is what Racket's `/` on a flonum gives too. No guard is added\n// here: adding one would make the emitted program behave differently from `a / b`, and the\n// proof is the enforcement.\nfunc FloatDiv(left, right float64) float64 { return left / right }\n\n// The predicates. NaN is its own case in every one of them: `Float.isNaN x` is the only way to\n// ask, because every comparison with NaN is false \226\128\148 which is exactly why `isPositive`,\n// `isNegative` and `isZero` all answer false for it rather than one of them accidentally\n// answering true.\nfunc FloatIsNaN(value float64) bool { return math.IsNaN(value) }\n\nfunc FloatIsInfinite(value float64) bool { return math.IsInf(value, 0) }\n\nfunc FloatIsPositive(value float64) bool { return value > 0 }\n\nfunc FloatIsNegative(value float64) bool { return value < 0 }\n\nfunc FloatIsZero(value float64) bool { return value == 0 }\n\n// FloatSign answers a FLOAT (1.0, -1.0, 0.0), not an Int: it composes with float arithmetic,\n// which is what a sign is used for. NaN has no sign, and answering 0.0 for it would claim it is\n// zero \226\128\148 so it answers NaN, which propagates the way every other NaN operation does.\nfunc FloatSign(value float64) float64 {\n\tswitch {\n\tcase math.IsNaN(value):\n\t\treturn value\n\tcase value > 0:\n\t\treturn 1.0\n\tcase value < 0:\n\t\treturn -1.0\n\tdefault:\n\t\treturn 0.0\n\t}\n}\n\n// FloatInfinity and FloatNaN are the two named constants. They are functions rather than package\n// variables so nothing can assign to them.\nfunc FloatInfinity() float64 { return math.Inf(1) }\n\nfunc FloatNaN() float64 { return math.NaN() }\n");
  ("hostclass.go", "package teslrt\n\nimport (\n\t\"net\"\n\t\"os\"\n\t\"strconv\"\n\t\"strings\"\n)\n\n// Address-range classification \226\128\148 the decision behind SSRF egress containment.\n//\n// The dangerous SSRF targets (cloud metadata at 169.254.169.254, RFC1918, CGNAT,\n// unique-local, link-local, 0.0.0.0/8) are refused for every outbound call, judged by the\n// address actually CONNECTED TO rather than by the hostname: `evil.example.com` can resolve\n// to 127.0.0.1 or to the metadata address, so a name check decides nothing.\n//\n// The range table is deliberately a copy of ONE Racket table\n// (`dsl/private/host-classify.rkt`), including the refusal wording, because a `.tesl`\n// application asking `Net.isForbiddenHost` and the runtime refusing to dial must agree\n// about what \"private\" means. The counterpart to `Tesl.Net`'s full host normalization \226\128\148\n// the `inet_aton` spellings (`2130706433`, `0x7f.0.0.1`) and DNS-name syntax \226\128\148 is not here:\n// this entry point judges an address a resolver already produced, and a spelling that\n// cannot be parsed is refused rather than guessed at.\n//\n// FAIL CLOSED: anything not recognizable as a public, routable address is refused.\ntype addressClass int\n\nconst (\n\tclassInvalid addressClass = iota\n\tclassPublic\n\tclassLoopback\n\tclassUnspecified\n\tclassLinkLocal\n\tclassPrivate\n\tclassCGNAT\n\tclassMulticast\n)\n\n// classifyAddress parses a bare address (an IPv6 zone id is tolerated and dropped) and\n// answers its class along with whether it denotes an IPv4 address. An IPv4-mapped or\n// IPv4-compatible IPv6 spelling denotes the IPv4 address it embeds \226\128\148 that fold is the\n// classic bypass, so it happens before classification, never after.\nfunc classifyAddress(raw string) (addressClass, bool) {\n\ttext := strings.ToLower(strings.TrimSpace(raw))\n\tif zone := strings.IndexByte(text, '%'); zone >= 0 {\n\t\ttext = text[:zone]\n\t}\n\taddress := net.ParseIP(text)\n\tif address == nil {\n\t\treturn classInvalid, false\n\t}\n\tif v4 := embeddedIPv4(address); v4 != nil {\n\t\treturn ipv4Class(v4), true\n\t}\n\tif v4 := address.To4(); v4 != nil {\n\t\treturn ipv4Class(v4), true\n\t}\n\treturn ipv6Class(address.To16()), false\n}\n\n// embeddedIPv4 answers the IPv4 address an IPv6 literal embeds, or nil.\n//\n// `net.IP.To4` already folds the IPv4-mapped form (`::ffff:a.b.c.d`). The deprecated\n// IPv4-COMPATIBLE form (`::a.b.c.d`) it does not, and that form reaches the same host, so it\n// is folded here. `::` and `::1` are their own addresses and are NOT folded \226\128\148 otherwise the\n// IPv6 loopback would be classified through the 0.0.0.0/8 branch.\nfunc embeddedIPv4(address net.IP) net.IP {\n\tfull := address.To16()\n\tif full == nil || address.To4() != nil {\n\t\treturn nil\n\t}\n\tfor _, octet := range full[:12] {\n\t\tif octet != 0 {\n\t\t\treturn nil\n\t\t}\n\t}\n\tif full[12] == 0 && full[13] == 0 {\n\t\treturn nil\n\t}\n\treturn net.IPv4(full[12], full[13], full[14], full[15]).To4()\n}\n\nfunc ipv4Class(v4 net.IP) addressClass {\n\tfirst, second := v4[0], v4[1]\n\tswitch {\n\tcase first == 0:\n\t\treturn classUnspecified // 0.0.0.0/8 \"this network\"\n\tcase first == 127:\n\t\treturn classLoopback // 127.0.0.0/8\n\tcase first == 10:\n\t\treturn classPrivate // 10.0.0.0/8\n\tcase first == 169 && second == 254:\n\t\treturn classLinkLocal // 169.254.0.0/16 (cloud metadata)\n\tcase first == 172 && second >= 16 && second <= 31:\n\t\treturn classPrivate // 172.16.0.0/12\n\tcase first == 192 && second == 168:\n\t\treturn classPrivate // 192.168.0.0/16\n\tcase first == 100 && second >= 64 && second <= 127:\n\t\treturn classCGNAT // 100.64.0.0/10\n\tcase first >= 224:\n\t\treturn classMulticast // 224.0.0.0/4 and the reserved space above it\n\tdefault:\n\t\treturn classPublic\n\t}\n}\n\nfunc ipv6Class(full net.IP) addressClass {\n\tif full == nil {\n\t\treturn classInvalid\n\t}\n\tgroup0 := uint16(full[0])<<8 | uint16(full[1])\n\tswitch {\n\tcase full.Equal(net.IPv6unspecified):\n\t\treturn classUnspecified // ::\n\tcase full.Equal(net.IPv6loopback):\n\t\treturn classLoopback // ::1\n\tcase group0&0xffc0 == 0xfe80:\n\t\treturn classLinkLocal // fe80::/10\n\tcase group0&0xfe00 == 0xfc00:\n\t\treturn classPrivate // fc00::/7 unique-local\n\tcase group0&0xff00 == 0xff00:\n\t\treturn classMulticast // ff00::/8\n\tdefault:\n\t\treturn classPublic\n\t}\n}\n\n// IPForbiddenReason names the range that makes an address unsafe to dial, or \"\" when the\n// address is public and routable. The wording matches the Racket runtime's, so a refusal\n// reads the same on both backends.\nfunc IPForbiddenReason(address string) string {\n\tclass, isIPv4 := classifyAddress(address)\n\tswitch class {\n\tcase classPublic:\n\t\treturn \"\"\n\tcase classLoopback:\n\t\tif isIPv4 {\n\t\t\treturn \"loopback 127.0.0.0/8\"\n\t\t}\n\t\treturn \"IPv6 loopback ::1\"\n\tcase classUnspecified:\n\t\tif isIPv4 {\n\t\t\treturn \"0.0.0.0/8 (this network)\"\n\t\t}\n\t\treturn \"unspecified ::\"\n\tcase classLinkLocal:\n\t\tif isIPv4 {\n\t\t\treturn \"link-local 169.254.0.0/16\"\n\t\t}\n\t\treturn \"IPv6 link-local fe80::/10\"\n\tcase classPrivate:\n\t\tif isIPv4 {\n\t\t\treturn rfc1918Label(address)\n\t\t}\n\t\treturn \"IPv6 unique-local fc00::/7\"\n\tcase classCGNAT:\n\t\treturn \"CGNAT 100.64.0.0/10\"\n\tcase classMulticast:\n\t\tif isIPv4 {\n\t\t\treturn \"multicast/reserved >= 224.0.0.0\"\n\t\t}\n\t\treturn \"IPv6 multicast ff00::/8\"\n\tcase classInvalid:\n\t\treturn \"unrecognized address form (fail-closed)\"\n\t}\n\t// Unreachable: every class is answered above. A class added later lands here, and refusing\n\t// is the only safe answer for a range whose policy nobody has decided yet.\n\treturn \"unrecognized address form (fail-closed)\"\n}\n\n// rfc1918Label names the specific private block, so the refusal is actionable.\nfunc rfc1918Label(address string) string {\n\tparsed := net.ParseIP(strings.TrimSpace(strings.ToLower(address)))\n\tif parsed == nil {\n\t\treturn \"a private range\"\n\t}\n\tv4 := embeddedIPv4(parsed)\n\tif v4 == nil {\n\t\tv4 = parsed.To4()\n\t}\n\tif v4 == nil {\n\t\treturn \"a private range\"\n\t}\n\tswitch v4[0] {\n\tcase 10:\n\t\treturn \"private 10.0.0.0/8\"\n\tcase 172:\n\t\treturn \"private 172.16.0.0/12\"\n\tdefault:\n\t\treturn \"private 192.168.0.0/16\"\n\t}\n}\n\n// HostLoopback reports whether a HOST (not a resolved address) can only be reached from\n// this machine. Used solely to bound the two development escapes below; the default secure\n// path never consults it.\nfunc HostLoopback(host string) bool {\n\tlowered := strings.ToLower(strings.TrimSpace(host))\n\tlowered = strings.TrimSuffix(strings.TrimPrefix(lowered, \"[\"), \"]\")\n\tif lowered == \"localhost\" || strings.HasSuffix(lowered, \".localhost\") {\n\t\treturn true\n\t}\n\tclass, _ := classifyAddress(lowered)\n\treturn class == classLoopback\n}\n\n// SsrfAllowLoopback reports whether loopback egress is permitted: it is the one private\n// range local development legitimately dials, so a non-deployed build allows it and a\n// deployed build refuses unless TESL_HTTP_ALLOW_LOOPBACK_EGRESS opts back in.\nfunc SsrfAllowLoopback() bool {\n\tif !envPresent(\"TESL_DEPLOYED\") {\n\t\treturn true\n\t}\n\treturn envTruthy(\"TESL_HTTP_ALLOW_LOOPBACK_EGRESS\")\n}\n\n// SsrfEgressRefusal is the egress verdict for a resolved peer address: \"\" to allow.\nfunc SsrfEgressRefusal(peer string) string {\n\treason := IPForbiddenReason(peer)\n\tswitch {\n\tcase reason == \"\":\n\t\treturn \"\"\n\tcase HostLoopback(peer) && SsrfAllowLoopback():\n\t\treturn \"\"\n\tdefault:\n\t\treturn reason\n\t}\n}\n\n// \226\148\128\226\148\128 Runtime configuration knobs \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// These read the process environment for the RUNTIME's own tuning (deadlines, egress\n// policy), which is a different question from Tesl's `env` surface in env.go: there an\n// empty variable counts as unset, because a blank deployment value must not look like a\n// configured one. Here presence is what a flag means, mirroring Racket's `getenv`.\n\nfunc envPresent(name string) bool {\n\t_, present := os.LookupEnv(name)\n\treturn present\n}\n\n// envTruthy accepts the same four spellings the Racket runtime does, so a deployment's\n// existing value keeps its meaning across backends.\nfunc envTruthy(name string) bool {\n\tvalue, present := os.LookupEnv(name)\n\tif !present {\n\t\treturn false\n\t}\n\tswitch strings.ToLower(strings.TrimSpace(value)) {\n\tcase \"1\", \"true\", \"yes\", \"on\":\n\t\treturn true\n\tdefault:\n\t\treturn false\n\t}\n}\n\n// envPositiveInt reads a positive-integer env knob, falling back to `fallback` for an\n// absent, empty, or unparseable value. Read fresh per call, not at init: a test or an\n// operator can retune a deadline without a restart.\nfunc envPositiveInt(name string, fallback int) int {\n\tvalue, present := os.LookupEnv(name)\n\tif !present {\n\t\treturn fallback\n\t}\n\tparsed, err := strconv.Atoi(strings.TrimSpace(value))\n\tif err != nil || parsed <= 0 {\n\t\treturn fallback\n\t}\n\treturn parsed\n}\n");
  ("httpclient.go", "package teslrt\n\nimport (\n\t\"context\"\n\t\"crypto/rand\"\n\t\"crypto/tls\"\n\t\"encoding/hex\"\n\t\"errors\"\n\t\"fmt\"\n\t\"io\"\n\t\"net\"\n\t\"net/http\"\n\t\"net/url\"\n\t\"os\"\n\t\"sort\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n\t\"syscall\"\n\t\"time\"\n)\n\n// millisDuration turns one of the millisecond knobs into a deadline.\nfunc millisDuration(millis int) time.Duration {\n\treturn time.Duration(millis) * time.Millisecond\n}\n\n// Outbound HTTP \226\128\148 the `Tesl.HttpClient` surface.\n//\n// The `httpClient` capability that gates every call here is a COMPILE-TIME grant, so\n// nothing about it survives to run time; what does survive is the set of protections a\n// call cannot opt out of:\n//\n//\tCR/LF header guard    a `\\r\\n` in a header name or value would split the request and\n//\t                      inject arbitrary headers, so it is refused before anything is sent;\n//\tSSRF containment      the peer address actually connected to is judged (hostclass.go), so\n//\t                      a public name resolving to 169.254.169.254 or 127.0.0.1 is refused;\n//\tverified TLS          certificate chain AND hostname, with one loopback-only development\n//\t                      escape;\n//\tdeadlines             a hung upstream fails the call rather than pinning the caller \226\128\148\n//\t                      inside a worker that is the difference between a failed job (which\n//\t                      retries and dead-letters) and a job that never finishes;\n//\ta response-body cap   an unbounded read of a hostile response is a memory DoS.\n//\n// Trace-context propagation (`traceparent`/`tracestate` on every outbound call) is NOT here\n// yet: it needs the telemetry slice, which has not been migrated. Its absence loses trace\n// continuity across services; it takes nothing else away.\ntype HttpResponse struct {\n\tStatus Int\n\tBody   string\n\t// Response headers in name order \226\128\148 one entry per value, so a repeated header\n\t// (`Set-Cookie`) keeps all of its values. Go's header map has no order of its own, so\n\t// sorting is what makes the list deterministic; Racket preserves wire order instead, and\n\t// a test that depends on either ordering is testing the transport, not the program.\n\tHeaders []Tuple2[string, string]\n}\n\n// \226\148\128\226\148\128 Deadlines \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// Env vars rather than per-call arguments, matching the Racket runtime: a deadline is\n// deployment tuning of the same kind as the response-body cap, and a per-call timeout would\n// put an operational concern into all four public signatures.\n//\n//\tTESL_HTTP_CONNECT_TIMEOUT_MS   10000   reaching the host\n//\tTESL_HTTP_TIMEOUT_MS           30000   the whole response (status + body)\n//\tTESL_HTTP_MAX_RESPONSE_BYTES   10 MiB  the most a response body may occupy\n\nfunc httpConnectTimeoutMs() int { return envPositiveInt(\"TESL_HTTP_CONNECT_TIMEOUT_MS\", 10000) }\nfunc httpReadTimeoutMs() int    { return envPositiveInt(\"TESL_HTTP_TIMEOUT_MS\", 30000) }\n\nfunc httpMaxResponseBytes() int {\n\treturn envPositiveInt(\"TESL_HTTP_MAX_RESPONSE_BYTES\", 10*1024*1024)\n}\n\n// \226\148\128\226\148\128 Header hygiene \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// HttpHeaderFieldSafe reports whether a header name or value can go on the wire: a CR or LF\n// would end the field and let the rest be read as further headers or a second request.\nfunc HttpHeaderFieldSafe(field string) bool {\n\treturn !strings.ContainsAny(field, \"\\r\\n\")\n}\n\nfunc requireHeaderFieldSafe(what, field string) string {\n\tif !HttpHeaderFieldSafe(field) {\n\t\tpanic(fmt.Sprintf(\n\t\t\t\"HttpClient: outbound %s contains a CR/LF newline \226\128\148 header injection rejected\", what))\n\t}\n\treturn field\n}\n\n// \226\148\128\226\148\128 Secret-carrying headers \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// `HttpClient.bearer k` and `HttpClient.secretHeader \"X-Api-Key\" k` are the sanctioned way\n// a `secret` reaches the wire, replacing the `\"Bearer \" ++ key.value` that `secret` makes\n// impossible. Their Tesl type is `Tuple2 String String`, so the value half IS a Go string \226\128\148\n// which means the plaintext cannot be what it holds, or `Tuple2.second (bearer k)` would\n// hand a program the secret it is not allowed to see.\n//\n// So the value half is a HANDLE: unguessable text that names the plaintext in a\n// process-local table. Every String operation on it sees the handle, printing it shows only\n// \"[redacted]\", and this file is the one place that trades a handle back for the bytes that\n// go on the socket. The handle carries a per-process random nonce because it is otherwise\n// forgeable: a program that could construct the handle text from user input would make the\n// client send OUR secret to an attacker's URL.\nvar (\n\tsecretHeaderNonce = newSecretHeaderNonce()\n\tsecretHeaderStore sync.Map // handle string -> plaintext string\n\tsecretHeaderSeq   int64\n\tsecretHeaderMutex sync.Mutex\n)\n\nfunc newSecretHeaderNonce() string {\n\tbuffer := make([]byte, 16)\n\tif _, err := rand.Read(buffer); err != nil {\n\t\tpanic(\"HttpClient: no source of randomness for secret headers: \" + err.Error())\n\t}\n\treturn hex.EncodeToString(buffer)\n}\n\nfunc secretHeaderHandle(plaintext string) string {\n\tsecretHeaderMutex.Lock()\n\tsecretHeaderSeq++\n\tsequence := secretHeaderSeq\n\tsecretHeaderMutex.Unlock()\n\thandle := SecretRedaction + \"\\x00\" + secretHeaderNonce + \":\" + strconv.FormatInt(sequence, 10)\n\tsecretHeaderStore.Store(handle, plaintext)\n\treturn handle\n}\n\n// revealHeaderValue is THE unwrap point: a secret-header handle becomes plaintext here and\n// nowhere else. Anything that is not a handle is already the value it looks like.\nfunc revealHeaderValue(value string) string {\n\tif !strings.HasPrefix(value, SecretRedaction+\"\\x00\") {\n\t\treturn value\n\t}\n\tif plaintext, found := secretHeaderStore.Load(value); found {\n\t\tif text, ok := plaintext.(string); ok {\n\t\t\treturn text\n\t\t}\n\t}\n\t// A handle shape from another process (or a forgery attempt) names no plaintext here.\n\t// Sending the handle text would leak nothing, but it would also silently authenticate as\n\t// nobody, so it fails instead.\n\tpanic(\"HttpClient: this secret header value does not belong to this process\")\n}\n\n// HttpSecretHeader is `HttpClient.secretHeader name k`.\nfunc HttpSecretHeader(name string, secret SecretString) Tuple2[string, string] {\n\treturn makeSecretHeader(name, secret, \"\")\n}\n\n// HttpBearer is `HttpClient.bearer k`: the Authorization header for a bearer token.\nfunc HttpBearer(secret SecretString) Tuple2[string, string] {\n\treturn makeSecretHeader(\"Authorization\", secret, \"Bearer \")\n}\n\nfunc makeSecretHeader(name string, secret SecretString, prefix string) Tuple2[string, string] {\n\treturn Tuple2[string, string]{\n\t\tTuple2First:  requireHeaderFieldSafe(\"header name\", name),\n\t\tTuple2Second: secretHeaderHandle(prefix + secret.Reveal()),\n\t}\n}\n\n// \226\148\128\226\148\128 The four verbs \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nfunc HttpGet(target string, headers []Tuple2[string, string]) HttpResponse {\n\treturn httpRequest(\"GET\", target, headers, nil)\n}\n\nfunc HttpPost(target string, headers []Tuple2[string, string], body string) HttpResponse {\n\treturn httpRequest(\"POST\", target, headers, &body)\n}\n\nfunc HttpPut(target string, headers []Tuple2[string, string], body string) HttpResponse {\n\treturn httpRequest(\"PUT\", target, headers, &body)\n}\n\nfunc HttpDelete(target string, headers []Tuple2[string, string]) HttpResponse {\n\treturn httpRequest(\"DELETE\", target, headers, nil)\n}\n\nfunc httpRequest(method, target string, headers []Tuple2[string, string], body *string) HttpResponse {\n\tparsed := parseOutboundURL(target)\n\t// The header guard runs BEFORE the test double is consulted, so a stubbed call is still a\n\t// well-formed one and a header-injection bug cannot hide behind a stub.\n\twire := outboundHeaders(headers)\n\tif answer, stubbed := httpStubAnswer(method, target, body); stubbed {\n\t\treturn answer\n\t}\n\treturn httpRequestNetwork(method, target, parsed, wire, body)\n}\n\nfunc parseOutboundURL(target string) *url.URL {\n\tparsed, err := url.Parse(target)\n\tif err != nil {\n\t\tpanic(fmt.Sprintf(\"HttpClient: invalid URL %q: %s\", target, err.Error()))\n\t}\n\tif parsed.Scheme != \"http\" && parsed.Scheme != \"https\" {\n\t\tpanic(fmt.Sprintf(\"HttpClient: invalid URL %q: expected an http or https scheme\", target))\n\t}\n\tif parsed.Hostname() == \"\" {\n\t\tpanic(fmt.Sprintf(\"HttpClient: invalid URL %q: could not parse host\", target))\n\t}\n\treturn parsed\n}\n\n// outboundHeaders checks every field and reveals the secret-carrying ones. A header list is\n// ordered and may repeat a name, so it becomes an http.Header by APPENDING rather than\n// setting \226\128\148 `Set` would drop all but the last of a repeated header.\nfunc outboundHeaders(headers []Tuple2[string, string]) http.Header {\n\twire := http.Header{}\n\tfor _, header := range headers {\n\t\tname := requireHeaderFieldSafe(\"header name\", header.Tuple2First)\n\t\tvalue := requireHeaderFieldSafe(\"header value\", revealHeaderValue(header.Tuple2Second))\n\t\twire[http.CanonicalHeaderKey(name)] = append(wire[http.CanonicalHeaderKey(name)], value)\n\t}\n\treturn wire\n}\n\nfunc httpRequestNetwork(method, target string, parsed *url.URL, wire http.Header,\n\tbody *string) HttpResponse {\n\tvar reader io.Reader\n\tif body != nil {\n\t\treader = strings.NewReader(*body)\n\t}\n\trequest, err := http.NewRequest(method, target, reader)\n\tif err != nil {\n\t\tpanic(fmt.Sprintf(\"HttpClient: HTTP %s to %s failed: %s\", method, target, err.Error()))\n\t}\n\trequest.Header = wire\n\tclient := &http.Client{\n\t\tTransport: outboundTransport(parsed.Hostname()),\n\t\tTimeout:   millisDuration(httpReadTimeoutMs()),\n\t\t// A redirect is a fresh request to an attacker-influenced location, so it gets the\n\t\t// same egress and TLS treatment as the first one \226\128\148 which it does, because the\n\t\t// transport is shared. Nothing else is followed automatically beyond Go's default\n\t\t// limit of 10.\n\t}\n\tresponse, err := client.Do(request)\n\tif err != nil {\n\t\tpanic(requestFailure(method, target, err))\n\t}\n\tif response == nil {\n\t\t// net/http never answers with neither a response nor an error; a transport that did\n\t\t// would make the reads below a nil dereference rather than a failed call.\n\t\tpanic(fmt.Sprintf(\"HttpClient: HTTP %s to %s failed: no response\", method, target))\n\t}\n\tdefer func() { _ = response.Body.Close() }()\n\tlimit := httpMaxResponseBytes()\n\traw, err := io.ReadAll(io.LimitReader(response.Body, int64(limit)+1))\n\tif err != nil {\n\t\tpanic(fmt.Sprintf(\"HttpClient: HTTP %s to %s failed: %s\", method, target, err.Error()))\n\t}\n\tif len(raw) > limit {\n\t\tpanic(fmt.Sprintf(\"HttpClient: response body exceeds the %d-byte cap\", limit))\n\t}\n\treturn HttpResponse{\n\t\tStatus:  FromInt64(int64(response.StatusCode)),\n\t\tBody:    string(raw),\n\t\tHeaders: responseHeaders(response.Header),\n\t}\n}\n\n// requestFailure turns a transport error into the message the Racket client raises for the\n// same condition, because the test double's traps are written to match it byte for byte \226\128\148 a\n// test that asserts on a timeout must describe what production logs.\n//\n// net/http wraps everything in a `Get \"url\": \226\128\166` url.Error, so the reason is unwrapped first;\n// otherwise every failure would read as a repeat of the URL.\nfunc requestFailure(method, target string, err error) string {\n\tmessage := err.Error()\n\tvar urlErr *url.Error\n\tif errors.As(err, &urlErr) {\n\t\tmessage = urlErr.Err.Error()\n\t}\n\t// The egress refusal is raised by the dialer's Control hook, so it arrives buried in a\n\t// dial error. It is a REFUSAL, not a transport fault, and reads as one.\n\tif index := strings.Index(message, \"SSRF: refused egress\"); index >= 0 {\n\t\treturn \"HttpClient: \" + message[index:]\n\t}\n\tif isTimeout(err) {\n\t\t// A deadline that expired during the DIAL is the connect deadline; anything later is\n\t\t// the response deadline. Racket names them separately for the same reason: they are\n\t\t// tuned by different env vars.\n\t\tif dialTimeout(err) {\n\t\t\treturn fmt.Sprintf(\"HttpClient: connect to %s timed out after %dms\",\n\t\t\t\ttarget, httpConnectTimeoutMs())\n\t\t}\n\t\treturn fmt.Sprintf(\"HttpClient: HTTP %s to %s timed out after %dms\",\n\t\t\tmethod, target, httpReadTimeoutMs())\n\t}\n\treturn fmt.Sprintf(\"HttpClient: HTTP %s to %s failed: %s\", method, target, message)\n}\n\nfunc isTimeout(err error) bool {\n\tvar timeout interface{ Timeout() bool }\n\tif errors.As(err, &timeout) && timeout.Timeout() {\n\t\treturn true\n\t}\n\treturn errors.Is(err, context.DeadlineExceeded)\n}\n\nfunc dialTimeout(err error) bool {\n\tvar opErr *net.OpError\n\tif !errors.As(err, &opErr) || opErr == nil {\n\t\treturn false\n\t}\n\treturn opErr.Op == \"dial\" && opErr.Timeout()\n}\n\nfunc responseHeaders(header http.Header) []Tuple2[string, string] {\n\theaders := make([]Tuple2[string, string], 0, len(header))\n\tnames := make([]string, 0, len(header))\n\tfor name := range header {\n\t\tnames = append(names, name)\n\t}\n\tsort.Strings(names)\n\tfor _, name := range names {\n\t\tfor _, value := range header[name] {\n\t\t\theaders = append(headers, Tuple2[string, string]{Tuple2First: name, Tuple2Second: value})\n\t\t}\n\t}\n\treturn headers\n}\n\n// outboundTransport is built per call because both of its policies depend on the target\n// host: the egress judgement is per connection, and the TLS development escape is\n// loopback-only. Connection reuse is given up for that, which costs a handshake on a\n// repeated call and buys a policy that cannot be inherited from an earlier, different one.\nfunc outboundTransport(host string) *http.Transport {\n\tdialer := &net.Dialer{\n\t\tTimeout: millisDuration(httpConnectTimeoutMs()),\n\t\t// Control runs after resolution with the address that is ABOUT to be connected, and\n\t\t// the connect then uses that same address. There is therefore no check-then-rebind\n\t\t// gap: a DNS answer cannot be swapped for an internal address after being judged.\n\t\tControl: func(_network, address string, _conn syscall.RawConn) error {\n\t\t\tpeer, _, err := net.SplitHostPort(address)\n\t\t\tif err != nil {\n\t\t\t\treturn fmt.Errorf(\"SSRF: refused egress to an unparseable peer address %q\", address)\n\t\t\t}\n\t\t\tif reason := SsrfEgressRefusal(peer); reason != \"\" {\n\t\t\t\treturn fmt.Errorf(\"SSRF: refused egress to %s \226\128\148 it resolves to %s, which is %s\",\n\t\t\t\t\thost, peer, reason)\n\t\t\t}\n\t\t\treturn nil\n\t\t},\n\t}\n\treturn &http.Transport{\n\t\tDialContext:       dialer.DialContext,\n\t\tTLSClientConfig:   outboundTLSConfig(host),\n\t\tForceAttemptHTTP2: true,\n\t\tDisableKeepAlives: true,\n\t}\n}\n\n// outboundTLSConfig verifies the peer's certificate chain AND hostname \226\128\148 Go's default, kept\n// explicit here because the one escape below is the only thing allowed to weaken it.\nfunc outboundTLSConfig(host string) *tls.Config {\n\tif tlsInsecureDevEscape(host) {\n\t\t// #nosec G402 -- The single development escape, and the reason it is safe: it engages\n\t\t// only when TESL_HTTP_TLS_INSECURE_DEV is set, only in a build that is not\n\t\t// TESL_DEPLOYED, and only for a loopback host, so the peer is a service on this\n\t\t// machine. It exists so a developer can talk to a local service presenting a\n\t\t// self-signed certificate; for any routable host the branch is not taken.\n\t\treturn &tls.Config{MinVersion: tls.VersionTLS12, InsecureSkipVerify: true}\n\t}\n\treturn &tls.Config{MinVersion: tls.VersionTLS12}\n}\n\nvar (\n\ttlsDevWarnActive  sync.Once\n\ttlsDevWarnRefused sync.Once\n)\n\nfunc tlsInsecureDevEscape(host string) bool {\n\tif envPresent(\"TESL_DEPLOYED\") || !envTruthy(\"TESL_HTTP_TLS_INSECURE_DEV\") {\n\t\treturn false\n\t}\n\tif HostLoopback(host) {\n\t\ttlsDevWarnActive.Do(func() {\n\t\t\tfmt.Fprintln(os.Stderr, \"WARNING: TESL_HTTP_TLS_INSECURE_DEV active -- HTTPS \"+\n\t\t\t\t\"certificate verification is DISABLED for loopback hosts only. \"+\n\t\t\t\t\"Never enable this in production.\")\n\t\t})\n\t\treturn true\n\t}\n\ttlsDevWarnRefused.Do(func() {\n\t\tfmt.Fprintf(os.Stderr, \"WARNING: TESL_HTTP_TLS_INSECURE_DEV is set but host %q is \"+\n\t\t\t\"not loopback -- TLS verification stays ON.\\n\", host)\n\t})\n\treturn false\n}\n");
  ("httpstub.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"strings\"\n\t\"sync\"\n)\n\n// The outbound-HTTP test double.\n//\n// Without it, every handler or worker that talks to an external service has an untestable\n// branch \226\128\148 and the branches most worth covering (an upstream 500, malformed JSON, a timeout)\n// are exactly the ones a real upstream will not produce on demand. A test declares its\n// answers up front:\n//\n//\tstubHttp        \"GET\"  \"https://rates.test/v1\"  200 \"{\\\"usd\\\":110}\"\n//\tstubHttpFailure \"POST\" \"https://rates.test/log\" \"connection refused\"\n//\tstubHttpTimeout \"GET\"  \"https://rates.test/slow\"\n//\n// and asserts afterwards with httpCalled / httpCallCount / httpLastBody.\n//\n// SCOPE. The table is cleared at the top of every emitted test function, so rules and the\n// call log cannot leak from one test block into the next \226\128\148 the isolation the Racket side gets\n// from a parameter that unwinds with the test body. Go's `go test` runs a package's tests\n// sequentially unless a test opts into t.Parallel, which emitted tests never do, so one\n// package-level table is enough and a stub is visible to the goroutines a test starts\n// (a queue worker's outbound call is the case that matters).\n//\n// PRODUCTION. `active` is false until an emitted test clears the table, and only a test file\n// does that, so a production build can never answer a call from here. That is a weaker\n// guarantee than Racket's (where the double lives in a module a production run does not\n// instantiate at all) and it is the strongest one available inside a single Go package.\ntype httpStubRule struct {\n\tmethod  string\n\turl     string\n\tkind    httpStubKind\n\tstatus  int64\n\tpayload string // the canned body, the failure message, or \"\" for a timeout\n}\n\ntype httpStubKind int\n\nconst (\n\thttpStubRespond httpStubKind = iota\n\thttpStubFail\n\thttpStubTimeout\n)\n\ntype httpStubCall struct {\n\tmethod string\n\turl    string\n\tbody   string\n}\n\nvar httpStubs = struct {\n\tmutex  sync.Mutex\n\tactive bool\n\trules  []httpStubRule\n\tcalls  []httpStubCall\n}{}\n\n// ResetHttpStubs gives the current test a fresh, empty stub table. Emitted test functions\n// call it before their first statement.\nfunc ResetHttpStubs() {\n\thttpStubs.mutex.Lock()\n\tdefer httpStubs.mutex.Unlock()\n\thttpStubs.active = true\n\thttpStubs.rules = nil\n\thttpStubs.calls = nil\n}\n\nfunc requireStubScope(who string) {\n\tif !httpStubs.active {\n\t\tpanic(who + \": outbound-HTTP stubs are only available inside a test body.\\n\" +\n\t\t\t\"  Call this from a `test`, `api-test`, or `load-test` block \226\128\148 the stub\\n\" +\n\t\t\t\"  scope is created per test so nothing leaks between them.\")\n\t}\n}\n\n// \226\148\128\226\148\128 Declaring a stub \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// StubHttp declares a canned response. Rules are consulted in DECLARATION order (first\n// match wins), so a specific stub declared before a `\"*\"` catch-all keeps winning;\n// re-declaring the exact same (method, url) pattern REPLACES the earlier rule in place, so a\n// later line in the same test overrides an earlier one rather than being shadowed by it.\nfunc StubHttp(method, target string, status Int, body string) struct{} {\n\tvalue, exact := status.Int64()\n\tif !exact {\n\t\tpanic(\"stubHttp: expected an Int status\")\n\t}\n\treturn addHTTPStubRule(\"stubHttp\", httpStubRule{\n\t\tmethod: method, url: target, kind: httpStubRespond, status: value, payload: body,\n\t})\n}\n\n// StubHttpFailure declares that the call fails the way a refused connection does.\nfunc StubHttpFailure(method, target, message string) struct{} {\n\treturn addHTTPStubRule(\"stubHttpFailure\", httpStubRule{\n\t\tmethod: method, url: target, kind: httpStubFail, payload: message,\n\t})\n}\n\n// StubHttpTimeout declares that the call blows its deadline.\nfunc StubHttpTimeout(method, target string) struct{} {\n\treturn addHTTPStubRule(\"stubHttpTimeout\", httpStubRule{\n\t\tmethod: method, url: target, kind: httpStubTimeout,\n\t})\n}\n\nfunc addHTTPStubRule(who string, rule httpStubRule) struct{} {\n\trequireStubScope(who)\n\thttpStubs.mutex.Lock()\n\tdefer httpStubs.mutex.Unlock()\n\tfor index, existing := range httpStubs.rules {\n\t\tif existing.method == rule.method && existing.url == rule.url {\n\t\t\thttpStubs.rules[index] = rule\n\t\t\treturn struct{}{}\n\t\t}\n\t}\n\thttpStubs.rules = append(httpStubs.rules, rule)\n\treturn struct{}{}\n}\n\n// \226\148\128\226\148\128 Matching \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// httpStubPatternMatches is deliberately NOT a regex: a stub pattern is a test fixture, and\n// `*` plus a trailing-`*` prefix covers every shape the lessons need without putting a second\n// pattern language into the surface. Method matching is case-insensitive; URL matching is not.\nfunc httpStubPatternMatches(pattern, value string, foldCase bool) bool {\n\tif foldCase {\n\t\tpattern = strings.ToLower(pattern)\n\t\tvalue = strings.ToLower(value)\n\t}\n\tswitch {\n\tcase pattern == \"*\":\n\t\treturn true\n\tcase strings.HasSuffix(pattern, \"*\"):\n\t\treturn strings.HasPrefix(value, strings.TrimSuffix(pattern, \"*\"))\n\tdefault:\n\t\treturn pattern == value\n\t}\n}\n\nfunc (rule httpStubRule) matches(method, target string) bool {\n\treturn httpStubPatternMatches(rule.method, method, true) &&\n\t\thttpStubPatternMatches(rule.url, target, false)\n}\n\n// httpStubAnswer is the seam tesl/http-client.rkt reaches through its hook parameter.\n// `false` means no stub is in force, which is only possible when the test declared no stubs\n// at all \226\128\148 so an existing test that really wants the network behaves as before. Once a test\n// declares its first stub, an unmatched call is a loud failure instead of a silent live\n// request.\nfunc httpStubAnswer(method, target string, body *string) (HttpResponse, bool) {\n\thttpStubs.mutex.Lock()\n\tif !httpStubs.active {\n\t\thttpStubs.mutex.Unlock()\n\t\treturn HttpResponse{}, false\n\t}\n\tsent := \"\"\n\tif body != nil {\n\t\tsent = *body\n\t}\n\t// The call is recorded BEFORE it is matched, so `httpCalled` sees a call that then failed\n\t// for want of a stub \226\128\148 which is what a test asserting on the failure needs.\n\thttpStubs.calls = append(httpStubs.calls,\n\t\thttpStubCall{method: strings.ToUpper(method), url: target, body: sent})\n\trules := make([]httpStubRule, len(httpStubs.rules))\n\tcopy(rules, httpStubs.rules)\n\thttpStubs.mutex.Unlock()\n\n\tif len(rules) == 0 {\n\t\treturn HttpResponse{}, false\n\t}\n\tfor _, rule := range rules {\n\t\tif !rule.matches(method, target) {\n\t\t\tcontinue\n\t\t}\n\t\tswitch rule.kind {\n\t\tcase httpStubTimeout:\n\t\t\t// Byte-for-byte the message the real deadline produces, so a test written against\n\t\t\t// the stub matches what production logs.\n\t\t\tpanic(fmt.Sprintf(\"HttpClient: HTTP %s to %s timed out after %dms\",\n\t\t\t\tstrings.ToUpper(method), target, httpReadTimeoutMs()))\n\t\tcase httpStubFail:\n\t\t\tpanic(fmt.Sprintf(\"HttpClient: HTTP %s to %s failed: %s\",\n\t\t\t\tstrings.ToUpper(method), target, rule.payload))\n\t\tcase httpStubRespond:\n\t\t\treturn HttpResponse{\n\t\t\t\tStatus:  FromInt64(rule.status),\n\t\t\t\tBody:    rule.payload,\n\t\t\t\tHeaders: []Tuple2[string, string]{},\n\t\t\t}, true\n\t\t}\n\t}\n\tpanic(fmt.Sprintf(\"HttpClient: no stub matches %s %s\\n\"+\n\t\t\"  This test declared outbound-HTTP stubs, so no call reaches the network.\\n\"+\n\t\t\"  declared: %s\\n\"+\n\t\t\"  hint: add `stubHttp %q %q 200 \\\"\226\128\166\\\"`, or widen a pattern with a trailing *.\",\n\t\tstrings.ToUpper(method), target, describeHTTPStubRules(rules),\n\t\tstrings.ToUpper(method), target))\n}\n\nfunc describeHTTPStubRules(rules []httpStubRule) string {\n\tif len(rules) == 0 {\n\t\treturn \"(none)\"\n\t}\n\tdescribed := make([]string, 0, len(rules))\n\tfor _, rule := range rules {\n\t\tswitch rule.kind {\n\t\tcase httpStubRespond:\n\t\t\tdescribed = append(described,\n\t\t\t\tfmt.Sprintf(\"%s %s -> status %d\", rule.method, rule.url, rule.status))\n\t\tcase httpStubFail:\n\t\t\tdescribed = append(described,\n\t\t\t\tfmt.Sprintf(\"%s %s -> failure %q\", rule.method, rule.url, rule.payload))\n\t\tcase httpStubTimeout:\n\t\t\tdescribed = append(described, fmt.Sprintf(\"%s %s -> timeout\", rule.method, rule.url))\n\t\t}\n\t}\n\treturn strings.Join(described, \"\\n            \")\n}\n\n// \226\148\128\226\148\128 Asserting on the calls made \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\nfunc matchingHTTPCalls(who, method, target string) []httpStubCall {\n\trequireStubScope(who)\n\thttpStubs.mutex.Lock()\n\tdefer httpStubs.mutex.Unlock()\n\tmatched := make([]httpStubCall, 0, len(httpStubs.calls))\n\tfor _, call := range httpStubs.calls {\n\t\tif httpStubPatternMatches(method, call.method, true) &&\n\t\t\thttpStubPatternMatches(target, call.url, false) {\n\t\t\tmatched = append(matched, call)\n\t\t}\n\t}\n\treturn matched\n}\n\nfunc HttpCallCount(method, target string) Int {\n\treturn FromInt64(int64(len(matchingHTTPCalls(\"httpCallCount\", method, target))))\n}\n\nfunc HttpCalled(method, target string) bool {\n\treturn len(matchingHTTPCalls(\"httpCalled\", method, target)) > 0\n}\n\n// HttpLastBody is the body of the most recent matching call, or a trap naming the calls that\n// were made \226\128\148 a test asserting on a body it never sent is a broken test, not a false one.\nfunc HttpLastBody(method, target string) string {\n\tmatched := matchingHTTPCalls(\"httpLastBody\", method, target)\n\tif len(matched) == 0 {\n\t\tpanic(fmt.Sprintf(\"httpLastBody: no outbound %s call matched %q\\n  calls made: %s\",\n\t\t\tmethod, target, describeHTTPCallsMade()))\n\t}\n\treturn matched[len(matched)-1].body\n}\n\nfunc describeHTTPCallsMade() string {\n\thttpStubs.mutex.Lock()\n\tdefer httpStubs.mutex.Unlock()\n\tif len(httpStubs.calls) == 0 {\n\t\treturn \"(none)\"\n\t}\n\tdescribed := make([]string, 0, len(httpStubs.calls))\n\tfor _, call := range httpStubs.calls {\n\t\tdescribed = append(described, call.method+\" \"+call.url)\n\t}\n\treturn strings.Join(described, \", \")\n}\n");
  ("int.go", "// Package teslrt contains the small, audited runtime core used by emitted Tesl\n// programs.\npackage teslrt\n\nimport (\n\t\"errors\"\n\t\"hash/fnv\"\n\t\"math\"\n\t\"math/big\"\n)\n\nvar (\n\tErrDivisionByZero = errors.New(\"teslrt.Int: division by zero\")\n\tErrNegativePower  = errors.New(\"teslrt.Int: negative exponent\")\n\tErrInvalidFloat   = errors.New(\"teslrt.Int: NaN and infinity are not integers\")\n\tErrInvalidInt     = errors.New(\"teslrt.Int: invalid decimal integer\")\n)\n\n// Int is Tesl's arbitrary-precision integer. The zero value is zero.\n//\n// big is non-nil exactly when the value is outside the int64 range. noCompare\n// makes raw == and map[Int] compile errors; callers must use Equal and Key.\ntype Int struct {\n\tnoCompare [0]func()\n\tsmall     int64\n\tbig       *big.Int\n}\n\n// IntKey is the canonical, comparable key for an Int.\ntype IntKey string\n\nfunc FromInt64(value int64) Int {\n\treturn Int{small: value}\n}\n\n// ParseDecimal parses an optional sign followed by one or more decimal digits.\nfunc ParseDecimal(value string) (Int, error) {\n\tif !validDecimal(value, true) {\n\t\treturn Int{}, ErrInvalidInt\n\t}\n\tn, ok := new(big.Int).SetString(value, 10)\n\tif !ok {\n\t\treturn Int{}, ErrInvalidInt\n\t}\n\treturn fromBig(n), nil\n}\n\nfunc MustParseDecimal(value string) Int {\n\tn, err := ParseDecimal(value)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\treturn n\n}\n\n// FromFloat64 truncates toward zero, matching Tesl's Int.fromFloat semantics.\nfunc FromFloat64(value float64) (Int, error) {\n\tif math.IsNaN(value) || math.IsInf(value, 0) {\n\t\treturn Int{}, ErrInvalidFloat\n\t}\n\tn, _ := big.NewFloat(value).Int(nil)\n\treturn fromBig(n), nil\n}\n\nfunc fromBig(value *big.Int) Int {\n\tif value == nil {\n\t\treturn Int{}\n\t}\n\tif value.IsInt64() {\n\t\treturn FromInt64(value.Int64())\n\t}\n\treturn Int{big: new(big.Int).Set(value)}\n}\n\n// bigInt always returns a new value. No operation may mutate an Int operand.\nfunc (n Int) bigInt() *big.Int {\n\t_ = n.noCompare\n\tif n.big == nil {\n\t\treturn big.NewInt(n.small)\n\t}\n\treturn new(big.Int).Set(n.big)\n}\n\nfunc validDecimal(value string, allowPlus bool) bool {\n\tif value == \"\" {\n\t\treturn false\n\t}\n\tstart := 0\n\tif value[0] == '-' || (allowPlus && value[0] == '+') {\n\t\tstart = 1\n\t}\n\tif start == len(value) {\n\t\treturn false\n\t}\n\tfor i := start; i < len(value); i++ {\n\t\tif value[i] < '0' || value[i] > '9' {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n\nfunc Add(left, right Int) Int {\n\tif left.big == nil && right.big == nil {\n\t\tif (right.small > 0 && left.small <= math.MaxInt64-right.small) ||\n\t\t\t(right.small < 0 && left.small >= math.MinInt64-right.small) ||\n\t\t\tright.small == 0 {\n\t\t\treturn FromInt64(left.small + right.small)\n\t\t}\n\t}\n\treturn fromBig(new(big.Int).Add(left.bigInt(), right.bigInt()))\n}\n\nfunc Sub(left, right Int) Int {\n\tif left.big == nil && right.big == nil {\n\t\tif (right.small > 0 && left.small >= math.MinInt64+right.small) ||\n\t\t\t(right.small < 0 && left.small <= math.MaxInt64+right.small) ||\n\t\t\tright.small == 0 {\n\t\t\treturn FromInt64(left.small - right.small)\n\t\t}\n\t}\n\treturn fromBig(new(big.Int).Sub(left.bigInt(), right.bigInt()))\n}\n\nfunc Mul(left, right Int) Int {\n\tif left.big == nil && right.big == nil {\n\t\tif left.small == 0 || right.small == 0 {\n\t\t\treturn Int{}\n\t\t}\n\t\tif (left.small != math.MinInt64 || right.small != -1) &&\n\t\t\t(right.small != math.MinInt64 || left.small != -1) {\n\t\t\tproduct := left.small * right.small\n\t\t\tif product/right.small == left.small {\n\t\t\t\treturn FromInt64(product)\n\t\t\t}\n\t\t}\n\t}\n\treturn fromBig(new(big.Int).Mul(left.bigInt(), right.bigInt()))\n}\n\nfunc Neg(value Int) Int {\n\tif value.big == nil && value.small != math.MinInt64 {\n\t\treturn FromInt64(-value.small)\n\t}\n\treturn fromBig(new(big.Int).Neg(value.bigInt()))\n}\n\n// IntGcd is Racket's `gcd`: always NON-NEGATIVE, and gcd(0, 0) is 0. The sign of either\n// operand does not reach the answer, which is what makes `gcd a b == gcd (-a) b` hold.\nfunc IntGcd(left, right Int) Int {\n\tfirst := new(big.Int).Abs(left.bigInt())\n\tsecond := new(big.Int).Abs(right.bigInt())\n\treturn fromBig(new(big.Int).GCD(nil, nil, first, second))\n}\n\n// IntLcm is Racket's `lcm`: non-negative, and 0 whenever either operand is 0 (there is no\n// smaller common multiple than 0 in that case, and dividing by gcd(0,0) would trap).\nfunc IntLcm(left, right Int) Int {\n\tfirst := new(big.Int).Abs(left.bigInt())\n\tsecond := new(big.Int).Abs(right.bigInt())\n\tif first.Sign() == 0 || second.Sign() == 0 {\n\t\treturn FromInt64(0)\n\t}\n\tdivisor := new(big.Int).GCD(nil, nil, first, second)\n\treturn fromBig(new(big.Int).Div(new(big.Int).Mul(first, second), divisor))\n}\n\nfunc Abs(value Int) Int {\n\tif value.Sign() >= 0 {\n\t\treturn value\n\t}\n\treturn Neg(value)\n}\n\n// Quo truncates toward zero.\nfunc Quo(dividend, divisor Int) (Int, error) {\n\tif divisor.IsZero() {\n\t\treturn Int{}, ErrDivisionByZero\n\t}\n\tif dividend.big == nil && divisor.big == nil &&\n\t\t(dividend.small != math.MinInt64 || divisor.small != -1) {\n\t\treturn FromInt64(dividend.small / divisor.small), nil\n\t}\n\treturn fromBig(new(big.Int).Quo(dividend.bigInt(), divisor.bigInt())), nil\n}\n\n// MustQuo is used by emitted code after Tesl has proved the divisor non-zero.\n// It still fails closed if compiler/runtime invariants drift.\nfunc MustQuo(dividend, divisor Int) Int {\n\tvalue, err := Quo(dividend, divisor)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\treturn value\n}\n\n// Rem is the truncating remainder. A non-zero result has the dividend's sign.\nfunc Rem(dividend, divisor Int) (Int, error) {\n\tif divisor.IsZero() {\n\t\treturn Int{}, ErrDivisionByZero\n\t}\n\tif dividend.big == nil && divisor.big == nil {\n\t\treturn FromInt64(dividend.small % divisor.small), nil\n\t}\n\treturn fromBig(new(big.Int).Rem(dividend.bigInt(), divisor.bigInt())), nil\n}\n\nfunc MustRem(dividend, divisor Int) Int {\n\tvalue, err := Rem(dividend, divisor)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\treturn value\n}\n\n// Mod matches Racket modulo: a non-zero result has the divisor's sign.\nfunc Mod(dividend, divisor Int) (Int, error) {\n\tremainder, err := Rem(dividend, divisor)\n\tif err != nil || remainder.IsZero() || remainder.Sign() == divisor.Sign() {\n\t\treturn remainder, err\n\t}\n\treturn Add(remainder, divisor), nil\n}\n\nfunc MustMod(dividend, divisor Int) Int {\n\tvalue, err := Mod(dividend, divisor)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\treturn value\n}\n\nfunc Pow(base, exponent Int) (Int, error) {\n\tif exponent.Sign() < 0 {\n\t\treturn Int{}, ErrNegativePower\n\t}\n\treturn fromBig(new(big.Int).Exp(base.bigInt(), exponent.bigInt(), nil)), nil\n}\n\nfunc GCD(left, right Int) Int {\n\treturn fromBig(new(big.Int).GCD(nil, nil, left.bigInt(), right.bigInt()))\n}\n\nfunc LCM(left, right Int) Int {\n\tif left.IsZero() || right.IsZero() {\n\t\treturn Int{}\n\t}\n\tgcd := GCD(left, right)\n\tquotient, err := Quo(Abs(left), gcd)\n\tif err != nil {\n\t\tpanic(\"unreachable: non-zero gcd\")\n\t}\n\treturn Mul(quotient, Abs(right))\n}\n\nfunc Min(left, right Int) Int {\n\tif Compare(left, right) <= 0 {\n\t\treturn left\n\t}\n\treturn right\n}\n\nfunc Max(left, right Int) Int {\n\tif Compare(left, right) >= 0 {\n\t\treturn left\n\t}\n\treturn right\n}\n\nfunc Clamp(value, low, high Int) Int {\n\treturn Max(low, Min(high, value))\n}\n\nfunc Compare(left, right Int) int {\n\tif left.big == nil && right.big == nil {\n\t\tswitch {\n\t\tcase left.small < right.small:\n\t\t\treturn -1\n\t\tcase left.small > right.small:\n\t\t\treturn 1\n\t\tdefault:\n\t\t\treturn 0\n\t\t}\n\t}\n\treturn left.bigInt().Cmp(right.bigInt())\n}\n\nfunc Equal(left, right Int) bool {\n\treturn Compare(left, right) == 0\n}\n\nfunc (n Int) Sign() int {\n\tif n.big != nil {\n\t\treturn n.big.Sign()\n\t}\n\tswitch {\n\tcase n.small < 0:\n\t\treturn -1\n\tcase n.small > 0:\n\t\treturn 1\n\tdefault:\n\t\treturn 0\n\t}\n}\n\nfunc (n Int) IsZero() bool {\n\treturn n.big == nil && n.small == 0\n}\n\nfunc (n Int) IsPositive() bool {\n\treturn n.Sign() > 0\n}\n\nfunc (n Int) IsNegative() bool {\n\treturn n.Sign() < 0\n}\n\nfunc (n Int) IsEven() bool {\n\tif n.big == nil {\n\t\treturn n.small%2 == 0\n\t}\n\treturn n.big.Bit(0) == 0\n}\n\nfunc (n Int) IsOdd() bool {\n\treturn !n.IsEven()\n}\n\nfunc (n Int) Digits() int {\n\ttext := n.String()\n\tif text[0] == '-' {\n\t\treturn len(text) - 1\n\t}\n\treturn len(text)\n}\n\nfunc (n Int) String() string {\n\tif n.big == nil {\n\t\treturn big.NewInt(n.small).String()\n\t}\n\treturn n.big.String()\n}\n\nfunc (n Int) Int64() (int64, bool) {\n\tif n.big != nil {\n\t\treturn 0, false\n\t}\n\treturn n.small, true\n}\n\nfunc (n Int) Float64() float64 {\n\tif n.big == nil {\n\t\treturn float64(n.small)\n\t}\n\tvalue, _ := new(big.Float).SetInt(n.big).Float64()\n\treturn value\n}\n\nfunc (n Int) Key() IntKey {\n\treturn IntKey(n.String())\n}\n\nfunc (n Int) Hash64() uint64 {\n\thash := fnv.New64a()\n\t_, _ = hash.Write([]byte(n.String()))\n\treturn hash.Sum64()\n}\n\nfunc (n Int) MarshalJSON() ([]byte, error) {\n\treturn []byte(n.String()), nil\n}\n\nfunc (n *Int) UnmarshalJSON(data []byte) error {\n\ttext := string(data)\n\tif !validJSONInteger(text) {\n\t\treturn ErrInvalidInt\n\t}\n\tvalue, err := ParseDecimal(text)\n\tif err != nil {\n\t\treturn err\n\t}\n\t*n = value\n\treturn nil\n}\n\nfunc validJSONInteger(value string) bool {\n\tif !validDecimal(value, false) {\n\t\treturn false\n\t}\n\tstart := 0\n\tif value[0] == '-' {\n\t\tstart = 1\n\t}\n\tif value[start] == '0' && len(value)-start > 1 {\n\t\treturn false\n\t}\n\treturn true\n}\n\n// IntNonZero and IntNonNegative are Tesl's `Int.nonZero` / `Int.nonNegative`\n// checks: the proof they mint erases, the rejection does not. The messages and the\n// 400 status are observable behavior and match the Racket implementations.\nfunc IntNonZero(value Int) Check[Int] {\n\tif value.IsZero() {\n\t\treturn Reject[Int](400, \"expected a non-zero integer\")\n\t}\n\treturn Accept(value)\n}\n\nfunc IntNonNegative(value Int) Check[Int] {\n\tif value.Sign() < 0 {\n\t\treturn Reject[Int](400, \"expected a non-negative integer\")\n\t}\n\treturn Accept(value)\n}\n\n// The Tesl.Int leaves the emitter calls as plain functions. Clamp, Pow, IsEven and IsOdd\n// already exist above; these are the wrappers for what is otherwise only a method, plus\n// the sign and power shapes Tesl's own signatures describe.\n\n// IntSign is -1, 0 or 1, matching Int.sign in tesl/int.rkt.\nfunc IntSign(value Int) Int {\n\treturn FromInt64(int64(value.Sign()))\n}\n\nfunc IntIsEven(value Int) bool {\n\treturn value.IsEven()\n}\n\nfunc IntIsOdd(value Int) bool {\n\treturn value.IsOdd()\n}\n\nfunc IntToString(value Int) string {\n\treturn value.String()\n}\n\n// MustPow raises rather than returning an error, matching Int.pow in tesl/int.rkt, which\n// rejects a negative exponent outright: there is no integer result, and Float.pow is the\n// function for a fractional one.\nfunc MustPow(base, exponent Int) Int {\n\tresult, err := Pow(base, exponent)\n\tif err != nil {\n\t\tpanic(\"Int.pow: \" + err.Error())\n\t}\n\treturn result\n}\n");
  ("json.go", "package teslrt\n\nimport (\n\t\"encoding/json\"\n\t\"fmt\"\n\t\"math/big\"\n\t\"sort\"\n\t\"strings\"\n)\n\n// JSON decoding for codecs.\n//\n// The one non-obvious requirement is INTEGER PRECISION. Tesl's Int is arbitrary\n// precision and Racket's JSON reader returns exact integers, so `{\"n\": 1234567890123\n// 45678901234567890}` round-trips there. Go's encoding/json decodes a number into\n// float64 when the target is `any`, which would silently round that to\n// 1.2345678901234568e+29 \226\128\148 wrong, and only for values above 2^53, so small tests would\n// never catch it. Every parse therefore goes through UseNumber and integers are read\n// from the decimal digits.\n//\n// Object key ORDER on the way out is alphabetical, matching Racket's `jsexpr->string`\n// (verified: it sorts). Go's own map marshalling sorts too, but a struct would emit in\n// field-declaration order, so encoding goes through a map rather than a generated\n// struct \226\128\148 the response bytes are observable and the two backends must agree.\n\n// ParseJSON parses a request body. A parse failure is the caller's to report, matching\n// the \"Malformed JSON payload\" 400 the Racket server produces.\nfunc ParseJSON(data []byte) (any, error) {\n\tdecoder := json.NewDecoder(strings.NewReader(string(data)))\n\tdecoder.UseNumber()\n\tvar value any\n\tif err := decoder.Decode(&value); err != nil {\n\t\treturn nil, err\n\t}\n\treturn value, nil\n}\n\n// jsonField returns the raw value at key. A missing field is an error rather than a\n// zero value: Racket raises `codec: required field \"x\" not found in JSON` here, and the\n// server turns any decode exception into a generic 400 \226\128\148 so the TEXT is not observable\n// by default, but the failure must still happen.\nfunc jsonField(object any, key string) (any, error) {\n\tfields, ok := object.(map[string]any)\n\tif !ok {\n\t\treturn nil, fmt.Errorf(\"codec: expected a JSON object\")\n\t}\n\tvalue, present := fields[key]\n\tif !present {\n\t\treturn nil, fmt.Errorf(\"codec: required field %q not found in JSON\", key)\n\t}\n\treturn value, nil\n}\n\n// HasJSONField reports whether a key is present, for an alternative that only applies\n// when a field exists.\nfunc HasJSONField(object any, key string) bool {\n\tfields, ok := object.(map[string]any)\n\tif !ok {\n\t\treturn false\n\t}\n\t_, present := fields[key]\n\treturn present\n}\n\nfunc DecodeStringField(object any, key string) (string, error) {\n\traw, err := jsonField(object, key)\n\tif err != nil {\n\t\treturn \"\", err\n\t}\n\ttext, ok := raw.(string)\n\tif !ok {\n\t\treturn \"\", fmt.Errorf(\"expected JSON string, got %v\", raw)\n\t}\n\treturn text, nil\n}\n\n// DecodeIntField reads the decimal digits rather than a float64, so an integer wider\n// than 2^53 survives.\nfunc DecodeIntField(object any, key string) (Int, error) {\n\traw, err := jsonField(object, key)\n\tif err != nil {\n\t\treturn Int{}, err\n\t}\n\tnumber, ok := raw.(json.Number)\n\tif !ok {\n\t\treturn Int{}, fmt.Errorf(\"expected JSON integer, got %v\", raw)\n\t}\n\tdigits := number.String()\n\tvalue, ok := new(big.Int).SetString(digits, 10)\n\tif !ok {\n\t\treturn Int{}, fmt.Errorf(\"expected JSON integer, got %v\", digits)\n\t}\n\treturn fromBig(value), nil\n}\n\nfunc DecodeBoolField(object any, key string) (bool, error) {\n\traw, err := jsonField(object, key)\n\tif err != nil {\n\t\treturn false, err\n\t}\n\tflag, ok := raw.(bool)\n\tif !ok {\n\t\treturn false, fmt.Errorf(\"expected JSON boolean, got %v\", raw)\n\t}\n\treturn flag, nil\n}\n\nfunc DecodeFloatField(object any, key string) (float64, error) {\n\traw, err := jsonField(object, key)\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\tnumber, ok := raw.(json.Number)\n\tif !ok {\n\t\treturn 0, fmt.Errorf(\"expected JSON number, got %v\", raw)\n\t}\n\treturn number.Float64()\n}\n\n// DecodeStringValue decodes an already-extracted value, for a nested codec whose field\n// was read by the caller (an `adtJson` type decodes from a bare JSON string).\nfunc DecodeStringValue(raw any) (string, error) {\n\ttext, ok := raw.(string)\n\tif !ok {\n\t\treturn \"\", fmt.Errorf(\"expected JSON string, got %v\", raw)\n\t}\n\treturn text, nil\n}\n\nfunc JSONFieldValue(object any, key string) (any, error) {\n\treturn jsonField(object, key)\n}\n\n// EncodeJSON renders an object. Keys are emitted in sorted order to match Racket, which\n// is why this takes a map rather than marshalling a generated struct.\nfunc EncodeJSON(fields map[string]any) string {\n\tvar builder strings.Builder\n\tbuilder.WriteByte('{')\n\tkeys := make([]string, 0, len(fields))\n\tfor key := range fields {\n\t\tkeys = append(keys, key)\n\t}\n\tsort.Strings(keys)\n\tfor index, key := range keys {\n\t\tif index > 0 {\n\t\t\tbuilder.WriteByte(',')\n\t\t}\n\t\tname, _ := json.Marshal(key)\n\t\tbuilder.Write(name)\n\t\tbuilder.WriteByte(':')\n\t\tbuilder.WriteString(EncodeJSONValue(fields[key]))\n\t}\n\tbuilder.WriteByte('}')\n\treturn builder.String()\n}\n\n// EncodeJSONValue renders one value. `Int` is rendered from its decimal digits so a\n// bignum is not routed through a float, and a nested object keeps the sorted-key rule.\nfunc EncodeJSONValue(value any) string {\n\tswitch typed := value.(type) {\n\tcase Int:\n\t\treturn typed.String()\n\tcase map[string]any:\n\t\treturn EncodeJSON(typed)\n\tcase []any:\n\t\tparts := make([]string, len(typed))\n\t\tfor index, element := range typed {\n\t\t\tparts[index] = EncodeJSONValue(element)\n\t\t}\n\t\treturn \"[\" + strings.Join(parts, \",\") + \"]\"\n\tcase float64:\n\t\treturn FormatFloat(typed)\n\tdefault:\n\t\tencoded, err := json.Marshal(typed)\n\t\tif err != nil {\n\t\t\tpanic(\"codec: value cannot be encoded as JSON\")\n\t\t}\n\t\treturn string(encoded)\n\t}\n}\n\n// DecodeObjectShape is the shape check a DERIVED record decoder runs before reading any\n// field: a record with no `codec` block still decodes from JSON, and the rule it follows is\n// the Racket runtime's generic decode (dsl/types.rkt `jsexpr->typed-value`) \226\128\148 the object's\n// keys must be EXACTLY the record's fields. A missing field is a 400 because the field has no\n// value to take, and an EXTRA field is a 400 too, which is the surprising half: silently\n// ignoring unknown keys is how a typo'd field name becomes a silent default.\nfunc DecodeObjectShape(raw any, typeName string, expected []string) (map[string]any, error) {\n\tfields, ok := raw.(map[string]any)\n\tif !ok {\n\t\treturn nil, fmt.Errorf(\"expected record JSON for type %s, got %v\", typeName, raw)\n\t}\n\tmissing := make([]string, 0, len(expected))\n\tfor _, name := range expected {\n\t\tif _, present := fields[name]; !present {\n\t\t\tmissing = append(missing, name)\n\t\t}\n\t}\n\tif len(missing) > 0 {\n\t\treturn nil, fmt.Errorf(\"record JSON for type %s is missing field%s (%s)\",\n\t\t\ttypeName, plural(len(missing)), strings.Join(missing, \" \"))\n\t}\n\textra := make([]string, 0, len(fields))\n\tfor name := range fields {\n\t\tif !containsName(expected, name) {\n\t\t\textra = append(extra, name)\n\t\t}\n\t}\n\tif len(extra) > 0 {\n\t\tsort.Strings(extra)\n\t\treturn nil, fmt.Errorf(\"record JSON for type %s has unexpected field%s (%s)\",\n\t\t\ttypeName, plural(len(extra)), strings.Join(extra, \" \"))\n\t}\n\treturn fields, nil\n}\n\nfunc plural(count int) string {\n\tif count == 1 {\n\t\treturn \"\"\n\t}\n\treturn \"s\"\n}\n\nfunc containsName(names []string, wanted string) bool {\n\tfor _, name := range names {\n\t\tif name == wanted {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// The value-level counterparts of the DecodeXField helpers, for a derived decoder that has\n// already taken the object apart (and for a list element, which has no key at all).\n\nfunc DecodeIntValue(raw any) (Int, error) {\n\tnumber, ok := raw.(json.Number)\n\tif !ok {\n\t\treturn Int{}, fmt.Errorf(\"expected JSON integer, got %v\", raw)\n\t}\n\tvalue, ok := new(big.Int).SetString(number.String(), 10)\n\tif !ok {\n\t\treturn Int{}, fmt.Errorf(\"expected JSON integer, got %v\", number.String())\n\t}\n\treturn fromBig(value), nil\n}\n\nfunc DecodeBoolValue(raw any) (bool, error) {\n\tflag, ok := raw.(bool)\n\tif !ok {\n\t\treturn false, fmt.Errorf(\"expected JSON boolean, got %v\", raw)\n\t}\n\treturn flag, nil\n}\n\nfunc DecodeFloatValue(raw any) (float64, error) {\n\tnumber, ok := raw.(json.Number)\n\tif !ok {\n\t\treturn 0, fmt.Errorf(\"expected JSON number, got %v\", raw)\n\t}\n\treturn number.Float64()\n}\n\n// DecodeListValue decodes a JSON array element-wise through `element`, so a derived decoder\n// composes over `List T` without the emitter writing the loop at every use.\nfunc DecodeListValue[Element any](raw any, element func(any) (Element, error)) ([]Element, error) {\n\titems, ok := raw.([]any)\n\tif !ok {\n\t\treturn nil, fmt.Errorf(\"expected JSON array, got %v\", raw)\n\t}\n\tout := make([]Element, 0, len(items))\n\tfor _, item := range items {\n\t\tdecoded, err := element(item)\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n\t\tout = append(out, decoded)\n\t}\n\treturn out, nil\n}\n");
  ("jwt.go", "package teslrt\n\nimport (\n\t\"crypto/hmac\"\n\t\"encoding/base64\"\n\t\"encoding/json\"\n\t\"fmt\"\n\t\"sort\"\n\t\"strings\"\n\t\"sync\"\n\t\"time\"\n)\n\n// `Tesl.JWT`: the one blessed session token \226\128\148 HS256, in one fixed cookie, with no options.\n//\n// The signature is HMAC-SHA256 over `header.payload`, which is `Tesl.Crypto`'s primitive, so a\n// token minted by either backend verifies on the other. Verification never PARSES the header:\n// it recomputes the MAC over the received bytes verbatim, which is why a foreign token, or one\n// minted before `kid` was stamped, verifies exactly the same.\n//\n// The rules below are the Racket runtime's, and several of them are fail-closed decisions worth\n// keeping visible rather than re-deriving:\n//\n//\ta structurally malformed token is a 401, never a trap \226\128\148 it comes off the wire, so\n//\t`Cookie: session=garbage` must not be a client-triggerable 500;\n//\tan unreadable `exp` means EXPIRED, not absent \226\128\148 skipping the check would accept such a\n//\ttoken forever;\n//\ta missing `exp` is accepted, because `exp` is OPTIONAL per RFC 7519 and Tesl cannot mint a\n//\ttoken without one, so this only admits a foreign token;\n//\trenewal refuses without a usable `iat`, because an unbounded-age token must not be\n//\trenewable \226\128\148 that bound is what makes \"no server-side revocation\" a defensible design.\ntype JwtToken struct {\n\tValue string\n}\n\nconst (\n\t// The renewable window and the hard stop on a renewed session's total lifetime. The cap is\n\t// named rather than derived: applying a multiplier to a shorter TTL silently yields a cap\n\t// nobody chose.\n\tjwtTTLSeconds         = 3600\n\tjwtAbsoluteMaxSeconds = 12 * jwtTTLSeconds\n\t// The only tolerance granted to an `iat` ahead of this machine's clock: enough for ordinary\n\t// NTP drift between replicas, too small to meaningfully extend a session.\n\tjwtMaxClockSkewSeconds = 60\n)\n\n// The OPTIONAL previous signing key. Verification accepts a token signed by either the current\n// key or this one, which is the overlap that lets a leaked key be rotated WITHOUT logging every\n// user out; signing and renewal always use the current key, so the slot drains on its own.\nvar (\n\tpreviousSessionKeyMutex sync.RWMutex\n\tpreviousSessionKey      *Secret\n)\n\n// SetPreviousSessionKey installs (or, with nil, clears) the rotation overlap. Clearing it while\n// rotating the current key is the global kill switch.\nfunc SetPreviousSessionKey(key *Secret) {\n\tpreviousSessionKeyMutex.Lock()\n\tdefer previousSessionKeyMutex.Unlock()\n\tpreviousSessionKey = key\n}\n\nfunc sessionKeys(current Secret) []string {\n\tpreviousSessionKeyMutex.RLock()\n\tdefer previousSessionKeyMutex.RUnlock()\n\tkeys := []string{current.Value.Reveal()}\n\tif previousSessionKey != nil {\n\t\tkeys = append(keys, previousSessionKey.Value.Reveal())\n\t}\n\treturn keys\n}\n\nfunc jwtNowSeconds() int64 { return time.Now().Unix() }\n\nfunc base64URL(raw []byte) string { return base64.RawURLEncoding.EncodeToString(raw) }\n\n// decodeBase64URL accepts the padded spelling too: a token arrives from another implementation,\n// and padding is the commonest harmless deviation.\nfunc decodeBase64URL(text string) ([]byte, bool) {\n\tif raw, err := base64.RawURLEncoding.DecodeString(text); err == nil {\n\t\treturn raw, true\n\t}\n\traw, err := base64.URLEncoding.DecodeString(text)\n\treturn raw, err == nil\n}\n\n// jwtHeader is assembled by string append rather than by marshalling a map, so the field order\n// is fixed (alg, typ, kid) and stable. `kid` is DERIVED from the key \226\128\148 a domain-separated,\n// truncated digest that is safe to log and is not proof of key possession \226\128\148 so there is no knob\n// here either, and no accessor: stamping is the part that is expensive to retrofit.\nfunc jwtHeader(key Secret) string {\n\treturn base64URL([]byte(`{\"alg\":\"HS256\",\"typ\":\"JWT\",\"kid\":\"` + KeyFingerprint(key) + `\"}`))\n}\n\nfunc jwtSignature(key, signingInput string) []byte {\n\treturn hmacSha256Bytes(key, signingInput)\n}\n\n// jwtPayload renders the claims. Keys are sorted so a token is a function of its claims and not\n// of map iteration order; `iat` and `exp` are NUMBERS, as RFC 7519 requires, while every claim a\n// program supplies is a String.\nfunc jwtPayload(claims Dict[string, string], issuedAt, expiresAt int64) string {\n\tvar builder strings.Builder\n\tbuilder.WriteString(\"{\")\n\tnames := make([]string, 0, len(claims.Entries))\n\tfor _, entry := range claims.Entries {\n\t\tnames = append(names, entry.Key)\n\t}\n\tsort.Strings(names)\n\tfor _, name := range names {\n\t\tvalue, _ := DictLookup(claims, name, stringKeyLess).Value()\n\t\tencoded, err := json.Marshal(value)\n\t\tif err != nil {\n\t\t\tpanic(\"JWT.sign: a claim value could not be encoded: \" + err.Error())\n\t\t}\n\t\tkey, err := json.Marshal(name)\n\t\tif err != nil {\n\t\t\tpanic(\"JWT.sign: a claim name could not be encoded: \" + err.Error())\n\t\t}\n\t\tbuilder.Write(key)\n\t\tbuilder.WriteString(\":\")\n\t\tbuilder.Write(encoded)\n\t\tbuilder.WriteString(\",\")\n\t}\n\tfmt.Fprintf(&builder, `\"iat\":%d,\"exp\":%d}`, issuedAt, expiresAt)\n\treturn base64URL([]byte(builder.String()))\n}\n\n// JwtSign is `JWT.sign`. It stamps BOTH `iat` and `exp` itself: `exp` because a caller who can\n// choose an expiry can choose ten years, and `iat` because renewal reads it to bound the total\n// lifetime of a session.\nfunc JwtSign(claims Dict[string, string], key Secret) JwtToken {\n\tfor _, reserved := range []string{\"exp\", \"iat\"} {\n\t\tif _, present := DictLookup(claims, reserved, stringKeyLess).Value(); present {\n\t\t\tpanic(fmt.Sprintf(\n\t\t\t\t\"JWT.sign: %s is not yours to set: JWT.sign stamps it itself, and there is no \"+\n\t\t\t\t\t\"parameter for it. Remove %s from the claims. If you need a credential that \"+\n\t\t\t\t\t\"outlives a session, a JWT is the wrong tool: use `Crypto.randomToken` and \"+\n\t\t\t\t\t\"store only its `Crypto.fingerprint`, which you can revoke.\", reserved, reserved))\n\t\t}\n\t}\n\tnow := jwtNowSeconds()\n\treturn signClaims(claims, key, now, now+jwtTTLSeconds)\n}\n\nfunc signClaims(claims Dict[string, string], key Secret, issuedAt, expiresAt int64) JwtToken {\n\tsigningInput := jwtHeader(key) + \".\" + jwtPayload(claims, issuedAt, expiresAt)\n\treturn JwtToken{\n\t\tValue: signingInput + \".\" + base64URL(jwtSignature(key.Value.Reveal(), signingInput)),\n\t}\n}\n\n// verifiedClaims is the parsed payload of a token whose signature checked out.\ntype verifiedClaims struct {\n\traw map[string]any\n}\n\n// verifyToken is the shared half of `JWT.verify` and `JWT.renew`, so the signature comparison,\n// the malformed-token rejections and the expiry rule cannot drift between verifying and\n// renewing.\nfunc verifyToken(token JwtToken, key Secret) (verifiedClaims, Check[Dict[string, string]]) {\n\tparts := strings.Split(token.Value, \".\")\n\tif len(parts) != 3 {\n\t\treturn verifiedClaims{}, Reject[Dict[string, string]](401, \"Invalid JWT format\")\n\t}\n\tsigningInput := parts[0] + \".\" + parts[1]\n\t// A signature segment that is not valid base64url falls through to the comparison with an\n\t// empty tag (which fails) rather than raising out of the handler.\n\tactual, _ := decodeBase64URL(parts[2])\n\tmatched := false\n\tfor _, candidate := range sessionKeys(key) {\n\t\t// Every candidate is compared in constant time; the NUMBER of keys (one or two) is not\n\t\t// secret.\n\t\tif hmac.Equal(jwtSignature(candidate, signingInput), actual) {\n\t\t\tmatched = true\n\t\t}\n\t}\n\tif !matched {\n\t\treturn verifiedClaims{}, Reject[Dict[string, string]](401, \"Invalid JWT signature\")\n\t}\n\tpayload, ok := decodeBase64URL(parts[1])\n\tif !ok {\n\t\treturn verifiedClaims{}, Reject[Dict[string, string]](401, \"Malformed JWT payload\")\n\t}\n\tdecoded, err := ParseJSON(payload)\n\tif err != nil {\n\t\treturn verifiedClaims{}, Reject[Dict[string, string]](401, \"Malformed JWT payload\")\n\t}\n\tclaims, isObject := decoded.(map[string]any)\n\tif !isObject {\n\t\treturn verifiedClaims{}, Reject[Dict[string, string]](401, \"Malformed JWT payload\")\n\t}\n\tif jwtExpired(claims) {\n\t\treturn verifiedClaims{}, Reject[Dict[string, string]](401, \"JWT token has expired\")\n\t}\n\treturn verifiedClaims{raw: claims}, Check[Dict[string, string]]{}\n}\n\n// jwtExpired reads `exp`. A MISSING claim means no expiry check (it is optional per the RFC and\n// Tesl always stamps one, so this only admits a foreign token); an UNREADABLE one means expired,\n// because skipping the check on a claim that cannot be read would accept the token forever.\nfunc jwtExpired(claims map[string]any) bool {\n\texpiry, present := claims[\"exp\"]\n\tif !present {\n\t\treturn false\n\t}\n\tseconds, ok := jsonSeconds(expiry)\n\tif !ok {\n\t\treturn true\n\t}\n\treturn seconds < jwtNowSeconds()\n}\n\nfunc jsonSeconds(value any) (int64, bool) {\n\tnumber, ok := value.(json.Number)\n\tif !ok {\n\t\treturn 0, false\n\t}\n\tif exact, err := number.Int64(); err == nil {\n\t\treturn exact, true\n\t}\n\t// A non-integral or oversized numeric claim: read it as a float and floor it, so a token\n\t// written by an implementation that emits `1.7853556e9` is still judged rather than refused.\n\tif approximate, err := number.Float64(); err == nil {\n\t\treturn int64(approximate), true\n\t}\n\treturn 0, false\n}\n\n// claimText renders a claim value as a String, which is what `Dict String String` promises. The\n// rule is `JWT.decode`'s, applied to verification too: a string is itself, a number or boolean\n// is its JSON text, null is \"null\", and an array or object is its compact JSON text.\n//\n// A note for authorization: an array claim decodes to JSON TEXT, which IS substring-matchable \226\128\148\n// do not branch on `String.contains` over it.\nfunc claimText(value any) string {\n\tswitch typed := value.(type) {\n\tcase nil:\n\t\treturn \"null\"\n\tcase string:\n\t\treturn typed\n\tcase bool:\n\t\tif typed {\n\t\t\treturn \"true\"\n\t\t}\n\t\treturn \"false\"\n\tcase json.Number:\n\t\treturn typed.String()\n\tdefault:\n\t\tencoded, err := json.Marshal(typed)\n\t\tif err != nil {\n\t\t\treturn fmt.Sprint(typed)\n\t\t}\n\t\treturn string(encoded)\n\t}\n}\n\nfunc claimsDict(claims map[string]any) Dict[string, string] {\n\tout := DictEmpty[string, string]()\n\tfor name, value := range claims {\n\t\tout = DictInsert(out, name, claimText(value), stringKeyLess)\n\t}\n\treturn out\n}\n\n// JwtVerify is `JWT.verify`: the claims of a token whose signature and expiry check out, or a\n// 401. On success the claims carry an `Authentic` fact, which erases \226\128\148 what it buys is that\n// \"trusted a cookie without verifying it\" stops compiling.\nfunc JwtVerify(token JwtToken, key Secret) Check[Dict[string, string]] {\n\tverified, rejection := verifyToken(token, key)\n\tif verified.raw == nil {\n\t\treturn rejection\n\t}\n\treturn Accept(claimsDict(verified.raw))\n}\n\n// JwtDecode is `JWT.decode`: the claims WITHOUT verifying anything. It exists for reading a\n// token you have not authenticated (an `iss` to decide which key to check it with, say), and\n// its result must never be trusted \226\128\148 which is why it mints no fact.\nfunc JwtDecode(token JwtToken) Dict[string, string] {\n\tparts := strings.Split(token.Value, \".\")\n\tif len(parts) != 3 {\n\t\tpanic(\"JWT.decode: malformed JWT: expected three dot-separated segments\")\n\t}\n\tpayload, ok := decodeBase64URL(parts[1])\n\tif !ok {\n\t\tpanic(\"JWT.decode: malformed JWT payload: not base64url\")\n\t}\n\tdecoded, err := ParseJSON(payload)\n\tif err != nil {\n\t\tpanic(\"JWT.decode: malformed JWT payload: \" + err.Error())\n\t}\n\tclaims, isObject := decoded.(map[string]any)\n\tif !isObject {\n\t\tpanic(\"JWT.decode: malformed JWT payload: the claims must be a JSON object\")\n\t}\n\treturn claimsDict(claims)\n}\n\n// JwtRenew is `JWT.renew`: it slides the session window forward, preserving every claim and the\n// ORIGINAL `iat`, so an active user is never logged out mid-task while an idle one still expires.\n//\n// It exists as a function because re-signing by hand is a trap: the verified claims contain\n// `exp` and `iat`, `JWT.sign` refuses both, and an author who rebuilds the dict to strip them\n// silently drops any claim they forget \226\128\148 downgrading the session on every renewal.\n//\n// It REFUSES when the token carries no usable `iat` (absent, not an exact non-negative integer,\n// or dated in the future beyond the skew allowance), or when the session has lived its absolute\n// maximum. Renewal is presented WITH the token, so a captured token can be renewed exactly as a\n// legitimate one can; the hard stop is what keeps \"a captured token is useful for a bounded\n// time\" true in a design with no server-side revocation.\nfunc JwtRenew(token JwtToken, key Secret) Check[JwtToken] {\n\tverified, rejection := verifyToken(token, key)\n\tif verified.raw == nil {\n\t\treturn Reject[JwtToken](rejection.Status(), rejection.Message())\n\t}\n\tnow := jwtNowSeconds()\n\tissuedAt, usable := jsonSeconds(verified.raw[\"iat\"])\n\tif !usable || issuedAt < 0 || issuedAt > now+jwtMaxClockSkewSeconds {\n\t\treturn Reject[JwtToken](401, \"Session cannot be renewed\")\n\t}\n\tif now-issuedAt > jwtAbsoluteMaxSeconds {\n\t\treturn Reject[JwtToken](401, \"Session has reached its maximum lifetime\")\n\t}\n\t// Every claim travels across except the two this function owns.\n\tcarried := DictEmpty[string, string]()\n\tfor name, value := range verified.raw {\n\t\tif name == \"exp\" || name == \"iat\" {\n\t\t\tcontinue\n\t\t}\n\t\tcarried = DictInsert(carried, name, claimText(value), stringKeyLess)\n\t}\n\treturn Accept(signClaims(carried, key, issuedAt, now+jwtTTLSeconds))\n}\n\n// JwtTokenText is the token as it travels \226\128\148 what a cookie writer puts on the wire.\nfunc JwtTokenText(token JwtToken) string { return token.Value }\n");
  ("list.go", "package teslrt\n\nimport (\n\t\"slices\"\n\t\"strings\"\n)\n\n// Tesl's `List a` is a Go slice, which buys idiomatic, readable emitted code. A Tesl\n// list is immutable, and nothing in a Tesl program can mutate one, so aliasing is\n// only ever observable if a function in THIS FILE writes into a backing array some\n// other Tesl value can still see. That gives the one invariant this file must never\n// break:\n//\n//\tONLY WRITERS ALLOCATE. READERS MAY ALIAS.\n//\n// So Take/Drop/Tail return plain sub-slice views in O(1), while the writers \226\128\148\n// anything append-like, plus SortBy, which sorts in place \226\128\148 build a fresh array\n// first. The combination that would be a soundness bug is a zero-copy view PLUS a\n// capacity-reusing append: `append(xs[:2], v)` writes index 2, which a longer live\n// value still sees. Since both halves live here, forbidding capacity reuse in the\n// writers is sufficient, and copying in the readers would be redundant.\n//\n// Any list writer added later must honour the same rule.\n//\n// Views are BOUNDED, because a slice keeps its whole backing array alive: a\n// `List.take 1` of a 10,000-row query result would otherwise pin all 10,000 rows for\n// as long as that one-element value lives. See boundedView.\n//\n// Remaining consequence, accepted deliberately: this is an invariant of the runtime,\n// not of the emitted module code. A Go author who sheds Tesl and appends to a Take\n// result reintroduces the classic aliasing bug \226\128\148 out of scope by design, rather than\n// paid for with O(n) on every read.\n//\n// Functions needing equality or ordering take it as a parameter. A generic Go\n// function cannot compare a `T` \226\128\148 `teslrt.Int` is deliberately non-comparable \226\128\148 but\n// the EMITTER knows the concrete element type at every call site and passes the\n// comparison in.\nfunc ListLength[T any](xs []T) Int {\n\treturn FromInt64(int64(len(xs)))\n}\n\nfunc ListIsEmpty[T any](xs []T) bool {\n\treturn len(xs) == 0\n}\n\n// ListHead is Nothing for an empty list rather than a panic: Tesl's `List.head`\n// returns `Maybe a`.\nfunc ListHead[T any](xs []T) Maybe[T] {\n\tif len(xs) == 0 {\n\t\treturn Nothing[T]()\n\t}\n\treturn Something(xs[0])\n}\n\n// ListTail drops the first element, or Nothing when there is none. The result is a\n// (bounded) view: no writer can reach the shared array \226\128\148 see the invariant above.\nfunc ListTail[T any](xs []T) Maybe[[]T] {\n\tif len(xs) == 0 {\n\t\treturn Nothing[[]T]()\n\t}\n\treturn Something(boundedView(xs[1:], xs))\n}\n\nfunc ListLast[T any](xs []T) Maybe[T] {\n\tif len(xs) == 0 {\n\t\treturn Nothing[T]()\n\t}\n\treturn Something(xs[len(xs)-1])\n}\n\n// ListAppend is a WRITER, so it allocates: appending into either input's spare\n// capacity is exactly the mutation the invariant above forbids.\nfunc ListAppend[T any](left, right []T) []T {\n\tout := make([]T, 0, len(left)+len(right))\n\tout = append(out, left...)\n\tout = append(out, right...)\n\treturn out\n}\n\n// ListTake and ListDrop are READERS: they return bounded views, clamping the count to\n// the list length. A negative count is a programming error the Racket backend rejects\n// at runtime, so it panics here rather than silently behaving like zero.\nfunc ListTake[T any](count Int, xs []T) []T {\n\treturn boundedView(xs[:clampCount(\"List.take\", count, len(xs))], xs)\n}\n\nfunc ListDrop[T any](count Int, xs []T) []T {\n\treturn boundedView(xs[clampCount(\"List.drop\", count, len(xs)):], xs)\n}\n\n// viewSlack is the array size a view may pin outright. Below it the retention is\n// irrelevant and a copy would be pure overhead.\nconst viewSlack = 32\n\n// boundedView keeps a reader O(1) while capping how much array a small result can\n// pin: past the slack, a view may retain at most twice its own length, and otherwise\n// copies. The copy costs O(len(out)) \226\128\148 by construction less than half the memory it\n// releases \226\128\148 so this cannot turn a cheap read into an expensive one.\nfunc boundedView[T any](out, source []T) []T {\n\tif cap(source) > viewSlack && cap(source) > 2*len(out) {\n\t\treturn cloneExact(out)\n\t}\n\treturn out\n}\n\nfunc clampCount(who string, count Int, length int) int {\n\tif count.Sign() < 0 {\n\t\tpanic(who + \": count must be non-negative\")\n\t}\n\tvalue, ok := count.Int64()\n\tif !ok || value > int64(length) {\n\t\treturn length\n\t}\n\treturn int(value)\n}\n\nfunc ListReverse[T any](xs []T) []T {\n\tout := make([]T, len(xs))\n\tfor index, value := range xs {\n\t\tout[len(xs)-1-index] = value\n\t}\n\treturn out\n}\n\nfunc ListSum(xs []Int) Int {\n\ttotal := FromInt64(0)\n\tfor _, value := range xs {\n\t\ttotal = Add(total, value)\n\t}\n\treturn total\n}\n\n// ListProduct is the product of every element, and of NO element it is 1 \226\128\148 the identity, which\n// is what `(apply * '())` answers in tesl/list.rkt. Answering 0 for the empty list would make\n// `product (xs ++ ys)` stop agreeing with `product xs * product ys`.\nfunc ListProduct(xs []Int) Int {\n\ttotal := FromInt64(1)\n\tfor _, value := range xs {\n\t\ttotal = Mul(total, value)\n\t}\n\treturn total\n}\n\nfunc ListMemberBy[T any](needle T, xs []T, equal func(T, T) bool) bool {\n\tfor _, value := range xs {\n\t\tif equal(needle, value) {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// ListUniqueBy keeps the FIRST occurrence and preserves order, matching Racket's\n// hash-based `List.unique`. It writes only into its own fresh array.\nfunc ListUniqueBy[T any](xs []T, equal func(T, T) bool) []T {\n\tout := make([]T, 0, len(xs))\n\tfor _, value := range xs {\n\t\tif !ListMemberBy(value, out, equal) {\n\t\t\tout = append(out, value)\n\t\t}\n\t}\n\treturn out\n}\n\n// ListSortBy is STABLE, matching Racket's `sort`, and sorts a copy so the input\n// value is untouched.\nfunc ListSortBy[T any](xs []T, less func(T, T) bool) []T {\n\tout := cloneExact(xs)\n\tslices.SortStableFunc(out, func(left, right T) int {\n\t\tswitch {\n\t\tcase less(left, right):\n\t\t\treturn -1\n\t\tcase less(right, left):\n\t\t\treturn 1\n\t\tdefault:\n\t\t\treturn 0\n\t\t}\n\t})\n\treturn out\n}\n\nfunc ListEqualBy[T any](left, right []T, equal func(T, T) bool) bool {\n\tif len(left) != len(right) {\n\t\treturn false\n\t}\n\tfor index := range left {\n\t\tif !equal(left[index], right[index]) {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n\n// cloneExact gives a writer a private array to work in.\nfunc cloneExact[T any](xs []T) []T {\n\tout := make([]T, len(xs))\n\tcopy(out, xs)\n\treturn out\n}\n\n// StringSplit matches Racket's `string-split` with #:trim? #f: separators are not\n// collapsed, leading and trailing empties are kept, and splitting \"\" yields [\"\"].\nfunc StringSplit(s, sep string) []string {\n\tif s == \"\" {\n\t\treturn []string{\"\"}\n\t}\n\treturn strings.Split(s, sep)\n}\n\nfunc StringJoin(parts []string, sep string) string {\n\treturn strings.Join(parts, sep)\n}\n\n// exactCount converts a proven-non-negative Int to a length. The frontend has already\n// discharged `IsNonNegative`, so a negative value here means the emitter let an unproven\n// call through; a count that does not fit cannot be allocated at all, and Racket would\n// exhaust memory attempting it, so both panic rather than silently truncating to a\n// wrong-length list.\nfunc exactCount(who string, count Int) int {\n\tif count.Sign() < 0 {\n\t\tpanic(who + \": count must be non-negative\")\n\t}\n\tvalue, ok := count.Int64()\n\tif !ok || value > int64(maxAllocElements) {\n\t\tpanic(who + \": count is too large to allocate\")\n\t}\n\treturn int(value)\n}\n\n// maxAllocElements bounds a single constructed list. Not a language limit \226\128\148 the point\n// past which the allocation cannot succeed anyway, reported as a clear panic rather than\n// an out-of-memory kill.\nconst maxAllocElements = 1 << 31\n\n// ListRange is start INCLUSIVE to end EXCLUSIVE, matching `for/list ([i (in-range \226\128\166)])`\n// in tesl/list.rkt, and empty when start >= end.\nfunc ListRange(start, end Int) []Int {\n\tif Compare(start, end) >= 0 {\n\t\treturn []Int{}\n\t}\n\tspan := exactCount(\"List.range\", Sub(end, start))\n\tout := make([]Int, span)\n\tcurrent := start\n\tfor index := range out {\n\t\tout[index] = current\n\t\tcurrent = Add(current, FromInt64(1))\n\t}\n\treturn out\n}\n\n// ListRepeat holds n copies of one value. `n` carries an IsNonNegative proof, so the\n// check here is containment rather than the enforcement.\nfunc ListRepeat[T any](value T, n Int) []T {\n\tout := make([]T, exactCount(\"List.repeat\", n))\n\tfor index := range out {\n\t\tout[index] = value\n\t}\n\treturn out\n}\n\n// ListConcat flattens ONE level, like `List.concat`/`List.flatten`. It sizes the result\n// first, so a list of n lists costs one allocation rather than n appends.\nfunc ListConcat[T any](xss [][]T) []T {\n\ttotal := 0\n\tfor _, xs := range xss {\n\t\ttotal += len(xs)\n\t}\n\tout := make([]T, 0, total)\n\tfor _, xs := range xss {\n\t\tout = append(out, xs...)\n\t}\n\treturn out\n}\n\n// ListMaximum and ListMinimum are Nothing for the empty list. Ordering comes in from the\n// emitter, which knows the concrete element type at each call site.\nfunc ListMaximum[T any](xs []T, less func(T, T) bool) Maybe[T] {\n\tif len(xs) == 0 {\n\t\treturn Nothing[T]()\n\t}\n\tbest := xs[0]\n\tfor _, value := range xs[1:] {\n\t\tif less(best, value) {\n\t\t\tbest = value\n\t\t}\n\t}\n\treturn Something(best)\n}\n\nfunc ListMinimum[T any](xs []T, less func(T, T) bool) Maybe[T] {\n\tif len(xs) == 0 {\n\t\treturn Nothing[T]()\n\t}\n\tbest := xs[0]\n\tfor _, value := range xs[1:] {\n\t\tif less(value, best) {\n\t\t\tbest = value\n\t\t}\n\t}\n\treturn Something(best)\n}\n");
  ("loadtest.go", "package teslrt\n\nimport (\n\t\"math\"\n\t\"sort\"\n\t\"testing\"\n\t\"time\"\n)\n\n// The load-test harness: an OPEN-MODEL scheduler, so latency measures what a client would see.\n//\n// Every rule here is copied from `dsl/load-test.rkt` deliberately, because the point of having it\n// on both backends is that the two sets of numbers are comparable:\n//\n//\trequests are sent at a FIXED arrival rate regardless of how long the last one took, and\n//\tlatency is measured from the SCHEDULED send time \226\128\148 a closed model (send, wait, send) hides\n//\texactly the queueing a load test exists to find, which is coordinated omission;\n//\twarm-up runs until p99 is steady (CV < 5% across three consecutive 2-second windows) or 30\n//\tseconds pass, and warm-up requests are NOT measured \226\128\148 otherwise the first JIT/allocation\n//\tcosts land in the p99 the assertion reads;\n//\tpercentiles are taken from the sorted sample by index (floor(p*n)), which is the same\n//\testimator, so a p99 here and a p99 there mean the same thing;\n//\tthe report is the same six lines, so a diff of two runs is a diff of the numbers.\n//\n// One request at a time, from one goroutine: the Racket harness is single-threaded, and matching\n// that is what makes the comparison about the RUNTIME rather than about how each harness spreads\n// work over cores.\nconst (\n\twarmupWindow      = 2 * time.Second\n\twarmupCVThreshold = 0.05\n\twarmupConsecutive = 3\n\twarmupMax         = 30 * time.Second\n)\n\n// LoadTestResult is the sample a run produced, in milliseconds.\ntype LoadTestResult struct {\n\tLatencies  []float64\n\tErrors     int\n\tTotal      int\n\tDurationS  float64\n\tThroughput float64\n\tErrorRate  float64\n}\n\n// RunLoadTest drives `request` at `rate` requests per second for `duration` seconds and reports\n// the sample. `request` answers the response status (an error is reported as 0), so the harness\n// can count a 4xx/5xx as an error without knowing anything about the program.\nfunc RunLoadTest(rate int, durationSeconds int, request func() int) LoadTestResult {\n\tif rate < 1 {\n\t\trate = 1\n\t}\n\tinterval := time.Duration(float64(time.Second) / float64(rate))\n\tresult := LoadTestResult{}\n\n\t// One request, measured from the time it was SCHEDULED to be sent.\n\tsend := func(scheduled time.Time) float64 {\n\t\tstatus := request()\n\t\tlatency := float64(time.Since(scheduled).Nanoseconds()) / 1e6\n\t\tresult.Total++\n\t\tif status == 0 || status >= 400 {\n\t\t\tresult.Errors++\n\t\t}\n\t\treturn latency\n\t}\n\n\t// \226\148\128\226\148\128 Warm-up: not measured \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\twarmupStart := time.Now()\n\twindowStart := time.Now()\n\twindow := []float64{}\n\trecent := []float64{}\n\tscheduled := time.Now()\n\tfor time.Since(warmupStart) < warmupMax {\n\t\twindow = append(window, send(scheduled))\n\t\tif time.Since(windowStart) >= warmupWindow {\n\t\t\trecent = append(recent, percentileOf(window, 0.99))\n\t\t\tif len(recent) > warmupConsecutive {\n\t\t\t\trecent = recent[len(recent)-warmupConsecutive:]\n\t\t\t}\n\t\t\tif len(recent) == warmupConsecutive &&\n\t\t\t\tcoefficientOfVariation(recent) < warmupCVThreshold {\n\t\t\t\tbreak\n\t\t\t}\n\t\t\twindow = window[:0]\n\t\t\twindowStart = time.Now()\n\t\t}\n\t\tscheduled = scheduled.Add(interval)\n\t\tif wait := time.Until(scheduled); wait > 0 {\n\t\t\ttime.Sleep(wait)\n\t\t}\n\t}\n\n\t// \226\148\128\226\148\128 Measurement \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\tresult.Total = 0\n\tresult.Errors = 0\n\tmeasureStart := time.Now()\n\tmeasureEnd := measureStart.Add(time.Duration(durationSeconds) * time.Second)\n\tscheduled = time.Now()\n\tfor time.Now().Before(measureEnd) {\n\t\tresult.Latencies = append(result.Latencies, send(scheduled))\n\t\tscheduled = scheduled.Add(interval)\n\t\tif wait := time.Until(scheduled); wait > 0 {\n\t\t\ttime.Sleep(wait)\n\t\t}\n\t}\n\tresult.DurationS = time.Since(measureStart).Seconds()\n\tif result.DurationS > 0 {\n\t\tresult.Throughput = float64(len(result.Latencies)) / result.DurationS\n\t}\n\tif result.Total > 0 {\n\t\tresult.ErrorRate = float64(result.Errors) / float64(result.Total)\n\t}\n\treturn result\n}\n\n// percentileOf takes the value at floor(p*n) of the sorted sample \226\128\148 the same estimator the Racket\n// harness uses, so the two report the same number for the same sample.\nfunc percentileOf(latencies []float64, p float64) float64 {\n\tif len(latencies) == 0 {\n\t\treturn math.Inf(1)\n\t}\n\tsorted := make([]float64, len(latencies))\n\tcopy(sorted, latencies)\n\tsort.Float64s(sorted)\n\tindex := int(math.Floor(p * float64(len(sorted))))\n\tif index >= len(sorted) {\n\t\tindex = len(sorted) - 1\n\t}\n\treturn sorted[index]\n}\n\nfunc coefficientOfVariation(values []float64) float64 {\n\tif len(values) < 2 {\n\t\treturn 1.0\n\t}\n\tsum := 0.0\n\tfor _, value := range values {\n\t\tsum += value\n\t}\n\tmean := sum / float64(len(values))\n\tif mean <= 0 {\n\t\treturn 1.0\n\t}\n\tvariance := 0.0\n\tfor _, value := range values {\n\t\tvariance += (value - mean) * (value - mean)\n\t}\n\tvariance /= float64(len(values) - 1)\n\treturn math.Sqrt(variance) / mean\n}\n\n// LoadTestMetric answers one of the metrics an `assert` names.\nfunc (result LoadTestResult) LoadTestMetric(name string) float64 {\n\tswitch name {\n\tcase \"p50\":\n\t\treturn percentileOf(result.Latencies, 0.50)\n\tcase \"p95\":\n\t\treturn percentileOf(result.Latencies, 0.95)\n\tcase \"p99\":\n\t\treturn percentileOf(result.Latencies, 0.99)\n\tcase \"p99.9\":\n\t\treturn percentileOf(result.Latencies, 0.999)\n\tcase \"errorRate\":\n\t\treturn result.ErrorRate\n\tcase \"throughput\":\n\t\treturn result.Throughput\n\tdefault:\n\t\tpanic(\"load-test: unknown metric \" + name)\n\t}\n}\n\n// ReportLoadTest prints the same six lines the Racket harness prints, so two runs diff cleanly.\n// It goes to the test log rather than stdout because a load test IS a test here.\nfunc ReportLoadTest(teslT *testing.T, result LoadTestResult) {\n\tteslT.Helper()\n\tteslT.Logf(\"  Load test results (%d requests in %.1fs):\", len(result.Latencies),\n\t\tresult.DurationS)\n\tteslT.Logf(\"    p50:  %.1fms  p95: %.1fms  p99: %.1fms  p99.9: %.1fms\",\n\t\tresult.LoadTestMetric(\"p50\"), result.LoadTestMetric(\"p95\"),\n\t\tresult.LoadTestMetric(\"p99\"), result.LoadTestMetric(\"p99.9\"))\n\tminimum, maximum := math.Inf(1), 0.0\n\tfor _, latency := range result.Latencies {\n\t\tminimum = math.Min(minimum, latency)\n\t\tmaximum = math.Max(maximum, latency)\n\t}\n\tif len(result.Latencies) == 0 {\n\t\tminimum = 0\n\t}\n\tteslT.Logf(\"    min: %.1fms  max: %.1fms  throughput: %.1frps  errors: %.2f%%\",\n\t\tminimum, maximum, result.Throughput, result.ErrorRate*100)\n\tteslT.Logf(\"    (measurements include in-process harness overhead)\")\n}\n\n// AssertLoadTest fails the test when a metric misses its threshold, naming the actual value \226\128\148\n// which is the whole content of a load-test failure.\nfunc AssertLoadTest(teslT *testing.T, result LoadTestResult, metric, operator string,\n\tthreshold float64) {\n\tteslT.Helper()\n\tactual := result.LoadTestMetric(metric)\n\tpassed := false\n\tswitch operator {\n\tcase \"<\":\n\t\tpassed = actual < threshold\n\tcase \"<=\":\n\t\tpassed = actual <= threshold\n\tcase \">\":\n\t\tpassed = actual > threshold\n\tcase \">=\":\n\t\tpassed = actual >= threshold\n\tdefault:\n\t\tpanic(\"load-test: unknown comparison \" + operator)\n\t}\n\tif !passed {\n\t\tteslT.Fatalf(\"load-test: assertion failed: %s %s %g (actual: %.2f)\",\n\t\t\tmetric, operator, threshold, actual)\n\t}\n}\n\n// LoadTestStatus is what a request thunk answers: the status an api-test response carries, or 0\n// when the request trapped. A trap is an error rather than a crash, because a load test that\n// dies on the first 500 measures nothing.\nfunc LoadTestStatus(response ApiResponse) int {\n\tstatus, exact := response.Status.Int64()\n\tif !exact {\n\t\treturn 0\n\t}\n\treturn int(status)\n}\n");
  ("maybe.go", "package teslrt\n\n// Maybe is Tesl's `Maybe a`. It lives in the runtime rather than being emitted per\n// module because a `Maybe` crosses module boundaries: two emitted packages that\n// each declared their own would produce incompatible Go types.\n//\n// The representation is the same flat tag+payload struct the emitter generates for\n// a user ADT, and Tag is exported for exactly that reason \226\128\148 an emitted package in\n// another module has to read it. The zero value is Nothing, matching Go's\n// zero-value convention as well as the tag order below.\ntype Maybe[A any] struct {\n\tTag            MaybeTag\n\tSomethingValue A\n}\n\n// MaybeTag identifies which variant a Maybe holds. The constants are an enum-like\n// set so the `exhaustive` linter can verify a switch over them.\ntype MaybeTag int\n\nconst (\n\tMaybeNothing MaybeTag = iota\n\tMaybeSomething\n)\n\n// Nothing is the empty Maybe. Emitted code writes the composite literal directly;\n// this exists for hand-written runtime code and for readable tests.\nfunc Nothing[A any]() Maybe[A] {\n\treturn Maybe[A]{Tag: MaybeNothing}\n}\n\n// Something wraps a present value.\nfunc Something[A any](value A) Maybe[A] {\n\treturn Maybe[A]{Tag: MaybeSomething, SomethingValue: value}\n}\n\n// IsSomething reports whether a value is present.\nfunc (m Maybe[A]) IsSomething() bool {\n\treturn m.Tag == MaybeSomething\n}\n\n// Value returns the wrapped value and whether it was present. The payload of a\n// Nothing is the zero value of A and must not be read as data; this signature\n// makes that impossible to do by accident.\nfunc (m Maybe[A]) Value() (A, bool) {\n\tif m.Tag != MaybeSomething {\n\t\tvar zero A\n\t\treturn zero, false\n\t}\n\treturn m.SomethingValue, true\n}\n");
  ("password.go", "package teslrt\n\nimport (\n\t\"crypto/rand\"\n\t\"crypto/subtle\"\n\t\"encoding/base64\"\n\t\"fmt\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n\n\t\"golang.org/x/crypto/argon2\"\n)\n\n// Password storage: Argon2id, in the SAME encoding the Racket runtime writes.\n//\n// This is the one place the emitted runtime takes a dependency outside Go's standard library\n// (`golang.org/x/crypto/argon2`), and it is a deliberate, approved decision rather than a\n// convenience: Racket hashes with libsodium's Argon2id, and the two alternatives are both\n// worse. Substituting stdlib PBKDF2 would mint hashes the Racket side cannot verify, so a\n// shared database becomes a silent lockout on migration; hand-writing Argon2id would put\n// hand-rolled cryptography in the runtime. The dependency ships ONLY with this file, which is\n// ONLY emitted for a program that stores passwords, so nothing else carries it.\n//\n// The encoding is the PHC string libsodium's `crypto_pwhash_str` produces at its INTERACTIVE\n// parameters:\n//\n//\t$argon2id$v=19$m=65536,t=2,p=1$<salt>$<hash>\n//\n// with standard-alphabet base64 and no padding, a 16-byte salt and a 32-byte tag. A hash\n// written by either backend therefore verifies on both \226\128\148 which is the whole point, and what a\n// test asserts against a real libsodium string.\nconst (\n\targonMemoryKiB = 64 * 1024 // libsodium crypto_pwhash_MEMLIMIT_INTERACTIVE, in KiB\n\targonTime      = 2         // libsodium crypto_pwhash_OPSLIMIT_INTERACTIVE\n\targonThreads   = 1\n\targonSaltBytes = 16\n\targonKeyBytes  = 32\n\n\t// A password longer than this is refused rather than hashed: hashing is deliberately\n\t// expensive, so an unbounded input is a denial-of-service amplifier. Same limit as the\n\t// Racket runtime's.\n\tmaxPasswordBytes = 1024\n)\n\n// PasswordHash is opaque to Tesl: it holds the PHC string, and a program can store it, verify\n// against it, or ask whether it needs re-minting \226\128\148 never read it apart.\ntype PasswordHash struct {\n\tValue string\n}\n\nfunc requirePasswordLength(who string, plaintext SecretString) {\n\tif len(plaintext.Reveal()) > maxPasswordBytes {\n\t\t// A rejection at the request boundary, not a crash: the input came from a client, and\n\t\t// inside a handler this answers 400 the way any other check rejection does.\n\t\tpanic(RequestRejection{\n\t\t\tStatus: 400,\n\t\t\tMessage: fmt.Sprintf(\n\t\t\t\t\"%s: password is too long: %d bytes, maximum is %d. Reject over-long input at \"+\n\t\t\t\t\t\"the request boundary; hashing it is a denial-of-service amplifier.\",\n\t\t\t\twho, len(plaintext.Reveal()), maxPasswordBytes),\n\t\t})\n\t}\n}\n\n// HashPassword is `Crypto.hashPassword`: a fresh random salt, then Argon2id at the interactive\n// parameters. The `::: HashFor plaintext` half of its Tesl type is compile-time only \226\128\148 the fact\n// is about the argument, and proofs erase \226\128\148 so what it buys is that storing the WRONG\n// password's hash does not compile.\n//\n// The plaintext arrives as a SecretString so that the emitted CALL SITE never handles it as an\n// ordinary string: a `secret Password = String` hands over its payload, and a plain String is\n// wrapped on the way in. The plaintext therefore exists only inside this file.\nfunc HashPassword(plaintext SecretString) PasswordHash {\n\trequirePasswordLength(\"Crypto.hashPassword\", plaintext)\n\tsalt := make([]byte, argonSaltBytes)\n\tif _, err := rand.Read(salt); err != nil {\n\t\tpanic(\"Crypto.hashPassword: no source of randomness: \" + err.Error())\n\t}\n\treturn PasswordHash{Value: encodeArgon2id(salt,\n\t\targon2.IDKey([]byte(plaintext.Reveal()), salt, argonTime, argonMemoryKiB, argonThreads,\n\t\t\targonKeyBytes))}\n}\n\nfunc encodeArgon2id(salt, key []byte) string {\n\traw := base64.RawStdEncoding\n\treturn fmt.Sprintf(\"$argon2id$v=%d$m=%d,t=%d,p=%d$%s$%s\",\n\t\targon2.Version, argonMemoryKiB, argonTime, argonThreads,\n\t\traw.EncodeToString(salt), raw.EncodeToString(key))\n}\n\n// argon2Params is what a stored PHC string says it was minted with.\ntype argon2Params struct {\n\tmemoryKiB uint32\n\ttime      uint32\n\tthreads   uint8\n\tsalt      []byte\n\tkey       []byte\n}\n\n// parseArgon2id reads a stored hash. Anything that is not an Argon2id v19 PHC string \226\128\148 a\n// foreign hash, a scheme that has been dropped, truncated text \226\128\148 fails to parse, and every\n// caller treats that as \"does not verify\" and \"needs re-minting\".\nfunc parseArgon2id(stored string) (argon2Params, bool) {\n\tfields := strings.Split(stored, \"$\")\n\t// \"\", \"argon2id\", \"v=19\", \"m=\226\128\166,t=\226\128\166,p=\226\128\166\", salt, key\n\tif len(fields) != 6 || fields[0] != \"\" || fields[1] != \"argon2id\" {\n\t\treturn argon2Params{}, false\n\t}\n\tif fields[2] != \"v=\"+strconv.Itoa(argon2.Version) {\n\t\treturn argon2Params{}, false\n\t}\n\tvar memory, time uint64\n\tvar threads uint64\n\tfor _, setting := range strings.Split(fields[3], \",\") {\n\t\tname, value, found := strings.Cut(setting, \"=\")\n\t\tif !found {\n\t\t\treturn argon2Params{}, false\n\t\t}\n\t\tparsed, err := strconv.ParseUint(value, 10, 32)\n\t\tif err != nil {\n\t\t\treturn argon2Params{}, false\n\t\t}\n\t\tswitch name {\n\t\tcase \"m\":\n\t\t\tmemory = parsed\n\t\tcase \"t\":\n\t\t\ttime = parsed\n\t\tcase \"p\":\n\t\t\tthreads = parsed\n\t\tdefault:\n\t\t\treturn argon2Params{}, false\n\t\t}\n\t}\n\tif memory == 0 || time == 0 || threads == 0 || threads > 255 {\n\t\treturn argon2Params{}, false\n\t}\n\traw := base64.RawStdEncoding\n\tsalt, saltErr := raw.DecodeString(fields[4])\n\tkey, keyErr := raw.DecodeString(fields[5])\n\tif saltErr != nil || keyErr != nil || len(salt) == 0 {\n\t\treturn argon2Params{}, false\n\t}\n\t// The tag length is FIXED at 32 bytes: that is what libsodium's `crypto_pwhash_str` writes,\n\t// and pinning it keeps the recomputation below free of a length taken from the stored string\n\t// (which would be an attacker-influenced integer conversion). A hash with any other tag\n\t// length is treated as unparseable \226\128\148 fail closed, and `needsRehash` says to re-mint it.\n\tif len(key) != argonKeyBytes {\n\t\treturn argon2Params{}, false\n\t}\n\treturn argon2Params{\n\t\tmemoryKiB: uint32(memory), time: uint32(time), threads: uint8(threads),\n\t\tsalt: salt, key: key,\n\t}, true\n}\n\nfunc verifyArgon2id(stored, candidate string) bool {\n\tparams, ok := parseArgon2id(stored)\n\tif !ok {\n\t\treturn false\n\t}\n\tcomputed := argon2.IDKey([]byte(candidate), params.salt, params.time, params.memoryKiB,\n\t\tparams.threads, argonKeyBytes)\n\treturn subtle.ConstantTimeCompare(computed, params.key) == 1\n}\n\n// timingEqualiser is a real hash of a random password at the CURRENT parameters, computed once\n// and reused. It exists so that verifying against a MISSING account costs the same as verifying\n// a wrong password \226\128\148 otherwise a login endpoint answers in microseconds for an unknown address\n// and in ~80ms for a known one, which enumerates the user table. Generated rather than\n// hardcoded so it cannot drift from the live parameters.\nvar (\n\ttimingEqualiserOnce sync.Once\n\ttimingEqualiserPHC  string\n)\n\nfunc timingEqualiser() string {\n\ttimingEqualiserOnce.Do(func() {\n\t\tfiller := make([]byte, 32)\n\t\tif _, err := rand.Read(filler); err != nil {\n\t\t\tpanic(\"Crypto.checkPassword: no source of randomness: \" + err.Error())\n\t\t}\n\t\ttimingEqualiserPHC = HashPassword(MakeSecret(string(filler))).Value\n\t})\n\treturn timingEqualiserPHC\n}\n\n// CheckPassword is `Crypto.checkPassword`. It takes a `Maybe PasswordHash` deliberately: a\n// missing account and a wrong password have to cost the same and answer the same, so `Nothing`\n// still performs a full verification \226\128\148 against the timing equaliser \226\128\148 and then fails with the\n// identical message. The caller does not have to know that this problem exists, which is the\n// point.\nfunc CheckPassword(stored Maybe[PasswordHash], candidate SecretString) Check[Maybe[PasswordHash]] {\n\trequirePasswordLength(\"Crypto.checkPassword\", candidate)\n\thash, present := stored.Value()\n\tphc := timingEqualiser()\n\tif present {\n\t\tphc = hash.Value\n\t}\n\tverified := verifyArgon2id(phc, candidate.Reveal())\n\tif !verified || !present {\n\t\treturn Reject[Maybe[PasswordHash]](401, \"invalid credentials\")\n\t}\n\treturn Accept(stored)\n}\n\n// NeedsRehash is `Crypto.needsRehash`: true when the stored hash was minted with weaker\n// parameters than the current ones, or in a format this runtime cannot parse at all (a foreign\n// hash, or one from a scheme that has been dropped) \226\128\148 in both cases the right move on the next\n// successful login is to re-mint, so both answer true.\n//\n// Tesl deliberately does NOT perform the rehash: a crypto function writing to the database\n// would be a hidden effect, and it is one explicit line in the application.\nfunc NeedsRehash(stored PasswordHash) bool {\n\tparams, ok := parseArgon2id(stored.Value)\n\tif !ok {\n\t\treturn true\n\t}\n\treturn params.memoryKiB < argonMemoryKiB || params.time < argonTime ||\n\t\tparams.threads != argonThreads\n}\n");
  ("queue.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"sort\"\n\t\"sync\"\n)\n\n// An in-memory job queue: the `backend: Memory` counterpart of tesl/queue.rkt's store.\n//\n// Jobs are dequeued in ENQUEUE ORDER. That is parity, not a detail: Racket's store is a\n// hash keyed by job id, and dequeuing it in hash order was a real bug (the PostgreSQL path\n// is `order by created_at asc`), fixed there with a monotonic sequence number. This store\n// keeps the sequence for the same reason.\n//\n// A payload is held as `any` because one queue may carry several job types; the emitter\n// knows them statically and passes a dispatcher that type-switches.\ntype Queue struct {\n\tmutex       sync.Mutex\n\tname        string\n\tmaxAttempts int\n\tnextSeq     int64\n\tjobs        map[string]*queuedJob\n}\n\ntype queuedJob struct {\n\tpayload  any\n\tstatus   string // \"pending\" | \"processing\" | \"dead\"\n\tattempts int\n\tseq      int64\n}\n\n// JobStatus values a test can ask about.\nconst (\n\tjobPending    = \"pending\"\n\tjobProcessing = \"processing\"\n\tjobDead       = \"dead\"\n)\n\nfunc NewQueue(name string, maxAttempts int) *Queue {\n\tif maxAttempts < 1 {\n\t\tmaxAttempts = 1\n\t}\n\treturn &Queue{name: name, maxAttempts: maxAttempts, jobs: map[string]*queuedJob{}}\n}\n\n// Enqueue stores a payload and answers the new job's id.\n//\n// The id is a UUID v7, NOT a counter: a process-local counter replayed ids after a restart,\n// which let a committed job id collide with a fresh one (the same reasoning as the Racket\n// side's move off gensym).\nfunc Enqueue(queue *Queue, payload any) string {\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\tid := UUIDv7()\n\tqueue.nextSeq++\n\tqueue.jobs[id] = &queuedJob{payload: payload, status: jobPending, seq: queue.nextSeq}\n\treturn id\n}\n\nfunc PendingJobCount(queue *Queue) Int {\n\treturn FromInt64(int64(queue.countWithStatus(jobPending)))\n}\n\nfunc DeadJobCount(queue *Queue) Int {\n\treturn FromInt64(int64(queue.countWithStatus(jobDead)))\n}\n\nfunc (queue *Queue) countWithStatus(status string) int {\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\tmatched := 0\n\tfor _, job := range queue.jobs {\n\t\tif job.status == status {\n\t\t\tmatched++\n\t\t}\n\t}\n\treturn matched\n}\n\n// dequeue claims the OLDEST job with `status`, marking it processing.\n//\n// The candidates carry their entry rather than being re-read from the map by id: a second\n// lookup would be a map read whose success only the surrounding lock explains, which is\n// exactly what nilaway (in the emitted-code gate) refuses to take on trust.\nfunc (queue *Queue) dequeue(status string) (string, any, int, bool) {\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\ttype candidate struct {\n\t\tid    string\n\t\tentry *queuedJob\n\t}\n\tcandidates := make([]candidate, 0, len(queue.jobs))\n\tfor id, job := range queue.jobs {\n\t\tif job.status == status {\n\t\t\tcandidates = append(candidates, candidate{id: id, entry: job})\n\t\t}\n\t}\n\tif len(candidates) == 0 {\n\t\treturn \"\", nil, 0, false\n\t}\n\toldest := candidates[0]\n\tfor _, next := range candidates[1:] {\n\t\tif next.entry.seq < oldest.entry.seq {\n\t\t\toldest = next\n\t\t}\n\t}\n\toldest.entry.status = jobProcessing\n\treturn oldest.id, oldest.entry.payload, oldest.entry.attempts, true\n}\n\n// DeadJob is one entry in a queue's dead letter. It is OPAQUE to Tesl \226\128\148 `deadJobs` is typed\n// `List DeadJob` and the type has no accessors \226\128\148 so it carries the job's identity for the\n// runtime's use and nothing a program can read: what a test does with the list is count it.\ntype DeadJob struct{ ID string }\n\n// DeadJobs is the dead letter's contents, oldest first. The order is by enqueue sequence\n// rather than by map iteration, matching the PostgreSQL path's `order by created_at asc`.\nfunc DeadJobs(queue *Queue) []DeadJob {\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\ttype entry struct {\n\t\tid  string\n\t\tseq int64\n\t}\n\tfound := make([]entry, 0, len(queue.jobs))\n\tfor id, job := range queue.jobs {\n\t\tif job.status == jobDead {\n\t\t\tfound = append(found, entry{id: id, seq: job.seq})\n\t\t}\n\t}\n\tsort.Slice(found, func(left, right int) bool { return found[left].seq < found[right].seq })\n\tdead := make([]DeadJob, 0, len(found))\n\tfor _, each := range found {\n\t\tdead = append(dead, DeadJob{ID: each.id})\n\t}\n\treturn dead\n}\n\n// ResetQueue empties the store, for a test block that starts from a fresh queue. The\n// sequence counter is deliberately NOT reset: it only has to be monotonic, and a counter that\n// restarts is how job ids came to repeat once already.\nfunc ResetQueue(queue *Queue) {\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\tqueue.jobs = map[string]*queuedJob{}\n}\n\n// JobOutcome is what a worker run produced, for the `expectJobOk` style assertions.\ntype JobOutcome struct {\n\tRan     bool   // a job was claimed at all\n\tOK      bool   // the worker returned without rejecting or trapping\n\tMessage string // the rejection or trap message, when OK is false\n}\n\n// ProcessNextJob runs the next pending job through `handler` and applies the retry rule:\n// success completes the job, failure increments attempts and either re-queues it or \226\128\148 once\n// attempts reach maxAttempts \226\128\148 moves it to the dead letter. Identical to the Racket\n// in-memory path, including that a TRAP counts as a failed attempt rather than propagating.\n//\n// The retry BACKOFF delay is deliberately not simulated here: the in-memory Racket path\n// does not sleep either, and a test that had to wait for an exponential backoff would be a\n// slow test rather than a truthful one.\nfunc ProcessNextJob(queue *Queue, handler func(any) JobOutcome) JobOutcome {\n\tid, payload, attempts, found := queue.dequeue(jobPending)\n\tif !found {\n\t\treturn JobOutcome{}\n\t}\n\toutcome := runJob(handler, payload)\n\tif outcome.OK {\n\t\tqueue.complete(id)\n\t} else {\n\t\tqueue.fail(id, attempts)\n\t}\n\toutcome.Ran = true\n\treturn outcome\n}\n\n// ProcessNextDeadJob is the dead-letter counterpart: it claims a job that exhausted its\n// attempts and hands it to the dead-letter worker. A dead job is REMOVED whatever the\n// outcome \226\128\148 there is no second dead letter to fall into.\nfunc ProcessNextDeadJob(queue *Queue, handler func(any) JobOutcome) JobOutcome {\n\tid, payload, _, found := queue.dequeue(jobDead)\n\tif !found {\n\t\treturn JobOutcome{}\n\t}\n\toutcome := runJob(handler, payload)\n\tqueue.complete(id)\n\toutcome.Ran = true\n\treturn outcome\n}\n\n// DrainQueue processes pending jobs until none remain, and reports how many ran. It stops\n// at `limit` attempts so a job that keeps failing back into the queue cannot spin forever.\nfunc DrainQueue(queue *Queue, handler func(any) JobOutcome, limit int) Int {\n\tran := 0\n\tfor ran < limit {\n\t\tif outcome := ProcessNextJob(queue, handler); !outcome.Ran {\n\t\t\tbreak\n\t\t}\n\t\tran++\n\t}\n\treturn FromInt64(int64(ran))\n}\n\n// A worker that traps is a FAILED ATTEMPT, not a crashed process: the Racket path wraps the\n// handler in `with-handlers` and calls fail-job!, so the queue keeps its retry semantics.\nfunc runJob(handler func(any) JobOutcome, payload any) (outcome JobOutcome) {\n\tdefer func() {\n\t\tif recovered := recover(); recovered != nil {\n\t\t\toutcome = JobOutcome{OK: false, Message: fmt.Sprint(recovered)}\n\t\t}\n\t}()\n\treturn handler(payload)\n}\n\nfunc (queue *Queue) complete(id string) {\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\tdelete(queue.jobs, id)\n}\n\nfunc (queue *Queue) fail(id string, attempts int) {\n\tqueue.mutex.Lock()\n\tdefer queue.mutex.Unlock()\n\tjob, found := queue.jobs[id]\n\tif !found {\n\t\treturn\n\t}\n\tjob.attempts = attempts + 1\n\tif job.attempts >= queue.maxAttempts {\n\t\tjob.status = jobDead\n\t} else {\n\t\tjob.status = jobPending\n\t}\n}\n\n// JobResult is what an api-test's `processNextJob` answers: the job that ran, and \226\128\148 when\n// the worker rejected or trapped \226\128\148 the error alongside it. `JobFailed` carries BOTH, as it\n// does on the Racket side (`JobFailed job error`), so a test can assert on the payload of a\n// job that failed.\n//\n// Runtime-provided like Maybe and Either, since a JobResult crosses module boundaries.\ntype JobResult[Payload any] struct {\n\tTag         JobResultTag\n\tOkJob       Payload\n\tFailedJob   Payload\n\tFailedError string\n}\n\ntype JobResultTag int\n\nconst (\n\tJobResultOk JobResultTag = iota\n\tJobResultFailed\n)\n\nfunc JobOk[Payload any](job Payload) JobResult[Payload] {\n\treturn JobResult[Payload]{Tag: JobResultOk, OkJob: job}\n}\n\nfunc JobFailed[Payload any](job Payload, failure string) JobResult[Payload] {\n\treturn JobResult[Payload]{Tag: JobResultFailed, FailedJob: job, FailedError: failure}\n}\n\n// ExpectJobOk is the api-test assertion: the job, or a trap naming the worker's failure.\nfunc ExpectJobOk[Payload any](result JobResult[Payload]) Payload {\n\tif result.Tag != JobResultOk {\n\t\tpanic(\"expectJobOk: expected JobOk but the worker failed with \" + result.FailedError)\n\t}\n\treturn result.OkJob\n}\n\n// ExpectJobFailed is its counterpart: the job that failed, or a trap.\nfunc ExpectJobFailed[Payload any](result JobResult[Payload]) Payload {\n\tif result.Tag != JobResultFailed {\n\t\tpanic(\"expectJobFailed: expected JobFailed but the worker succeeded\")\n\t}\n\treturn result.FailedJob\n}\n\n// EmptyQueue is the trap an api-test gets when it asks for a job and there is none \226\128\148 the\n// same failure Racket raises, with the same hint, because the usual cause is that the HTTP\n// action meant to enqueue the job did not run.\nfunc EmptyQueue(queueName, who string) string {\n\treturn fmt.Sprintf(\"%s: queue %s is empty \226\128\148 expected at least one pending job\\n\"+\n\t\t\"hint: did the HTTP action that enqueues the job run and return a success status?\",\n\t\twho, queueName)\n}\n\n// EnqueueJob is `enqueue`, whose Tesl type is Unit: the job id is not surfaced to the\n// program (Racket's enqueue! answers void too), so the id stays internal to the store.\nfunc EnqueueJob(queue *Queue, payload any) struct{} {\n\tEnqueue(queue, payload)\n\treturn struct{}{}\n}\n");
  ("random.go", "package teslrt\n\nimport (\n\t\"crypto/rand\"\n\t\"encoding/hex\"\n\t\"fmt\"\n\t\"math/big\"\n\t\"time\"\n)\n\n// Randomness is an effect Tesl gates behind the `random` capability, which the checker\n// enforces; nothing about that survives to run time.\n//\n// The source is crypto/rand rather than math/rand: a Tesl program cannot seed a generator\n// (there is no such surface), so a predictable stream would be a security property nobody\n// asked for, and gosec flags math/rand for exactly that reason.\n\n// RandomInt is `randomInt lo hi`: a uniform draw from [lo, hi). The caller proves lo < hi \226\128\148\n// the range is a compile-time obligation on the inputs \226\128\148 so an empty range is a trap rather\n// than a silent lo.\nfunc RandomInt(low, high Int) Int {\n\tspan := Sub(high, low)\n\tif Compare(span, FromInt64(1)) < 0 {\n\t\tpanic(\"randomInt: the range is empty (high must be greater than low)\")\n\t}\n\toffset, err := rand.Int(rand.Reader, span.bigInt())\n\tif err != nil {\n\t\tpanic(\"randomInt: no randomness available: \" + err.Error())\n\t}\n\treturn Add(low, fromBig(offset))\n}\n\n// RandomFloat is `randomFloat()`: a uniform draw from [0, 1), a fresh value per call.\n//\n// It is built from 53 random bits divided by 2^53 \226\128\148 the number of bits a float64 can hold\n// exactly \226\128\148 so every representable value in the range is reachable and none is favoured.\nfunc RandomFloat() float64 {\n\tconst bits = 1 << 53\n\tdrawn, err := rand.Int(rand.Reader, big.NewInt(bits))\n\tif err != nil {\n\t\tpanic(\"randomFloat: no randomness available: \" + err.Error())\n\t}\n\treturn float64(drawn.Int64()) / float64(bits)\n}\n\n// GeneratePrefixedId is `generatePrefixedId prefix`: `<prefix>-<32 hex chars>`, 16 CSPRNG\n// bytes rendered as hex, matching `tesl-generate-prefixed-id`. An id is often used as a\n// token, so it must be unguessable \226\128\148 the shape (prefix, dash, 32 hex digits) is part of the\n// contract, since ids land in URLs and databases.\nfunc GeneratePrefixedId(prefix string) string {\n\traw := make([]byte, 16)\n\tif _, err := rand.Read(raw); err != nil {\n\t\tpanic(\"generateId: no randomness available: \" + err.Error())\n\t}\n\treturn prefix + \"-\" + hex.EncodeToString(raw)\n}\n\n// GenerateId is `generateId()`: the same value with an empty prefix, so it still begins\n// with the dash \226\128\148 parity with Racket, which appends the separator unconditionally.\nfunc GenerateId() string {\n\treturn GeneratePrefixedId(\"\")\n}\n\n// UUIDv7 is a time-ordered UUID: 48 bits of Unix milliseconds, then random bits, with the\n// version and variant nibbles set (RFC 9562). The layout matches `uuid-v7-string` in\n// tesl/private/uuid-gen.rkt byte for byte, so an id generated on either backend sorts and\n// parses the same way.\n//\n// Time-ordered matters for the queue: a job id that is monotonic makes \"oldest first\"\n// recoverable from the id alone, and a v4 id would not.\nfunc UUIDv7() string {\n\tmilliseconds := time.Now().UnixMilli()\n\traw := make([]byte, 16)\n\tif _, err := rand.Read(raw[6:]); err != nil {\n\t\tpanic(\"UUID.v7: no randomness available: \" + err.Error())\n\t}\n\t// Masked, not just shifted: the truncation to a byte is the POINT (a 48-bit timestamp\n\t// spread over six bytes), and gosec's integer-overflow check is right to ask that it be\n\t// written explicitly rather than left to conversion.\n\tstamp := uint64(milliseconds)\n\traw[0] = byte((stamp >> 40) & 0xff)\n\traw[1] = byte((stamp >> 32) & 0xff)\n\traw[2] = byte((stamp >> 24) & 0xff)\n\traw[3] = byte((stamp >> 16) & 0xff)\n\traw[4] = byte((stamp >> 8) & 0xff)\n\traw[5] = byte(stamp & 0xff)\n\traw[6] = 0x70 | (raw[6] & 0x0f)\n\traw[8] = 0x80 | (raw[8] & 0x3f)\n\treturn fmt.Sprintf(\"%x-%x-%x-%x-%x\", raw[0:4], raw[4:6], raw[6:8], raw[8:10], raw[10:16])\n}\n\n// UUIDv4 is a RANDOM UUID: 122 random bits with the version and variant nibbles set\n// (RFC 9562), the same layout `uuid-v4-string` writes in tesl/private/uuid-gen.rkt.\n//\n// Randomness comes from crypto/rand, not math/rand, for the reason every id in this file\n// does: a UUID is routinely used as an unguessable handle, and a predictable one is a\n// vulnerability rather than a collision.\nfunc UUIDv4() string {\n\traw := make([]byte, 16)\n\tif _, err := rand.Read(raw); err != nil {\n\t\tpanic(\"UUID.v4: no randomness available: \" + err.Error())\n\t}\n\traw[6] = 0x40 | (raw[6] & 0x0f)\n\traw[8] = 0x80 | (raw[8] & 0x3f)\n\treturn fmt.Sprintf(\"%x-%x-%x-%x-%x\", raw[0:4], raw[4:6], raw[6:8], raw[8:10], raw[10:16])\n}\n\n// ValidUUID reports the 8-4-4-4-12 hex shape, in either case \226\128\148 the same set\n// `uuid-regexp` accepts in tesl/uuid.rkt. It is written as a scan rather than as a regular\n// expression so the runtime carries no regexp engine for one shape.\nfunc ValidUUID(value string) bool {\n\tif len(value) != 36 {\n\t\treturn false\n\t}\n\tfor index := 0; index < len(value); index++ {\n\t\tcharacter := value[index]\n\t\tswitch index {\n\t\tcase 8, 13, 18, 23:\n\t\t\tif character != '-' {\n\t\t\t\treturn false\n\t\t\t}\n\t\tdefault:\n\t\t\tisDigit := character >= '0' && character <= '9'\n\t\t\tisLower := character >= 'a' && character <= 'f'\n\t\t\tisUpper := character >= 'A' && character <= 'F'\n\t\t\tif !isDigit && !isLower && !isUpper {\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t}\n\treturn true\n}\n\n// UUIDValidate is `UUID.validate`: a CHECK, so an invalid string is a 400 the request\n// answers with rather than a trap. The proof it mints (`IsUuid`) erases, so what survives\n// is the string it verified.\nfunc UUIDValidate(value string) Check[string] {\n\tif !ValidUUID(value) {\n\t\treturn Reject[string](400, \"not a valid UUID\")\n\t}\n\treturn Accept(value)\n}\n");
  ("request.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"net/http\"\n\t\"strings\"\n)\n\n// RequestScope is the per-request state the Racket runtime keeps in a `parameterize`\n// scope: the cookies a handler has recorded on the response being built.\n//\n// Capabilities are deliberately NOT here. Every capability site in the AST carries a\n// STATIC list of names \226\128\148 `requires [...]`, `withCapabilities [...]`, `serve`, `workers` \226\128\148\n// so the granted set at any point is known at compile time and the checker already\n// verifies each call against it. A runtime check would compare two compile-time constants.\n// Keeping one would also force this scope through every capability-gated function, which\n// is exactly the blast radius the call-graph threading exists to avoid. Racket checks at\n// runtime because its capability set is a dynamic parameter; that mechanism is also what\n// broke capability delegation at deferred tool execution (\"passes test, fails live\"), a\n// failure mode a compile-time-only design does not have.\n//\n// This type exists because Go has no goroutine-local storage. A Racket parameter is\n// thread-local and every request is served on its own thread, so a handler deep in a call\n// chain can call `Http.clearSessionCookie` and the runtime knows which response it belongs\n// to. In Go the scope has to be passed explicitly \226\128\148 and the emitter passes it ONLY to the\n// functions whose call graph actually reaches a scope-using leaf, so ordinary pure\n// functions keep their plain signatures and the emitted code still reads like Go someone\n// would write.\n//\n// A nil scope means \"no live HTTP response\", which is exactly the Racket condition that\n// raises: startup code, `main`, and queue workers have no response to attach a cookie to.\ntype RequestScope struct {\n\t// Full `Set-Cookie` header values, in send order.\n\tcookies []string\n}\n\nfunc NewRequestScope() *RequestScope {\n\treturn &RequestScope{}\n}\n\n// SetCookieHeader records one complete `Set-Cookie` value. LAST CALL WINS PER COOKIE\n// NAME, and send order is otherwise preserved \226\128\148 the same rule dsl/response-cookies.rkt\n// states, so `setSessionCookie` followed by `clearSessionCookie` emits exactly one\n// `Set-Cookie` for that name rather than two contradictory ones.\nfunc (scope *RequestScope) SetCookieHeader(who, value string) {\n\tif scope == nil {\n\t\tpanic(who + \": no HTTP response to attach a cookie to.\\n\" +\n\t\t\t\"  it is only callable while serving an HTTP request \226\128\148 from a handler body, an\\n\" +\n\t\t\t\"  `auth` block, or an SSE subscribe.  Startup, `main` and queue-worker code have\\n\" +\n\t\t\t\"  no HTTP response.\")\n\t}\n\tname := value\n\tif index := strings.IndexByte(value, '='); index >= 0 {\n\t\tname = value[:index]\n\t}\n\tfor index, existing := range scope.cookies {\n\t\texistingName := existing\n\t\tif at := strings.IndexByte(existing, '='); at >= 0 {\n\t\t\texistingName = existing[:at]\n\t\t}\n\t\tif existingName == name {\n\t\t\tscope.cookies[index] = value\n\t\t\treturn\n\t\t}\n\t}\n\tscope.cookies = append(scope.cookies, value)\n}\n\n// CookieHeaders hands back a copy, so a caller cannot reach the scope's own storage.\n//\n// An EMPTY slice rather than nil for \"no scope\": callers range over or index the result, and\n// nilaway is right that a nil return travelling into a slice operation is a nil-panic waiting\n// for the one caller who forgets to check.\nfunc (scope *RequestScope) CookieHeaders() []string {\n\tif scope == nil {\n\t\treturn []string{}\n\t}\n\tout := make([]string, len(scope.cookies))\n\tcopy(out, scope.cookies)\n\treturn out\n}\n\n// The session cookie's shape is fixed by tesl/http.rkt and must match byte for byte:\n// the name is `__Host-`-prefixed (so the browser enforces Secure + host-only + Path=/),\n// and SameSite=Lax rather than Strict so following an ordinary link back into the app\n// arrives authenticated.\nconst (\n\tsessionCookieName       = \"__Host-session\"\n\tsessionCookieAttributes = \"Path=/; HttpOnly; Secure; SameSite=Lax\"\n)\n\n// ClearSessionCookie is the logout half: same cookie, same attributes, empty value and\n// `Max-Age=0`, which is how a browser is told to drop it. It removes the BROWSER's copy\n// and does not invalidate the token \226\128\148 the same documented limitation Racket carries.\n// Returns Tesl's Unit (an empty struct), so the emitted code can use it in value\n// position the way a Tesl expression of type Unit is used.\nfunc ClearSessionCookie(scope *RequestScope) struct{} {\n\tscope.SetCookieHeader(\"Http.clearSessionCookie\",\n\t\tfmt.Sprintf(\"%s=; %s; Max-Age=0\", sessionCookieName, sessionCookieAttributes))\n\treturn struct{}{}\n}\n\n// HttpRequest is what an `auth` function and a handler see of the incoming request.\n// It is a plain value built once per request by the dispatcher \226\128\148 the fields Tesl exposes,\n// nothing more, so an ejecting author is not handed the whole net/http surface.\n//\n// The maps are teslrt.Dict values because that is what Tesl's `Dict.lookup` expects.\n// A Dict is stored sorted by key, and these are built with plain string ordering, which is\n// exactly the comparator the emitter passes at a `Dict.lookup` call site on String keys.\ntype HttpRequest struct {\n\tMethod          string\n\tPath            string\n\tCookies         Dict[string, string]\n\tHeaders         Dict[string, string]\n\tQueryParameters Dict[string, string]\n\tBody            string\n}\n\n// NewHttpRequest snapshots the request. Header names are lower-cased so a lookup does not\n// depend on the casing a client happened to send; cookie names are left exactly as sent.\n//\n// A REPEATED name \226\128\148 `?q=first&q=second`, or two `X-Forwarded-For` headers \226\128\148 collapses to the\n// LAST value, because a Dict holds one value per key and that is the answer the Racket runtime\n// gives: both its header and query hashes are built with `for/hash`, which keeps the last\n// binding. Taking the first instead is the natural Go spelling (`Query().Get`) and the wrong\n// one; `tests/query-parameters-tests.tesl` pins the rule.\nfunc NewHttpRequest(request *http.Request, body string) HttpRequest {\n\theaders := DictEmpty[string, string]()\n\tfor name, values := range request.Header {\n\t\tif len(values) > 0 {\n\t\t\theaders = DictInsert(headers, strings.ToLower(name), values[len(values)-1], stringKeyLess)\n\t\t}\n\t}\n\tcookies := DictEmpty[string, string]()\n\tfor _, cookie := range request.Cookies() {\n\t\tcookies = DictInsert(cookies, cookie.Name, cookie.Value, stringKeyLess)\n\t}\n\tquery := DictEmpty[string, string]()\n\tfor name, values := range request.URL.Query() {\n\t\tif len(values) > 0 {\n\t\t\tquery = DictInsert(query, name, values[len(values)-1], stringKeyLess)\n\t\t}\n\t}\n\treturn HttpRequest{\n\t\tMethod:          request.Method,\n\t\tPath:            request.URL.Path,\n\t\tCookies:         cookies,\n\t\tHeaders:         headers,\n\t\tQueryParameters: query,\n\t\tBody:            body,\n\t}\n}\n\n// SetSessionCookie is `Http.setSessionCookie`: the ONE blessed session transport. The name is\n// `__Host-`-prefixed so the browser enforces Secure, host-only and Path=/, and the lifetime\n// matches the token's own TTL \226\128\148 a cookie that outlived its token would only produce 401s.\n//\n// There is no name parameter and no attribute parameter: every option here is a way to get it\n// wrong, and the fixed shape is what makes `Http.sessionToken` able to read it back.\nfunc SetSessionCookie(scope *RequestScope, token JwtToken) struct{} {\n\t// The value must LOOK like a signed token \226\128\148 three non-empty base64url segments. A session\n\t// cookie carrying anything else is a misuse (writing an unverified cookie value straight\n\t// back, say), and writing it would mint a session out of attacker-supplied text. Racket\n\t// applies the same shape check for the same reason, and the trap is contained by the\n\t// router's sanitized 500 rather than reaching the client.\n\tif !looksLikeJWT(token.Value) {\n\t\tpanic(fmt.Sprintf(\"Http.setSessionCookie: expected a JwtToken produced by `JWT.sign`, \"+\n\t\t\t\"got %q.\\n  A session cookie must carry a signed token; this value is not a\\n\"+\n\t\t\t\"  well-formed JWT and will not be written to the response.\", token.Value))\n\t}\n\tscope.SetCookieHeader(\"Http.setSessionCookie\",\n\t\tfmt.Sprintf(\"%s=%s; %s; Max-Age=%d\",\n\t\t\tsessionCookieName, token.Value, sessionCookieAttributes, jwtTTLSeconds))\n\treturn struct{}{}\n}\n\n// looksLikeJWT is the wire SHAPE only \226\128\148 `header.payload.signature`, base64url \226\128\148 never a\n// verification. Deciding whether a token is authentic is `JWT.verify`'s job, and conflating the\n// two here would be the more dangerous kind of check: one that looks like a guarantee.\nfunc looksLikeJWT(value string) bool {\n\tsegments := strings.Split(value, \".\")\n\tif len(segments) != 3 {\n\t\treturn false\n\t}\n\tfor _, segment := range segments {\n\t\tif segment == \"\" {\n\t\t\treturn false\n\t\t}\n\t\tfor _, character := range segment {\n\t\t\tisBase64URL := (character >= 'A' && character <= 'Z') ||\n\t\t\t\t(character >= 'a' && character <= 'z') ||\n\t\t\t\t(character >= '0' && character <= '9') ||\n\t\t\t\tcharacter == '_' || character == '-'\n\t\t\tif !isBase64URL {\n\t\t\t\treturn false\n\t\t\t}\n\t\t}\n\t}\n\treturn true\n}\n\n// SessionToken is `Http.sessionToken`: the reader, so the fixed cookie name is written down\n// once rather than spelled out at every call site \226\128\148 where a typo is a permanent 401. It is pure\n// and ungated; `JWT.verify` is what sits between this and a fact.\nfunc SessionToken(request HttpRequest) Maybe[JwtToken] {\n\tvalue, found := DictLookup(request.Cookies, sessionCookieName, stringKeyLess).Value()\n\tif !found {\n\t\treturn Nothing[JwtToken]()\n\t}\n\treturn Something(JwtToken{Value: value})\n}\n\n// ResponseCookie is the api-test reader: the session cookie a response set, as a\n// Cookie-header-ready `name=value` pair, so a round-trip test can feed it straight back. The\n// ATTRIBUTES are stripped deliberately \226\128\148 assert those against the raw `set-cookie` header,\n// which is the full line.\nfunc ResponseCookie(response ApiResponse) Maybe[string] {\n\tline, found := DictLookup(response.Headers, \"set-cookie\", stringKeyLess).Value()\n\tif !found {\n\t\treturn Nothing[string]()\n\t}\n\t// The pair is everything up to the first `;`. Indexed only after a length check: a split\n\t// result is a slice whose emptiness nothing here guarantees to a reader (or to nilaway).\n\tsegments := strings.Split(line, \";\")\n\tif len(segments) == 0 {\n\t\treturn Nothing[string]()\n\t}\n\tpair := strings.TrimSpace(segments[0])\n\tif !strings.Contains(pair, \"=\") {\n\t\treturn Nothing[string]()\n\t}\n\treturn Something(pair)\n}\n");
  ("result.go", "package teslrt\n\n// Result is Tesl's `Result ok err`: Ok carries the value, Err the failure. Like Maybe and\n// Either it lives in the runtime because a Result crosses module boundaries, and it uses\n// the same flat tag+payload shape the emitter generates for a user ADT.\n//\n// The zero value is an Ok holding the zero value of Ok \226\128\148 the tag order below \226\128\148 which is the\n// one asymmetry worth stating: a zero Result reads as success. Emitted code never produces\n// one (every construction names a constructor), and Tesl has no way to observe an\n// uninitialised value, so this is a Go-level note rather than a semantic choice.\ntype Result[Ok any, Err any] struct {\n\tTag      ResultTag\n\tOkValue  Ok\n\tErrValue Err\n}\n\n// ResultTag identifies which side a Result holds. The constants are an enum-like set so the\n// `exhaustive` linter can verify a switch over them.\ntype ResultTag int\n\nconst (\n\tResultOk ResultTag = iota\n\tResultErr\n)\n\n// MakeOk and MakeErr exist for hand-written runtime code and readable tests; emitted code\n// writes the composite literal directly. They are not named `Ok`/`Err` because those are\n// the FIELD-bearing type parameters above, and a function may not share a name with them.\nfunc MakeOk[Ok any, Err any](value Ok) Result[Ok, Err] {\n\treturn Result[Ok, Err]{Tag: ResultOk, OkValue: value}\n}\n\nfunc MakeErr[Ok any, Err any](failure Err) Result[Ok, Err] {\n\treturn Result[Ok, Err]{Tag: ResultErr, ErrValue: failure}\n}\n\n// IsOk reports which side is held.\nfunc (r Result[Ok, Err]) IsOk() bool {\n\treturn r.Tag == ResultOk\n}\n");
  ("secret.go", "package teslrt\n\nimport \"crypto/subtle\"\n\n// SecretRedaction is the one string every sink substitutes for a secret's payload.\n//\n// Fixed, and deliberately carrying no length, prefix or hash of the value: partial\n// disclosure in a log or a debugger is the convenience that erodes the guarantee. Same text\n// as `secret-redaction-text` in dsl/types.rkt, so the two backends redact identically.\nconst SecretRedaction = \"[redacted]\"\n\n// SecretString is the payload of a `secret` newtype over String.\n//\n// It is a distinct type rather than a bare string so that a `%v`/`%s` of it \226\128\148 a log line, a\n// panic message, a test failure \226\128\148 prints the redaction instead of the plaintext. The\n// plaintext is reached through `Reveal`, which is spelled to be searchable: a review can ask\n// where it is called.\ntype SecretString struct {\n\tplaintext string\n}\n\nfunc MakeSecret(plaintext string) SecretString {\n\treturn SecretString{plaintext: plaintext}\n}\n\n// String makes redaction the DEFAULT: fmt reaches for this method, so every accidental\n// print is safe without the call sites having to know they are handling a secret.\nfunc (secret SecretString) String() string { return SecretRedaction }\n\n// GoString covers `%#v`, which would otherwise print the struct with its field.\nfunc (secret SecretString) GoString() string { return SecretRedaction }\n\n// MarshalJSON keeps a secret out of an encoded payload the same way, rather than relying on\n// every codec to remember.\nfunc (secret SecretString) MarshalJSON() ([]byte, error) {\n\treturn []byte(`\"` + SecretRedaction + `\"`), nil\n}\n\n// Reveal hands back the plaintext. Every use is a deliberate disclosure \226\128\148 sending it on the\n// wire, hashing it, comparing it \226\128\148 and is meant to be greppable.\nfunc (secret SecretString) Reveal() string { return secret.plaintext }\n\n// SecretEqual compares two secrets without an early-exit data dependency, so a caller\n// cannot learn a prefix from how long the comparison took. `subtle.ConstantTimeCompare`\n// itself returns 0 for differing LENGTHS without comparing, which is the same shape Racket's\n// `constant-time-bytes=?/secret` has.\nfunc SecretEqual(left, right SecretString) bool {\n\treturn subtle.ConstantTimeCompare([]byte(left.plaintext), []byte(right.plaintext)) == 1\n}\n");
  ("serve.go", "package teslrt\n\nimport (\n\t\"context\"\n\t\"errors\"\n\t\"fmt\"\n\t\"net/http\"\n\t\"os\"\n\t\"os/signal\"\n\t\"path\"\n\t\"path/filepath\"\n\t\"strings\"\n\t\"sync\"\n\t\"syscall\"\n\t\"time\"\n)\n\n// Activation: what `main` returning an `App { \226\128\166 }` becomes.\n//\n// The App record is not a runtime value \226\128\148 the compiler lowers it into the startup chain it\n// describes (start each queue's workers, then serve), so what is left here are the two things\n// that chain calls. Everything the App configures is therefore decided at compile time and read\n// here as ordinary arguments.\n\n// ServeOptions is what an `App` says about the HTTP surface. Grouped in a struct rather than\n// passed positionally because most programs set only `Port`, and a five-argument call whose\n// middle three are usually zero reads worse in the emitted code than a literal with named\n// fields.\ntype ServeOptions struct {\n\tPort int\n\t// StaticDir serves files, with an index.html SPA fallback, when set.\n\tStaticDir string\n\t// MountPath scopes exactly the DECLARED api surface (`/api`), while static files, the SPA\n\t// fallback and the health probe keep answering on the raw path \226\128\148 the same split the Racket\n\t// runtime makes, and for its reason: the SPA is precisely the other thing sharing this\n\t// origin that the prefix exists to separate the API from.\n\tMountPath string\n}\n\n// Serve runs the HTTP server until the process is asked to stop, then drains in-flight requests.\n//\n// Timeouts are set rather than left at Go's defaults (which are \"none\"): a server with no read\n// timeout can be held open by a slow client indefinitely, which is the same class of problem the\n// outbound deadlines close on the client side. `ReadHeaderTimeout` in particular is what stops a\n// Slowloris-style hold.\n// Answers Tesl's Unit (an empty struct) rather than nothing, so the emitted `main` can return it\n// the way it returns any other statement's value \226\128\148 the same shape `EnqueueJob` and the cookie\n// writers use.\nfunc Serve(server Server, options ServeOptions) struct{} {\n\tport := options.Port\n\tif port == 0 {\n\t\tport = 8080\n\t}\n\thandler := server.handlerWith(options)\n\taddress := fmt.Sprintf(\":%d\", port)\n\thttpServer := &http.Server{\n\t\tAddr:              address,\n\t\tHandler:           handler,\n\t\tReadHeaderTimeout: 10 * time.Second,\n\t\tReadTimeout:       30 * time.Second,\n\t\tWriteTimeout:      60 * time.Second,\n\t\tIdleTimeout:       120 * time.Second,\n\t}\n\t// Graceful: an interrupt stops accepting and lets in-flight requests finish, so a deploy does\n\t// not answer a request with a truncated response.\n\tshutdown, stop := signal.NotifyContext(context.Background(),\n\t\tos.Interrupt, syscall.SIGTERM)\n\tdefer stop()\n\tgo func() {\n\t\t<-shutdown.Done()\n\t\tdrain, cancel := context.WithTimeout(context.Background(), 15*time.Second)\n\t\tdefer cancel()\n\t\t_ = httpServer.Shutdown(drain)\n\t}()\n\tfmt.Fprintf(os.Stderr, \"tesl: serving on http://localhost:%d\\n\", port)\n\tif err := httpServer.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {\n\t\tpanic(\"serve: \" + err.Error())\n\t}\n\treturn struct{}{}\n}\n\n// handlerWith wraps the router with the static-file surface an App may declare. The API routes\n// are reached under `MountPath`; everything else the runtime owns answers on the raw path.\nfunc (server Server) handlerWith(options ServeOptions) http.Handler {\n\tmount := strings.Trim(options.MountPath, \"/\")\n\tstatic := options.StaticDir\n\treturn http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {\n\t\trouted := request\n\t\tif mount != \"\" {\n\t\t\ttrimmed := strings.TrimPrefix(strings.TrimPrefix(request.URL.Path, \"/\"), mount)\n\t\t\tif !strings.HasPrefix(strings.TrimPrefix(request.URL.Path, \"/\"), mount) {\n\t\t\t\t// Not under the mount prefix: only the static surface can answer it.\n\t\t\t\tif static != \"\" && serveStatic(writer, request, static) {\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\twriteResponse(writer, nil, Fail(404, \"not found\"))\n\t\t\t\treturn\n\t\t\t}\n\t\t\trouted = request.Clone(request.Context())\n\t\t\tif trimmed == \"\" {\n\t\t\t\ttrimmed = \"/\"\n\t\t\t}\n\t\t\tif !strings.HasPrefix(trimmed, \"/\") {\n\t\t\t\ttrimmed = \"/\" + trimmed\n\t\t\t}\n\t\t\trouted.URL.Path = trimmed\n\t\t}\n\t\tif server.routeExists(routed) {\n\t\t\tserver.ServeHTTP(writer, routed)\n\t\t\treturn\n\t\t}\n\t\tif static != \"\" && serveStatic(writer, request, static) {\n\t\t\treturn\n\t\t}\n\t\tserver.ServeHTTP(writer, routed)\n\t})\n}\n\n// routeExists reports whether the router has a route for this path at all \226\128\148 used to decide\n// between the API surface and the static one WITHOUT letting the router answer 404 first.\nfunc (server Server) routeExists(request *http.Request) bool {\n\tfor _, route := range server.Routes {\n\t\tif pathMatches(route.Path, request.URL.Path) {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// serveStatic answers a GET from the static directory, falling back to index.html so a\n// single-page app's client-side routes load. Reports whether it answered.\n//\n// The path is resolved and then CHECKED to be inside the directory: `..` segments and absolute\n// paths are how a static handler becomes an arbitrary-file read, and the check is on the\n// resolved path rather than on the request text so an encoded traversal cannot slip past.\nfunc serveStatic(writer http.ResponseWriter, request *http.Request, directory string) bool {\n\tif request.Method != http.MethodGet && request.Method != http.MethodHead {\n\t\treturn false\n\t}\n\troot, err := filepath.Abs(directory)\n\tif err != nil {\n\t\treturn false\n\t}\n\trelative := strings.TrimPrefix(path.Clean(\"/\"+request.URL.Path), \"/\")\n\tif relative == \"\" {\n\t\trelative = \"index.html\"\n\t}\n\tcandidate := filepath.Join(root, filepath.FromSlash(relative))\n\tif !strings.HasPrefix(candidate, root+string(os.PathSeparator)) && candidate != root {\n\t\treturn false\n\t}\n\tif info, err := os.Stat(candidate); err == nil && !info.IsDir() {\n\t\thttp.ServeFile(writer, request, candidate)\n\t\treturn true\n\t}\n\t// The SPA fallback: an unknown path serves index.html, so client-side routing works on a\n\t// cold load. Only when there IS an index.html \226\128\148 otherwise the router's own 404 is the honest\n\t// answer.\n\tindex := filepath.Join(root, \"index.html\")\n\tif info, err := os.Stat(index); err == nil && !info.IsDir() {\n\t\thttp.ServeFile(writer, request, index)\n\t\treturn true\n\t}\n\treturn false\n}\n\n// \226\148\128\226\148\128 Queue workers \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n\n// StartWorkers activates a queue's workers: `concurrency` goroutines, each claiming and running\n// one job at a time. `dead` selects the dead-letter worker instead of the ordinary one.\n//\n// A worker that finds nothing sleeps briefly rather than spinning: the in-memory store has no\n// condition variable to wait on, and a busy loop would burn a core per queue. The Racket runtime\n// waits on a semaphore instead \226\128\148 same behaviour, one poll interval of latency on an idle queue.\nfunc StartWorkers(queue *Queue, handler func(any) JobOutcome, concurrency int, dead bool) struct{} {\n\tif concurrency < 1 {\n\t\tconcurrency = 1\n\t}\n\tfor range concurrency {\n\t\tgo func() {\n\t\t\tfor {\n\t\t\t\toutcome := JobOutcome{}\n\t\t\t\tif dead {\n\t\t\t\t\toutcome = ProcessNextDeadJob(queue, handler)\n\t\t\t\t} else {\n\t\t\t\t\toutcome = ProcessNextJob(queue, handler)\n\t\t\t\t}\n\t\t\t\tif !outcome.Ran {\n\t\t\t\t\ttime.Sleep(50 * time.Millisecond)\n\t\t\t\t}\n\t\t\t}\n\t\t}()\n\t}\n\treturn struct{}{}\n}\n\n// \226\148\128\226\148\128 Request-level guards \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// Two refusals the Racket runtime applies to every request, mirrored here so a program does not\n// lose them by changing backend. Both are cheap and neither is configurable per route.\n\nvar publicOriginOnce sync.Once\nvar publicOrigin string\n\n// PublicOrigin is `TESL_PUBLIC_ORIGIN` when set: the origin this deployment answers as.\nfunc PublicOrigin() string {\n\tpublicOriginOnce.Do(func() {\n\t\tpublicOrigin = strings.TrimSpace(os.Getenv(\"TESL_PUBLIC_ORIGIN\"))\n\t})\n\treturn publicOrigin\n}\n\n// requestRefusal is the guard pair: a cross-site state-changing request is refused (403), and a\n// Host that does not match the configured public origin is refused (421). Answering the second\n// with 421 rather than 404 is deliberate \226\128\148 it says \"not this origin\", which is what a\n// misconfigured proxy needs to hear.\nfunc requestRefusal(request *http.Request) (Response, bool) {\n\tswitch request.Method {\n\tcase http.MethodPost, http.MethodPut, http.MethodDelete, http.MethodPatch:\n\t\tif strings.EqualFold(strings.TrimSpace(request.Header.Get(\"Sec-Fetch-Site\")), \"cross-site\") {\n\t\t\treturn Fail(403, \"cross-site request refused\"), true\n\t\t}\n\t}\n\torigin := PublicOrigin()\n\tif origin == \"\" {\n\t\treturn Response{}, false\n\t}\n\tif hostOf(request.Host) == hostOf(origin) {\n\t\treturn Response{}, false\n\t}\n\treturn Fail(421, \"Host does not match the configured public origin\"), true\n}\n\n// hostOf takes the host out of either a bare Host header or a full origin, without its port: a\n// deployment behind a proxy sees the port the proxy forwards to, not the public one.\nfunc hostOf(value string) string {\n\ttext := strings.TrimSpace(strings.ToLower(value))\n\tif index := strings.Index(text, \"://\"); index >= 0 {\n\t\ttext = text[index+3:]\n\t}\n\tif index := strings.IndexAny(text, \"/?#\"); index >= 0 {\n\t\ttext = text[:index]\n\t}\n\tif strings.HasPrefix(text, \"[\") {\n\t\tif end := strings.Index(text, \"]\"); end >= 0 {\n\t\t\treturn text[:end+1]\n\t\t}\n\t\treturn text\n\t}\n\tif index := strings.LastIndex(text, \":\"); index >= 0 {\n\t\treturn text[:index]\n\t}\n\treturn text\n}\n\n// PortOf narrows a Tesl `Int` to a listening port. A port is a 16-bit number, so anything\n// outside that range is a configuration error worth failing at startup rather than silently\n// binding somewhere else.\nfunc PortOf(value Int) int {\n\tport, exact := value.Int64()\n\tif !exact || port < 1 || port > 65535 {\n\t\tpanic(\"serve: port \" + value.String() + \" is not a valid TCP port (1-65535)\")\n\t}\n\treturn int(port)\n}\n");
  ("server.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"net/http\"\n\t\"os\"\n\t\"runtime/debug\"\n\t\"strings\"\n)\n\n// The HTTP surface an emitted module exposes: the ROUTES an `api` declares, and the\n// SERVER that binds each route's endpoint name to a handler.\n//\n// Emitted modules build these as ordinary values, so a Go author who sheds Tesl can read\n// the routing table, call a handler directly, or mount the server on any net/http mux.\n// Nothing here reaches into request-scoped globals: the per-request state a handler may\n// touch (cookies) is created by the dispatcher and passed in explicitly.\n\ntype Route struct {\n\tMethod   string\n\tPath     string\n\tEndpoint string\n}\n\n// HandlerFunc is one endpoint's implementation. The scope carries the response state the\n// handler is allowed to write (see request.go); `Response` says what to send.\ntype HandlerFunc func(scope *RequestScope, request *http.Request) Response\n\ntype Response struct {\n\tStatus int\n\t// Body is an already-encoded JSON value (map / slice / scalar), rendered by\n\t// EncodeJSONValue so object keys keep the sorted order Racket produces.\n\tBody any\n}\n\n// Fail builds the error body shape the Racket server sends:\n// {\"ok\":false,\"error\":<message>,\"details\":[]}.\nfunc Fail(status int, message string) Response {\n\treturn Response{\n\t\tStatus: status,\n\t\tBody: map[string]any{\n\t\t\t\"ok\":      false,\n\t\t\t\"error\":   message,\n\t\t\t\"details\": []any{},\n\t\t},\n\t}\n}\n\ntype Server struct {\n\tRoutes   []Route\n\tHandlers map[string]HandlerFunc\n}\n\n// ServeHTTP dispatches by method and path. A path segment written `:name` in the route\n// matches any single segment.\n//\n// The status choices mirror the Racket router: an unknown path is 404, and a known path\n// with the wrong method is 405 \226\128\148 reporting 404 for a method mismatch would tell a client\n// the resource does not exist when it does.\n// callHandler runs one handler and converts a check rejection that escaped its body into\n// the response that rejection describes. Any OTHER panic is left alone: a genuine bug must\n// not be reported to the client as a validation failure.\nfunc callHandler(handler HandlerFunc, scope *RequestScope, request *http.Request) (response Response) {\n\tdefer func() {\n\t\trecovered := recover()\n\t\tif recovered == nil {\n\t\t\treturn\n\t\t}\n\t\tif rejection, isRejection := recovered.(RequestRejection); isRejection {\n\t\t\tresponse = Fail(rejection.Status, rejection.Message)\n\t\t\treturn\n\t\t}\n\t\t// ANY other trap becomes a SANITIZED 500. The message is deliberately generic and the\n\t\t// trap text never reaches the client: a trap message carries whatever the program was\n\t\t// holding (a path, a key, a row), and an `auth` block is exactly where a malformed\n\t\t// cookie can provoke one \226\128\148 so a client-triggerable trap must not become a\n\t\t// client-readable disclosure. The detail is still available to the operator, on stderr.\n\t\tfmt.Fprintf(os.Stderr, \"tesl: handler trapped: %v\\n%s\", recovered, debug.Stack())\n\t\tresponse = Fail(500, \"Internal server error\")\n\t}()\n\treturn handler(scope, request)\n}\n\nfunc (server Server) ServeHTTP(writer http.ResponseWriter, request *http.Request) {\n\t// The two request-level refusals the Racket runtime applies to every request (serve.go):\n\t// a cross-site state-changing request, and a Host that is not this deployment's. Checked\n\t// here rather than in `Serve` so an api-test \226\128\148 which drives this method directly \226\128\148 exercises\n\t// them too.\n\tif refusal, refused := requestRefusal(request); refused {\n\t\twriteResponse(writer, nil, refusal)\n\t\treturn\n\t}\n\tpathMatched := false\n\tfor _, route := range server.Routes {\n\t\tif !pathMatches(route.Path, request.URL.Path) {\n\t\t\tcontinue\n\t\t}\n\t\tpathMatched = true\n\t\tif route.Method != request.Method {\n\t\t\tcontinue\n\t\t}\n\t\thandler, found := server.Handlers[route.Endpoint]\n\t\tif !found {\n\t\t\twriteResponse(writer, nil, Fail(500, \"endpoint \"+route.Endpoint+\" has no handler\"))\n\t\t\treturn\n\t\t}\n\t\tscope := NewRequestScope()\n\t\twriteResponse(writer, scope, callHandler(handler, scope, request))\n\t\treturn\n\t}\n\tif pathMatched {\n\t\twriteResponse(writer, nil, Fail(405, \"method not allowed\"))\n\t\treturn\n\t}\n\twriteResponse(writer, nil, Fail(404, \"not found\"))\n}\n\nfunc pathMatches(pattern, path string) bool {\n\tpatternParts := strings.Split(strings.Trim(pattern, \"/\"), \"/\")\n\tpathParts := strings.Split(strings.Trim(path, \"/\"), \"/\")\n\tif len(patternParts) != len(pathParts) {\n\t\treturn false\n\t}\n\tfor index, part := range patternParts {\n\t\tif strings.HasPrefix(part, \":\") {\n\t\t\tif pathParts[index] == \"\" {\n\t\t\t\treturn false\n\t\t\t}\n\t\t\tcontinue\n\t\t}\n\t\tif part != pathParts[index] {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n\n// PathParam reads the segment a `:name` placeholder matched.\nfunc PathParam(pattern, path, name string) (string, bool) {\n\tpatternParts := strings.Split(strings.Trim(pattern, \"/\"), \"/\")\n\tpathParts := strings.Split(strings.Trim(path, \"/\"), \"/\")\n\tif len(patternParts) != len(pathParts) {\n\t\treturn \"\", false\n\t}\n\tfor index, part := range patternParts {\n\t\tif part == \":\"+name {\n\t\t\treturn pathParts[index], true\n\t\t}\n\t}\n\treturn \"\", false\n}\n\nfunc writeResponse(writer http.ResponseWriter, scope *RequestScope, response Response) {\n\t// Cookies attach to 2xx responses only, matching dsl/web.rkt: a handler that sets a\n\t// cookie and then fails mints no session.\n\tif scope != nil && response.Status >= 200 && response.Status < 300 {\n\t\tfor _, cookie := range scope.CookieHeaders() {\n\t\t\twriter.Header().Add(\"Set-Cookie\", cookie)\n\t\t}\n\t}\n\twriter.Header().Set(\"Content-Type\", \"application/json\")\n\twriter.WriteHeader(response.Status)\n\t_, _ = writer.Write([]byte(EncodeJSONValue(response.Body)))\n}\n");
  ("set.go", "package teslrt\n\n// Set is Tesl's `Set a`, held as elements kept SORTED with no duplicates.\n//\n// Same reasoning as Dict (see dict.go): a Go map cannot be keyed by the non-comparable\n// teslrt.Int, and Go randomises map iteration order per run \226\128\148 which would make the same\n// binary print different output across runs, worse than Racket's unspecified-but-stable\n// order. Sorted order is deterministic and free here, since the insertion point is the\n// binary search membership already performs.\n//\n// Racket's `Set.toList` iterates a hash, so element order is UNSPECIFIED in Tesl: a\n// program may observe membership and size, never order. That divergence is real and\n// demonstrated \226\128\148 see the Dict entry in the migration tracker.\n//\n// Ordering comes in from the emitter, which knows the concrete element type at every\n// call site.\ntype Set[A any] struct {\n\tElements []A\n}\n\nfunc SetEmpty[A any]() Set[A] {\n\treturn Set[A]{}\n}\n\nfunc SetSingleton[A any](value A) Set[A] {\n\treturn Set[A]{Elements: []A{value}}\n}\n\nfunc SetSize[A any](s Set[A]) Int {\n\treturn FromInt64(int64(len(s.Elements)))\n}\n\nfunc SetIsEmpty[A any](s Set[A]) bool {\n\treturn len(s.Elements) == 0\n}\n\n// setSearch returns the insertion index and whether the element was present.\nfunc setSearch[A any](s Set[A], value A, less func(A, A) bool) (int, bool) {\n\tlow, high := 0, len(s.Elements)\n\tfor low < high {\n\t\tmiddle := int(uint(low+high) >> 1)\n\t\tswitch {\n\t\tcase less(s.Elements[middle], value):\n\t\t\tlow = middle + 1\n\t\tcase less(value, s.Elements[middle]):\n\t\t\thigh = middle\n\t\tdefault:\n\t\t\treturn middle, true\n\t\t}\n\t}\n\treturn low, false\n}\n\nfunc SetMember[A any](value A, s Set[A], less func(A, A) bool) bool {\n\t_, found := setSearch(s, value, less)\n\treturn found\n}\n\n// SetInsert is a WRITER, so it allocates rather than reusing the caller's spare\n// capacity \226\128\148 the same rule list.go states.\nfunc SetInsert[A any](value A, s Set[A], less func(A, A) bool) Set[A] {\n\tindex, found := setSearch(s, value, less)\n\tif found {\n\t\treturn s\n\t}\n\telements := make([]A, 0, len(s.Elements)+1)\n\telements = append(elements, s.Elements[:index]...)\n\telements = append(elements, value)\n\telements = append(elements, s.Elements[index:]...)\n\treturn Set[A]{Elements: elements}\n}\n\nfunc SetRemove[A any](value A, s Set[A], less func(A, A) bool) Set[A] {\n\tindex, found := setSearch(s, value, less)\n\tif !found {\n\t\treturn s\n\t}\n\telements := make([]A, 0, len(s.Elements)-1)\n\telements = append(elements, s.Elements[:index]...)\n\telements = append(elements, s.Elements[index+1:]...)\n\treturn Set[A]{Elements: elements}\n}\n\n// SetToList hands back a copy in element order, so a caller cannot reach the set's own\n// storage through the list.\nfunc SetToList[A any](s Set[A]) []A {\n\tout := make([]A, len(s.Elements))\n\tcopy(out, s.Elements)\n\treturn out\n}\n\n// SetFromList sorts once and drops duplicates rather than inserting n times, which\n// would be O(n\194\178).\nfunc SetFromList[A any](values []A, less func(A, A) bool) Set[A] {\n\tout := SetEmpty[A]()\n\tif len(values) == 0 {\n\t\treturn out\n\t}\n\tsorted := ListSortBy(values, less)\n\telements := make([]A, 0, len(sorted))\n\tfor index, value := range sorted {\n\t\tif index == 0 || less(elements[len(elements)-1], value) {\n\t\t\telements = append(elements, value)\n\t\t}\n\t}\n\treturn Set[A]{Elements: elements}\n}\n\n// SetUnion, SetIntersection, and SetDifference each merge two ordered runs in one pass,\n// so they are O(n+m) rather than n lookups.\nfunc SetUnion[A any](left, right Set[A], less func(A, A) bool) Set[A] {\n\telements := make([]A, 0, len(left.Elements)+len(right.Elements))\n\tleftIndex, rightIndex := 0, 0\n\tfor leftIndex < len(left.Elements) && rightIndex < len(right.Elements) {\n\t\tswitch {\n\t\tcase less(left.Elements[leftIndex], right.Elements[rightIndex]):\n\t\t\telements = append(elements, left.Elements[leftIndex])\n\t\t\tleftIndex++\n\t\tcase less(right.Elements[rightIndex], left.Elements[leftIndex]):\n\t\t\telements = append(elements, right.Elements[rightIndex])\n\t\t\trightIndex++\n\t\tdefault:\n\t\t\telements = append(elements, left.Elements[leftIndex])\n\t\t\tleftIndex++\n\t\t\trightIndex++\n\t\t}\n\t}\n\telements = append(elements, left.Elements[leftIndex:]...)\n\telements = append(elements, right.Elements[rightIndex:]...)\n\treturn Set[A]{Elements: elements}\n}\n\nfunc SetIntersection[A any](left, right Set[A], less func(A, A) bool) Set[A] {\n\telements := make([]A, 0, min(len(left.Elements), len(right.Elements)))\n\tleftIndex, rightIndex := 0, 0\n\tfor leftIndex < len(left.Elements) && rightIndex < len(right.Elements) {\n\t\tswitch {\n\t\tcase less(left.Elements[leftIndex], right.Elements[rightIndex]):\n\t\t\tleftIndex++\n\t\tcase less(right.Elements[rightIndex], left.Elements[leftIndex]):\n\t\t\trightIndex++\n\t\tdefault:\n\t\t\telements = append(elements, left.Elements[leftIndex])\n\t\t\tleftIndex++\n\t\t\trightIndex++\n\t\t}\n\t}\n\treturn Set[A]{Elements: elements}\n}\n\nfunc SetDifference[A any](left, right Set[A], less func(A, A) bool) Set[A] {\n\telements := make([]A, 0, len(left.Elements))\n\tleftIndex, rightIndex := 0, 0\n\tfor leftIndex < len(left.Elements) && rightIndex < len(right.Elements) {\n\t\tswitch {\n\t\tcase less(left.Elements[leftIndex], right.Elements[rightIndex]):\n\t\t\telements = append(elements, left.Elements[leftIndex])\n\t\t\tleftIndex++\n\t\tcase less(right.Elements[rightIndex], left.Elements[leftIndex]):\n\t\t\trightIndex++\n\t\tdefault:\n\t\t\tleftIndex++\n\t\t\trightIndex++\n\t\t}\n\t}\n\telements = append(elements, left.Elements[leftIndex:]...)\n\treturn Set[A]{Elements: elements}\n}\n\n// SetIsSubset reports whether every element of left is also in right.\nfunc SetIsSubset[A any](left, right Set[A], less func(A, A) bool) bool {\n\trightIndex := 0\n\tfor _, value := range left.Elements {\n\t\tfor rightIndex < len(right.Elements) && less(right.Elements[rightIndex], value) {\n\t\t\trightIndex++\n\t\t}\n\t\tif rightIndex >= len(right.Elements) || less(value, right.Elements[rightIndex]) {\n\t\t\treturn false\n\t\t}\n\t\trightIndex++\n\t}\n\treturn true\n}\n\n// SetEqualBy compares in one pass, since both sides are ordered.\nfunc SetEqualBy[A any](left, right Set[A], equal func(A, A) bool) bool {\n\tif len(left.Elements) != len(right.Elements) {\n\t\treturn false\n\t}\n\tfor index := range left.Elements {\n\t\tif !equal(left.Elements[index], right.Elements[index]) {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn true\n}\n");
  ("string.go", "package teslrt\n\nimport (\n\t\"strings\"\n\t\"unicode/utf8\"\n)\n\n// Tesl's String is Go's string, but Tesl's string INDICES AND LENGTHS ARE CODE\n// POINTS, because the Racket backend's `string-length`, `substring`, and match\n// positions all count Racket chars. Every function here that exposes a length or an\n// index therefore converts, and none of them may use len() or a byte offset as a\n// Tesl-visible number.\n//\n// Two deliberate, documented differences from the Racket backend, both cases where\n// Go's behavior is the defensible one (see roadmap/next/migrate_to_golang.md):\n//\n//   - StringToInt accepts an optional sign followed by decimal digits, and nothing\n//     else. Racket's `string->number` also accepts reader syntax \226\128\148 \"#x1A\" is 26,\n//     \"1/1\" is the exact integer 1 \226\128\148 which is an implementation leak rather than a\n//     language surface.\n//   - StringTrim trims Unicode whitespace (Go's unicode.IsSpace), where Racket's\n//     default `\\s` is ASCII-only. Case mapping is Go's per-rune simple mapping, so\n//     \"\195\159\" uppercases to \"\195\159\" rather than Racket's full-mapping \"SS\".\nfunc StringLength(s string) Int {\n\treturn FromInt64(int64(utf8.RuneCountInString(s)))\n}\n\nfunc StringIsEmpty(s string) bool {\n\treturn s == \"\"\n}\n\nfunc StringStartsWith(s, prefix string) bool {\n\treturn strings.HasPrefix(s, prefix)\n}\n\nfunc StringEndsWith(s, suffix string) bool {\n\treturn strings.HasSuffix(s, suffix)\n}\n\nfunc StringContains(s, sub string) bool {\n\treturn strings.Contains(s, sub)\n}\n\nfunc StringConcat(left, right string) string {\n\treturn left + right\n}\n\n// StringReplace replaces every occurrence, matching Racket's string-replace.\nfunc StringReplace(s, from, to string) string {\n\treturn strings.ReplaceAll(s, from, to)\n}\n\n// StringSlice is a zero-based, code-point-indexed slice with both bounds clamped,\n// so it is total: no index can panic and no bound can be inverted.\nfunc StringSlice(s string, start, end Int) string {\n\trunes := []rune(s)\n\tlength := int64(len(runes))\n\tlo := clampIndex(start, length)\n\thi := clampIndex(end, length)\n\tif hi < lo {\n\t\thi = lo\n\t}\n\treturn string(runes[lo:hi])\n}\n\n// clampIndex pins an arbitrary-precision index into [0, length]. An Int outside\n// int64 range clamps by sign rather than truncating, which a naive conversion\n// would get exactly backwards.\nfunc clampIndex(index Int, length int64) int64 {\n\tvalue, ok := index.Int64()\n\tif !ok {\n\t\tif index.Sign() < 0 {\n\t\t\treturn 0\n\t\t}\n\t\treturn length\n\t}\n\tif value < 0 {\n\t\treturn 0\n\t}\n\tif value > length {\n\t\treturn length\n\t}\n\treturn value\n}\n\nfunc StringToUpper(s string) string {\n\treturn strings.ToUpper(s)\n}\n\nfunc StringToLower(s string) string {\n\treturn strings.ToLower(s)\n}\n\nfunc StringTrim(s string) string {\n\treturn strings.TrimSpace(s)\n}\n\nfunc StringFromInt(value Int) string {\n\treturn value.String()\n}\n\n// StringToInt parses an optional sign followed by decimal digits; anything else is\n// Nothing. Arbitrary precision is preserved.\nfunc StringToInt(s string) Maybe[Int] {\n\tvalue, err := ParseDecimal(s)\n\tif err != nil {\n\t\treturn Nothing[Int]()\n\t}\n\treturn Something(value)\n}\n\n// StringIndexOf reports the first occurrence as a CODE POINT index, not a byte\n// offset \226\128\148 the two differ for any string with a multi-byte rune before the match.\nfunc StringIndexOf(s, sub string) Maybe[Int] {\n\toffset := strings.Index(s, sub)\n\tif offset < 0 {\n\t\treturn Nothing[Int]()\n\t}\n\treturn Something(FromInt64(int64(utf8.RuneCountInString(s[:offset]))))\n}\n\nfunc StringDropPrefix(s, prefix string) string {\n\treturn strings.TrimPrefix(s, prefix)\n}\n\nfunc StringDropSuffix(s, suffix string) string {\n\treturn strings.TrimSuffix(s, suffix)\n}\n\n// StringPadLeft pads to a code-point width using the first rune of pad. A string\n// already at or over the width is returned unchanged, never truncated.\nfunc StringPadLeft(s string, width Int, pad string) string {\n\tfill, count := padding(s, width, pad)\n\tif count <= 0 {\n\t\treturn s\n\t}\n\treturn strings.Repeat(fill, count) + s\n}\n\nfunc StringPadRight(s string, width Int, pad string) string {\n\tfill, count := padding(s, width, pad)\n\tif count <= 0 {\n\t\treturn s\n\t}\n\treturn s + strings.Repeat(fill, count)\n}\n\nfunc padding(s string, width Int, pad string) (string, int) {\n\tfill, size := utf8.DecodeRuneInString(pad)\n\tif size == 0 {\n\t\treturn \"\", 0\n\t}\n\ttarget, ok := width.Int64()\n\tif !ok {\n\t\t// A width beyond int64 cannot be materialised; treat it as no padding\n\t\t// rather than attempting an allocation that would kill the process.\n\t\treturn string(fill), 0\n\t}\n\tcurrent := int64(utf8.RuneCountInString(s))\n\tif target <= current {\n\t\treturn string(fill), 0\n\t}\n\treturn string(fill), int(target - current)\n}\n\nfunc StringRepeat(s string, times Int) string {\n\tcount, ok := times.Int64()\n\tif !ok || count <= 0 {\n\t\treturn \"\"\n\t}\n\treturn strings.Repeat(s, int(count))\n}\n\n// StringReverse reverses by code point, matching Racket's string->list round trip.\nfunc StringReverse(s string) string {\n\trunes := []rune(s)\n\tfor left, right := 0, len(runes)-1; left < right; left, right = left+1, right-1 {\n\t\trunes[left], runes[right] = runes[right], runes[left]\n\t}\n\treturn string(runes)\n}\n\n// StringRequireNonEmpty is Tesl's `String.requireNonEmpty` check: the proof erases,\n// the rejection does not.\nfunc StringRequireNonEmpty(s string) Check[string] {\n\tif s == \"\" {\n\t\treturn Reject[string](400, \"expected a non-empty string\")\n\t}\n\treturn Accept(s)\n}\n");
  ("table.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"sort\"\n\t\"strings\"\n\t\"sync\"\n)\n\n// An in-memory table, the `backend: Memory` store.\n//\n// Rows are held as VALUES, and every read returns a copy of the slice header's contents\n// rather than the table's own storage \226\128\148 the same \"only writers allocate, readers may not\n// alias the store\" rule list.go states, applied here because a table is mutable and long\n// lived where a Tesl list is neither.\n//\n// The mutex is not decoration: an HTTP server serves each request on its own goroutine, so\n// two handlers touching the same table race by construction. The gates run `go test -race`\n// on emitted code, which is what would catch a missing lock.\ntype Table[Row any] struct {\n\tmutex sync.RWMutex\n\trows  []Row\n}\n\nfunc NewTable[Row any]() *Table[Row] {\n\treturn &Table[Row]{}\n}\n\n// TableInsert stores a row, rejecting one whose primary key is already present \226\128\148\n// `conflicts(existing, inserted)` compares the two keys, since their type is known only\n// to the emitter. The Racket memory backend keys its store BY the primary key and raises\n// on a duplicate, so this is parity rather than an extra: a table that silently accepted\n// two rows with one key would answer `selectOne` differently on the two backends.\nfunc TableInsert[Row any](table *Table[Row], entity string, row Row, conflicts func(Row, Row) bool) Row {\n\ttable.mutex.Lock()\n\tdefer table.mutex.Unlock()\n\ttable.insertLocked(entity, row, conflicts)\n\treturn row\n}\n\n// TableInsertMany inserts in order, and a row conflicting with an EARLIER row of the same\n// batch is rejected just as it would be if the two were inserted separately \226\128\148 Racket's\n// insert-many! is a loop over insert-one!.\nfunc TableInsertMany[Row any](table *Table[Row], entity string, rows []Row, conflicts func(Row, Row) bool) struct{} {\n\ttable.mutex.Lock()\n\tdefer table.mutex.Unlock()\n\tfor _, row := range rows {\n\t\ttable.insertLocked(entity, row, conflicts)\n\t}\n\treturn struct{}{}\n}\n\n// The caller holds the write lock.\nfunc (table *Table[Row]) insertLocked(entity string, row Row, conflicts func(Row, Row) bool) {\n\tfor _, existing := range table.rows {\n\t\tif conflicts(existing, row) {\n\t\t\tpanic(fmt.Sprintf(\"insert: entity %s already contains a row with that primary key\", entity))\n\t\t}\n\t}\n\ttable.rows = append(table.rows, row)\n}\n\n// TableSelectOne returns the FIRST row matching, in insertion order. Tesl's `selectOne`\n// yields `Maybe`, so \"no row\" is a value rather than an error.\nfunc TableSelectOne[Row any](table *Table[Row], match func(Row) bool) Maybe[Row] {\n\ttable.mutex.RLock()\n\tdefer table.mutex.RUnlock()\n\tfor _, row := range table.rows {\n\t\tif match(row) {\n\t\t\treturn Something(row)\n\t\t}\n\t}\n\treturn Nothing[Row]()\n}\n\nfunc TableSelect[Row any](table *Table[Row], match func(Row) bool) []Row {\n\ttable.mutex.RLock()\n\tdefer table.mutex.RUnlock()\n\tout := make([]Row, 0, len(table.rows))\n\tfor _, row := range table.rows {\n\t\tif match(row) {\n\t\t\tout = append(out, row)\n\t\t}\n\t}\n\treturn out\n}\n\n// An aggregate walks the rows in place: it needs no copy of them, and on the Memory store\n// it is the whole implementation. On a SQL backend an aggregate must instead become a\n// `SELECT COUNT/SUM/MAX(...) ... WHERE ...` \226\128\148 the work belongs in the database, and the\n// query structure to build it from is the same recovered seed. Nothing here should be\n// carried over to that path.\nfunc TableCount[Row any](table *Table[Row], match func(Row) bool) Int {\n\ttable.mutex.RLock()\n\tdefer table.mutex.RUnlock()\n\tmatched := 0\n\tfor _, row := range table.rows {\n\t\tif match(row) {\n\t\t\tmatched++\n\t\t}\n\t}\n\treturn FromInt64(int64(matched))\n}\n\n// TableSelectRange is `limit` / `offset` without an `order` clause: rows come back in\n// insertion order, which is the order the un-ordered Racket path yields as well. A\n// negative `limit` means \"no limit\".\nfunc TableSelectRange[Row any](table *Table[Row], match func(Row) bool, offset, limit int) []Row {\n\treturn sliceRange(TableSelect(table, match), offset, limit)\n}\n\n// TableSelectSorted is `order by`, plus any `limit`/`offset` applied after the sort.\n// `less` reports strictly-before, and the sort is STABLE, so rows comparing equal keep\n// their insertion order.\nfunc TableSelectSorted[Row any](table *Table[Row], match func(Row) bool, less func(Row, Row) bool, offset, limit int) []Row {\n\trows := TableSelect(table, match)\n\tsort.SliceStable(rows, func(left, right int) bool { return less(rows[left], rows[right]) })\n\treturn sliceRange(rows, offset, limit)\n}\n\n// TableSelectOneSorted is `selectOne \226\128\166 order \226\128\166`: the first row after sorting.\nfunc TableSelectOneSorted[Row any](table *Table[Row], match func(Row) bool, less func(Row, Row) bool) Maybe[Row] {\n\trows := TableSelectSorted(table, match, less, 0, 1)\n\tif len(rows) == 0 {\n\t\treturn Nothing[Row]()\n\t}\n\treturn Something(rows[0])\n}\n\n// TableFold is the scalar aggregate (`selectSum`): the matching rows' projections\n// combined left to right from `zero`, so an empty table yields `zero` \226\128\148 the same answer\n// SQL's SUM-over-no-rows gives once Tesl has typed it as the column type.\nfunc TableFold[Row any, Value any](table *Table[Row], match func(Row) bool, project func(Row) Value, combine func(Value, Value) Value, zero Value) Value {\n\ttable.mutex.RLock()\n\tdefer table.mutex.RUnlock()\n\ttotal := zero\n\tfor _, row := range table.rows {\n\t\tif match(row) {\n\t\t\ttotal = combine(total, project(row))\n\t\t}\n\t}\n\treturn total\n}\n\n// TableExtreme is `selectMax` / `selectMin`: the projection of the matching rows that no\n// other beats, where `better(candidate, best)` reports that the candidate wins.\n//\n// The answer is a `Maybe`: with no matching row there is no value of the column's type to\n// return, and unlike `selectSum` there is no identity to fall back on. Racket's aggregates\n// answer `Nothing` in the same case.\nfunc TableExtreme[Row any, Value any](table *Table[Row], match func(Row) bool, project func(Row) Value, better func(Value, Value) bool) Maybe[Value] {\n\ttable.mutex.RLock()\n\tdefer table.mutex.RUnlock()\n\tvar best Value\n\tfound := false\n\tfor _, row := range table.rows {\n\t\tif !match(row) {\n\t\t\tcontinue\n\t\t}\n\t\tcandidate := project(row)\n\t\tif !found || better(candidate, best) {\n\t\t\tbest = candidate\n\t\t\tfound = true\n\t\t}\n\t}\n\tif !found {\n\t\treturn Nothing[Value]()\n\t}\n\treturn Something(best)\n}\n\n// SqlLike is the `like` / `ilike` predicate: `%` matches any run of characters and `_`\n// exactly one, and the whole value must match. It is a direct matcher rather than a\n// translation to a regular expression, so a pattern can never inject one.\nfunc SqlLike(value, pattern string, foldCase bool) bool {\n\tif foldCase {\n\t\tvalue = strings.ToLower(value)\n\t\tpattern = strings.ToLower(pattern)\n\t}\n\ttext := []rune(value)\n\tglob := []rune(pattern)\n\t// Standard backtracking match: `star` remembers where the last `%` was, so a failure\n\t// after it resumes by letting that `%` consume one more character.\n\ttextAt, globAt, star, retry := 0, 0, -1, 0\n\tfor textAt < len(text) {\n\t\tswitch {\n\t\tcase globAt < len(glob) && (glob[globAt] == '_' || glob[globAt] == text[textAt]):\n\t\t\ttextAt++\n\t\t\tglobAt++\n\t\tcase globAt < len(glob) && glob[globAt] == '%':\n\t\t\tstar = globAt\n\t\t\tglobAt++\n\t\t\tretry = textAt\n\t\tcase star >= 0:\n\t\t\tglobAt = star + 1\n\t\t\tretry++\n\t\t\ttextAt = retry\n\t\tdefault:\n\t\t\treturn false\n\t\t}\n\t}\n\tfor globAt < len(glob) && glob[globAt] == '%' {\n\t\tglobAt++\n\t}\n\treturn globAt == len(glob)\n}\n\nfunc sliceRange[Row any](rows []Row, offset, limit int) []Row {\n\tif offset >= len(rows) {\n\t\treturn []Row{}\n\t}\n\trows = rows[offset:]\n\tif limit >= 0 && limit < len(rows) {\n\t\trows = rows[:limit]\n\t}\n\treturn rows\n}\n\n// TableDelete removes every matching row. `delete` is a statement in Tesl, so the count\n// goes nowhere; TableDeleteCount is the form that reports it.\nfunc TableDelete[Row any](table *Table[Row], match func(Row) bool) struct{} {\n\tTableDeleteCount(table, match)\n\treturn struct{}{}\n}\n\nfunc TableDeleteCount[Row any](table *Table[Row], match func(Row) bool) Int {\n\ttable.mutex.Lock()\n\tdefer table.mutex.Unlock()\n\tkept := make([]Row, 0, len(table.rows))\n\tremoved := 0\n\tfor _, row := range table.rows {\n\t\tif match(row) {\n\t\t\tremoved++\n\t\t\tcontinue\n\t\t}\n\t\tkept = append(kept, row)\n\t}\n\ttable.rows = kept\n\treturn FromInt64(int64(removed))\n}\n\n// TableUpdate replaces every matching row with the result of `apply`. Like `delete`, a\n// plain `update` is a statement, so nothing is reported back.\nfunc TableUpdate[Row any](table *Table[Row], match func(Row) bool, apply func(Row) Row) struct{} {\n\ttable.mutex.Lock()\n\tdefer table.mutex.Unlock()\n\tfor index, row := range table.rows {\n\t\tif match(row) {\n\t\t\ttable.rows[index] = apply(row)\n\t\t}\n\t}\n\treturn struct{}{}\n}\n\n// TableUpdateReturnOne is `updateAndReturnOne`: it yields the FIRST updated row, and\n// traps when the predicate matched nothing \226\128\148 Racket takes the `car` of the updated rows,\n// which errors on an empty list, so \"no row updated\" is a failure on both backends rather\n// than a zero value.\nfunc TableUpdateReturnOne[Row any](table *Table[Row], match func(Row) bool, apply func(Row) Row) Row {\n\ttable.mutex.Lock()\n\tdefer table.mutex.Unlock()\n\tfor index, row := range table.rows {\n\t\tif match(row) {\n\t\t\tupdated := apply(row)\n\t\t\ttable.rows[index] = updated\n\t\t\treturn updated\n\t\t}\n\t}\n\tpanic(\"updateAndReturnOne: no row matched\")\n}\n\n// TableTruncate empties the table, for a test that wants a fresh store.\nfunc TableTruncate[Row any](table *Table[Row]) {\n\ttable.mutex.Lock()\n\tdefer table.mutex.Unlock()\n\ttable.rows = nil\n}\n");
  ("telemetry.go", "package teslrt\n\nimport (\n\t\"fmt\"\n\t\"os\"\n\t\"sort\"\n\t\"strings\"\n\t\"sync\"\n)\n\n// `Tesl.Telemetry`: the ambient signals \226\128\148 a telemetry EVENT (`telemetry \"name\" { \226\128\166 }`) and the\n// three metric instruments (`counter`, `histogram`, `gauge`).\n//\n// Ambient by design, and that is a language decision rather than an implementation shortcut: an\n// observability call that needed a capability would either be threaded through every signature\n// or be left out of the code that most needs it. So there is nothing to grant and nothing to\n// pass; what a program configures is the SINK, once, in `main`.\n//\n// WHAT THIS RECORDS AND WHAT IT DOES NOT EXPORT. Events and metrics accumulate in process, and\n// with `console True` they are written to stderr. OTLP export \226\128\148 the wire protocol, the batching\n// exporter, the `/v1/metrics` endpoint, and the span tree the Racket runtime builds around every\n// request and outbound call \226\128\148 is NOT here yet. That is a deliberate boundary rather than an\n// oversight: the corpus configures `endpoint \"in-memory\"`, every assertion in it is that\n// telemetry does not disturb the program's own answers, and an exporter that silently dropped\n// spans would be worse than one that is honestly absent. A program that needs the wire today\n// runs on the Racket backend.\n//\n// The recorder is guarded by one mutex. Metrics are per (name, attribute-set), which is what\n// makes a counter cumulative rather than per-call, and the attribute set is normalised to a\n// sorted key so `{a=1,b=2}` and `{b=2,a=1}` are one series.\ntype TelemetryEvent struct {\n\tService     string\n\tEndpoint    string\n\tMessage     string\n\tAttributes  []Tuple2[string, string]\n\tTimestampMs int64\n}\n\n// MetricKind distinguishes the three instruments. A counter SUMS, a gauge keeps the LAST value,\n// and a histogram keeps the shape of a distribution (count/sum/min/max) \226\128\148 not the bucket\n// boundaries an OTLP histogram carries, which belong with the exporter.\ntype MetricKind int\n\nconst (\n\tMetricCounter MetricKind = iota\n\tMetricHistogram\n\tMetricGauge\n)\n\n// MetricSeries is one instrument at one attribute set.\ntype MetricSeries struct {\n\tName       string\n\tKind       MetricKind\n\tAttributes []Tuple2[string, string]\n\tCount      int64\n\tSum        float64\n\tLast       float64\n\tMin        float64\n\tMax        float64\n}\n\nvar telemetry = struct {\n\tmutex             sync.Mutex\n\tservice           string\n\tendpoint          string\n\tconsole           bool\n\tmetricsEnabled    bool\n\ttracesEnabled     bool\n\ttraceRatio        float64\n\tmetricsIntervalMs int\n\tevents            []TelemetryEvent\n\tseries            map[string]*MetricSeries\n}{service: \"tesl\", metricsEnabled: true, traceRatio: 1.0, series: map[string]*MetricSeries{}}\n\n// InitTelemetry is `initTelemetry service \226\128\166 endpoint \226\128\166 console \226\128\166`: it configures the sink, once,\n// from `main`. Calling it twice replaces the configuration and clears what was recorded, which\n// is what a fresh process would have.\nfunc InitTelemetry(service, endpoint string, console, metrics, traces bool,\n\tmetricsIntervalMs int, traceRatio float64) struct{} {\n\ttelemetry.mutex.Lock()\n\tdefer telemetry.mutex.Unlock()\n\tif service != \"\" {\n\t\ttelemetry.service = service\n\t}\n\ttelemetry.endpoint = endpoint\n\ttelemetry.console = console\n\ttelemetry.metricsEnabled = metrics\n\ttelemetry.tracesEnabled = traces\n\ttelemetry.metricsIntervalMs = metricsIntervalMs\n\ttelemetry.traceRatio = traceRatio\n\ttelemetry.events = nil\n\ttelemetry.series = map[string]*MetricSeries{}\n\tif endpoint != \"\" && endpoint != \"in-memory\" {\n\t\t// Said once, at configuration time, rather than silently dropping every span and metric\n\t\t// for the lifetime of the process.\n\t\tfmt.Fprintf(os.Stderr,\n\t\t\t\"tesl: telemetry endpoint %q is configured, but this runtime records in process only \"+\n\t\t\t\t\"\226\128\148 OTLP export is not implemented on the Go backend yet.\\n\", endpoint)\n\t}\n\treturn struct{}{}\n}\n\n// Telemetry is the `telemetry \"name\" { key = value }` block: one event, with its attributes\n// already rendered to text by the emitter (which knows each field's type, and renders a `secret`\n// as its redaction rather than its payload).\nfunc Telemetry(message string, attributes []Tuple2[string, string]) struct{} {\n\tevent := TelemetryEvent{\n\t\tService:     telemetry.service,\n\t\tEndpoint:    telemetry.endpoint,\n\t\tMessage:     message,\n\t\tAttributes:  attributes,\n\t\tTimestampMs: telemetryNowMillis(),\n\t}\n\ttelemetry.mutex.Lock()\n\ttelemetry.events = append(telemetry.events, event)\n\tconsole := telemetry.console\n\ttelemetry.mutex.Unlock()\n\tif console {\n\t\tfmt.Fprintf(os.Stderr, \"[telemetry] %s %s%s\\n\", event.Service, message,\n\t\t\trenderAttributes(attributes))\n\t}\n\treturn struct{}{}\n}\n\n// telemetryNowMillis is the event timestamp. An Int wider than int64 cannot be a wall clock, so\n// the conversion is total here in a way it is not in general.\nfunc telemetryNowMillis() int64 {\n\tmillis, _ := NowMillis().Value.Int64()\n\treturn millis\n}\n\nfunc renderAttributes(attributes []Tuple2[string, string]) string {\n\tif len(attributes) == 0 {\n\t\treturn \"\"\n\t}\n\tparts := make([]string, 0, len(attributes))\n\tfor _, attribute := range attributes {\n\t\tparts = append(parts, attribute.Tuple2First+\"=\"+attribute.Tuple2Second)\n\t}\n\treturn \" {\" + strings.Join(parts, \", \") + \"}\"\n}\n\n// seriesKey is the identity of a metric series: its name plus its attribute set, normalised so\n// the same attributes in a different order are the same series.\nfunc seriesKey(name string, kind MetricKind, attributes []Tuple2[string, string]) string {\n\tpairs := make([]string, 0, len(attributes))\n\tfor _, attribute := range attributes {\n\t\tpairs = append(pairs, attribute.Tuple2First+\"\\x00\"+attribute.Tuple2Second)\n\t}\n\tsort.Strings(pairs)\n\treturn fmt.Sprintf(\"%d\\x00%s\\x00%s\", kind, name, strings.Join(pairs, \"\\x01\"))\n}\n\nfunc recordMetric(name string, kind MetricKind, value float64,\n\tattributes []Tuple2[string, string]) {\n\ttelemetry.mutex.Lock()\n\tdefer telemetry.mutex.Unlock()\n\tif !telemetry.metricsEnabled {\n\t\treturn\n\t}\n\tkey := seriesKey(name, kind, attributes)\n\tseries, found := telemetry.series[key]\n\tif !found {\n\t\tseries = &MetricSeries{Name: name, Kind: kind, Attributes: attributes,\n\t\t\tMin: value, Max: value}\n\t\ttelemetry.series[key] = series\n\t}\n\tseries.Count++\n\tseries.Sum += value\n\tseries.Last = value\n\tif value < series.Min {\n\t\tseries.Min = value\n\t}\n\tif value > series.Max {\n\t\tseries.Max = value\n\t}\n}\n\n// Counter is `counter \"name\" delta attrs`: CUMULATIVE, which is why the series is kept rather\n// than the call. A negative delta is allowed for the same reason Racket allows it \226\128\148 the\n// instrument records what the program says.\nfunc Counter(name string, delta Int, attributes []Tuple2[string, string]) struct{} {\n\trecordMetric(name, MetricCounter, delta.Float64(), attributes)\n\treturn struct{}{}\n}\n\nfunc Histogram(name string, value float64, attributes []Tuple2[string, string]) struct{} {\n\trecordMetric(name, MetricHistogram, value, attributes)\n\treturn struct{}{}\n}\n\nfunc Gauge(name string, value float64, attributes []Tuple2[string, string]) struct{} {\n\trecordMetric(name, MetricGauge, value, attributes)\n\treturn struct{}{}\n}\n\n// \226\148\128\226\148\128 Inspection seams \226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\226\148\128\n//\n// Not Tesl-surface names: they exist so the runtime's own tests can assert what was recorded,\n// and so a program that has shed Tesl can read its own telemetry without an exporter.\n\nfunc TelemetryEvents() []TelemetryEvent {\n\ttelemetry.mutex.Lock()\n\tdefer telemetry.mutex.Unlock()\n\tout := make([]TelemetryEvent, len(telemetry.events))\n\tcopy(out, telemetry.events)\n\treturn out\n}\n\n// MetricSeriesSnapshot is every series, in a deterministic order (by name, then by key), so a\n// test or a dump reads the same way twice.\nfunc MetricSeriesSnapshot() []MetricSeries {\n\ttelemetry.mutex.Lock()\n\tdefer telemetry.mutex.Unlock()\n\tkeys := make([]string, 0, len(telemetry.series))\n\tfor key := range telemetry.series {\n\t\tkeys = append(keys, key)\n\t}\n\tsort.Strings(keys)\n\tout := make([]MetricSeries, 0, len(keys))\n\tfor _, key := range keys {\n\t\tif series := telemetry.series[key]; series != nil {\n\t\t\tout = append(out, *series)\n\t\t}\n\t}\n\tsort.SliceStable(out, func(left, right int) bool { return out[left].Name < out[right].Name })\n\treturn out\n}\n\n// ResetTelemetry clears what was recorded, for a test that asserts on it. The emitted per-test\n// reset calls it for the same reason it truncates tables: one test block's signals must not be\n// another's.\nfunc ResetTelemetry() {\n\ttelemetry.mutex.Lock()\n\tdefer telemetry.mutex.Unlock()\n\ttelemetry.events = nil\n\ttelemetry.series = map[string]*MetricSeries{}\n}\n\n// MillisOf narrows a Tesl `Int` interval to the plain int the recorder keeps. An interval outside\n// int64 is a configuration mistake rather than a duration, so it fails at configuration time.\nfunc MillisOf(value Int) int {\n\tmillis, exact := value.Int64()\n\tif !exact || millis < 0 {\n\t\tpanic(\"initTelemetry: \" + value.String() + \" is not a millisecond interval\")\n\t}\n\treturn int(millis)\n}\n");
  ("time.go", "package teslrt\n\nimport \"time\"\n\n// PosixMillis is Tesl's canonical instant: milliseconds since the Unix epoch, UTC.\n//\n// It is a NEWTYPE over the exact integer, not an int64 \226\128\148 `tesl/time.rkt` defines it as\n// `(define-newtype PosixMillis Integer)` and Racket's integers are exact and unbounded, so\n// arithmetic on a timestamp cannot silently wrap here either. The type lives in the runtime\n// rather than being emitted per module for the reason `Maybe` does: an instant crosses\n// module boundaries, and two packages declaring their own would be different Go types.\ntype PosixMillis struct {\n\tValue Int\n}\n\n// NowMillis reads the clock. Tesl gates this behind the `time` capability, which the\n// checker enforces; nothing about that survives to run time.\nfunc NowMillis() PosixMillis {\n\treturn PosixMillis{Value: FromInt64(time.Now().UnixMilli())}\n}\n\n// PosixToSeconds truncates toward zero, which is what Racket's `quotient` does \226\128\148 NOT floor,\n// so an instant before the epoch rounds up toward it on both backends.\nfunc PosixToSeconds(instant PosixMillis) Int {\n\treturn MustQuo(instant.Value, FromInt64(1000))\n}\n\nfunc SecondsToPosix(seconds Int) PosixMillis {\n\treturn PosixMillis{Value: Mul(seconds, FromInt64(1000))}\n}\n\nfunc AddMs(instant PosixMillis, delta Int) PosixMillis {\n\treturn PosixMillis{Value: Add(instant.Value, delta)}\n}\n\nfunc SubtractMs(instant PosixMillis, delta Int) PosixMillis {\n\treturn PosixMillis{Value: Sub(instant.Value, delta)}\n}\n\n// DiffMs is later minus earlier, in the argument order Tesl uses: `diffMs a b` = b - a.\nfunc DiffMs(earlier, later PosixMillis) Int {\n\treturn Sub(later.Value, earlier.Value)\n}\n\n// DurationMs is how long ago an instant was, clamped at zero \226\128\148 a clock that went backwards\n// must not produce a negative age (Racket clamps with `max` for the same reason).\nfunc DurationMs(past PosixMillis) Int {\n\telapsed := DiffMs(past, NowMillis())\n\tif Compare(elapsed, FromInt64(0)) < 0 {\n\t\treturn FromInt64(0)\n\t}\n\treturn elapsed\n}\n");
  ("tuple.go", "package teslrt\n\n// Tuple2 and Tuple3 are Tesl's anonymous products. They live in the runtime for the\n// same reason Maybe does: a tuple crosses module boundaries, so two emitted packages\n// declaring their own would be incompatible Go types.\n//\n// Unlike Maybe they carry NO tag \226\128\148 a single-variant type has nothing to discriminate,\n// and a tag would be a wasted word in a value used as a lightweight pair. The emitter\n// knows this shape and matches `Tuple2 x y -> \226\128\166` by binding the fields directly\n// instead of switching.\n//\n// Field names are the ones the emitter derives for a constructor's payload\n// (constructor name + field name), so `Tuple2.first p` emits as `p.Tuple2First`.\ntype Tuple2[A any, B any] struct {\n\tTuple2First  A\n\tTuple2Second B\n}\n\ntype Tuple3[A any, B any, C any] struct {\n\tTuple3First  A\n\tTuple3Second B\n\tTuple3Third  C\n}\n");
]
